function initNavigation() {
    const navItems = document.querySelectorAll('.nav-item');
    navItems.forEach(item => {
        item.addEventListener('click', async (e) => {
            e.preventDefault();
            const tabName = item.dataset.tab;
            if (tabName) {
                await window.navigateToTab(tabName);
            }
        });
    });

    const mobNavBtns = document.querySelectorAll('.mobile-nav-btn');
    mobNavBtns.forEach(btn => {
        btn.addEventListener('click', async (e) => {
            e.preventDefault();
            const tabName = btn.dataset.tab;
            if (tabName) {
                await window.navigateToTab(tabName);
            }
        });
    });

    // Mobile FAB button
    const fabBtn = document.getElementById('mobile-fab-btn');
    if (fabBtn) {
        fabBtn.onclick = () => {
            openModal('modal-mobile-quick-actions');
        };
    }

    // Bind all FAB actions
    initMobileFabActions();
}

function initMobileFabActions() {
    // 0. Venta Directa
    const actDirectSale = document.getElementById('fab-act-direct-sale');
    if (actDirectSale) {
        actDirectSale.onclick = () => {
            closeModal('modal-mobile-quick-actions');
            if (window.openDirectSaleModal) {
                window.openDirectSaleModal();
            } else if (window.triggerHeaderNewAction) {
                window.triggerHeaderNewAction('direct-sale');
            }
        };
    }

    // 1. Nuevo Paciente
    const actPatient = document.getElementById('fab-act-patient');
    if (actPatient) {
        actPatient.onclick = () => {
            closeModal('modal-mobile-quick-actions');
            if (typeof window.openPatientModalForNew === 'function') {
                window.openPatientModalForNew();
            } else {
                openModal('modal-patient');
            }
        };
    }

    // 2. Agendar Cita
    const actAppointment = document.getElementById('fab-act-appointment');
    if (actAppointment) {
        actAppointment.onclick = async () => {
            closeModal('modal-mobile-quick-actions');
            await window.openNewAppointmentModal();
        };
    }

    // 3. Nuevo Presupuesto
    const actBudget = document.getElementById('fab-act-budget');
    if (actBudget) {
        actBudget.onclick = async () => {
            closeModal('modal-mobile-quick-actions');
            openModal('modal-select-budget-type');
        };
    }

    // 4. Agregar Evolución
    const actEvolution = document.getElementById('fab-act-evolution');
    if (actEvolution) {
        actEvolution.onclick = async () => {
            closeModal('modal-mobile-quick-actions');
            const activeId = getActivePatientId();
            if (activeId) {
                const sessionPatientId = document.getElementById('session-patient-id');
                if (sessionPatientId) sessionPatientId.value = activeId;
                openModal('modal-session');
            } else {
                await window.navigateToTab('ehr');
                Swal.fire({
                    icon: 'info',
                    title: 'Seleccione un Paciente',
                    text: 'Seleccione un paciente de la lista para registrar una nueva sesión o evolución clínica.'
                });
            }
        };
    }

    // 5. Registrar Gasto
    const actExpense = document.getElementById('fab-act-expense');
    if (actExpense) {
        actExpense.onclick = () => {
            closeModal('modal-mobile-quick-actions');
            const billForm = document.getElementById('form-provider-bill');
            if (billForm) billForm.reset();
            openModal('modal-provider-bill');
        };
    }

    // 6. Registrar Ingreso / Abono
    const actIncome = document.getElementById('fab-act-income');
    if (actIncome) {
        actIncome.onclick = async () => {
            closeModal('modal-mobile-quick-actions');
            const activeId = getActivePatientId();
            if (activeId) {
                const paymentPatientId = document.getElementById('payment-patient-id');
                if (paymentPatientId) paymentPatientId.value = activeId;
                openModal('modal-payment');
            } else {
                await window.navigateToTab('finance');
                Swal.fire({
                    icon: 'info',
                    title: 'Registro de Abonos / Ingresos',
                    text: 'Puede registrar abonos desde la ficha de cada paciente en Historias Clínicas o Cuentas por Cobrar.'
                });
            }
        };
    }

    // 7. Transferencia / Traslado entre Cuentas
    const actTransfer = document.getElementById('fab-act-transfer');
    if (actTransfer) {
        actTransfer.onclick = () => {
            closeModal('modal-mobile-quick-actions');
            openModal('modal-account-transfer');
        };
    }

    // 8. Facturación
    const actBilling = document.getElementById('fab-act-billing');
    if (actBilling) {
        actBilling.onclick = async () => {
            closeModal('modal-mobile-quick-actions');
            await window.navigateToTab('billing');
        };
    }
}

async function updateActivePatientUI(filterText = '') {
    const activeId = getActivePatientId();
    const activePill = document.getElementById('active-patient-bar');
    const activeName = document.getElementById('active-patient-name');
    const odSelect = document.getElementById('od-patient-select');

    const patients = await SupabaseDataService.getPatients();

    const query = filterText.toLowerCase().trim();
    const filteredPatients = patients.filter(p => {
        const name = (p.fullname || '').toLowerCase();
        const ci = (p.id || '').toLowerCase();
        return name.includes(query) || ci.includes(query);
    });

    if (odSelect) {
        odSelect.innerHTML = '<option value="">-- Seleccionar Paciente --</option>';
        filteredPatients.forEach(p => {
            const opt = document.createElement('option');
            opt.value = p.id;
            opt.innerText = `${p.fullname} (${p.id})`;
            if (p.id === activeId) opt.selected = true;
            odSelect.appendChild(opt);
        });

        const newOpt = document.createElement('option');
        newOpt.value = 'new';
        newOpt.innerText = '➕ Registrar Nuevo Paciente...';
        odSelect.appendChild(newOpt);
    }

    if (activeId) {
        const patient = patients.find(p => p.id === activeId);
        if (patient) {
            activePill.classList.remove('hidden');
            let tagBadge = '';
            const pTagName = patient.tagName || (patient.metadata && patient.metadata.tagName);
            const pTagColor = patient.tagColor || (patient.metadata && patient.metadata.tagColor) || '#0d9488';
            const pTagRule = patient.tagRule || (patient.metadata && patient.metadata.tagRule);
            if (pTagName) {
                const rText = pTagRule?.type === 'discount' ? `-${pTagRule.value}%` : (pTagRule?.type === 'surcharge' ? `+${pTagRule.value}%` : (pTagRule?.type === 'exonerated' ? '100% Exon.' : ''));
                tagBadge = ` <span style="font-size: 0.75rem; padding: 2px 6px; border-radius: 4px; background: ${pTagColor}25; color: ${pTagColor}; font-weight: 700; margin-left: 6px;">🏷️ ${pTagName} ${rText ? `(${rText})` : ''}</span>`;
            }
            activeName.innerHTML = `${patient.fullname}${tagBadge}`;
            return;
        }
    }

    activePill.classList.add('hidden');
    activeName.innerText = 'Ninguno';
}

async function renderPatientSearchResults(query) {
    const resultsContainer = document.getElementById('od-patient-search-results');
    if (!resultsContainer) return;

    const trimmedQuery = query.toLowerCase().trim();
    if (!trimmedQuery) {
        resultsContainer.style.display = 'none';
        return;
    }

    const patients = await SupabaseDataService.getPatients();
    const filtered = patients.filter(p => {
        const name = (p.fullname || '').toLowerCase();
        const ci = (p.id || '').toLowerCase();
        const tag = (p.tagName || (p.metadata && p.metadata.tagName) || '').toLowerCase();
        return name.includes(trimmedQuery) || ci.includes(trimmedQuery) || tag.includes(trimmedQuery);
    });

    if (filtered.length === 0) {
        resultsContainer.innerHTML = '<div style="padding: 10px 15px; color: var(--text-muted); font-size: 0.88rem; text-align: left;">No se encontraron pacientes</div>';
        resultsContainer.style.display = 'block';
        return;
    }

    resultsContainer.innerHTML = '';
    filtered.forEach(p => {
        const item = document.createElement('div');
        item.className = 'search-result-item';
        const pTagName = p.tagName || (p.metadata && p.metadata.tagName);
        const pTagColor = p.tagColor || (p.metadata && p.metadata.tagColor) || '#0d9488';
        const tagHtml = pTagName ? `<span style="font-size: 0.72rem; padding: 2px 6px; border-radius: 4px; background: ${pTagColor}20; color: ${pTagColor}; border: 1px solid ${pTagColor}40; font-weight: 700; margin-left: 6px;">🏷️ ${pTagName}</span>` : '';
        item.innerHTML = `<strong>${p.fullname}</strong> <span style="font-size: 0.8rem; color: var(--text-muted); margin-left: 5px;">(${p.id})</span>${tagHtml}`;
        item.onclick = async () => {
            document.getElementById('od-patient-search-input').value = p.fullname;
            resultsContainer.style.display = 'none';
            await window.selectPatientAndLoadApprovedBudget(p.id);
        };
        resultsContainer.appendChild(item);
    });
    resultsContainer.style.display = 'block';
}

async function saveCurrentBudgetAsDraft(patientIdToSave) {
    if (!patientIdToSave) return;
    try {
        const patients = await SupabaseDataService.getPatients();
        const patient = patients.find(p => String(p.id) === String(patientIdToSave));
        if (!patient) return;

        const odData = window.odontogram ? window.odontogram.getData() : {};
        const discInput = document.getElementById('budget-discount-input');
        const notesInput = document.getElementById('budget-notes');
        const termsInput = document.getElementById('payment-mode-select');
        const payMethodSelect = document.getElementById('budget-payment-method');
        const consentInput = document.getElementById('budget-consent-text');

        const docSig = (window.doctorSigPad && !window.doctorSigPad.isEmpty()) ? window.doctorSigPad.toDataURL() : null;
        const patSig = (window.patientSigPad && !window.patientSigPad.isEmpty()) ? window.patientSigPad.toDataURL() : (patient.metadata?.patientSignature || null);

        const discountPct = parseFloat(discInput ? discInput.value : 0) || 0;
        const notes = notesInput ? notesInput.value : '';
        const paymentMethod = payMethodSelect ? payMethodSelect.value : 'pagomovil';
        const paymentTerms = termsInput ? termsInput.value : 'Contado';
        const consentText = consentInput ? (consentInput.value || consentInput.innerText) : '';

        let subtotalUSD = 0;
        (currentBudgetItems || []).forEach(item => {
            subtotalUSD += (parseFloat(item.price) || 0);
        });
        const discountAmountUSD = subtotalUSD * (discountPct / 100);
        const totalUSD = Math.max(0, subtotalUSD - discountAmountUSD);
        const rate = typeof getExchangeRate === 'function' ? getExchangeRate() : 1;

        const budgetId = activeEditingBudgetId || `PRE-${Date.now().toString().slice(-6)}`;

        const budgetObj = {
            id: budgetId,
            patientId: patientIdToSave,
            invoiceDate: new Date().toISOString().split('T')[0],
            paymentMethod: paymentMethod,
            paymentTerms: paymentTerms,
            currency: 'REF',
            items: (currentBudgetItems || []).map(item => ({
                tooth: item.tooth,
                face: item.face || 'Gnl',
                serviceCode: item.serviceCode || item.code || '',
                name: item.name,
                price: parseFloat(item.price) || 0,
                specialist: item.specialist || patient.assignedDoctor || 'Dr. Rodrigo Navas'
            })),
            subtotal: subtotalUSD,
            discountPct: discountPct,
            discountUSD: discountAmountUSD,
            totalRef: totalUSD,
            totalUSD: totalUSD,
            totalBcv: totalUSD * rate,
            status: 'Borrador',
            footerText: notes,
            doctorSignature: docSig,
            patientSignature: patSig,
            odontogramData: odData,
            metadata: {
                consentText: consentText,
                discountPct: discountPct,
                doctorSignature: docSig,
                patientSignature: patSig
            }
        };

        await SupabaseDataService.saveInvoice(budgetObj);

        // Also persist in patient draft metadata without polluting official EHR odontogram
        if (!patient.metadata) patient.metadata = {};
        patient.metadata.draftOdontogramData = odData;
        patient.metadata.draftBudget = {
            id: budgetId,
            items: currentBudgetItems || [],
            discountPct: discountPct,
            notes: notes,
            terms: paymentTerms,
            paymentMethod: paymentMethod,
            consentText: consentText,
            doctorSignature: docSig,
            patientSignature: patSig
        };
        await SupabaseDataService.savePatient(patient);
    } catch(err) {
        console.error("Error saving budget draft:", err);
    }
}

window.selectPatientAndLoadApprovedBudget = async function(patientId) {
    const currentActiveId = getActivePatientId();

    // Check if there are unsaved budget items for the currently active patient before switching
    if (currentActiveId && String(currentActiveId) !== String(patientId) && currentBudgetItems && currentBudgetItems.length > 0) {
        const patients = await SupabaseDataService.getPatients();
        const prevPatient = patients.find(p => String(p.id) === String(currentActiveId));
        const prevPatientName = prevPatient ? prevPatient.fullname : `Paciente (${currentActiveId})`;

        // Check if the current budget is already an approved budget
        const invoices = await SupabaseDataService.getInvoices();
        const existingInvoice = activeEditingBudgetId ? invoices.find(inv => String(inv.id) === String(activeEditingBudgetId)) : null;
        const isAlreadyApproved = existingInvoice && (String(existingInvoice.status).toLowerCase() === 'aprobado' || String(existingInvoice.status).toLowerCase() === 'approved' || String(existingInvoice.status).toLowerCase() === 'completada' || String(existingInvoice.status).toLowerCase() === 'finalizado');

        if (!isAlreadyApproved || !activeEditingBudgetId) {
            const result = await Swal.fire({
                title: `<i class="fa-solid fa-triangle-exclamation text-amber" style="color: #f59e0b; margin-right: 8px;"></i> Presupuesto no guardado`,
                html: `
                    <div style="text-align: left; font-size: 0.95rem; line-height: 1.5; color: var(--text-main, #334155);">
                        <div style="background: rgba(245, 158, 11, 0.1); border-left: 4px solid #f59e0b; padding: 10px 14px; border-radius: 6px; margin-bottom: 12px;">
                            Estás trabajando en un presupuesto para <strong>${prevPatientName}</strong> con <strong>${currentBudgetItems.length}</strong> servicio(s) que aún no ha sido formalmente guardado.
                        </div>
                        <p style="margin: 0; color: var(--text-muted, #64748b);">¿Deseas guardar este presupuesto como borrador antes de cambiar de paciente?</p>
                    </div>
                `,
                icon: 'warning',
                showCancelButton: true,
                showDenyButton: true,
                confirmButtonText: '<i class="fa-solid fa-floppy-disk"></i> Guardar como Borrador',
                denyButtonText: '<i class="fa-solid fa-trash-can"></i> Descartar y Cambiar',
                cancelButtonText: 'Cancelar',
                confirmButtonColor: '#0d9488',
                denyButtonColor: '#e11d48',
                cancelButtonColor: '#64748b',
                focusCancel: true
            });

            if (result.isDismissed) {
                // Cancel: keep current patient and restore UI
                const searchInput = document.getElementById('od-patient-search-input');
                if (searchInput && prevPatient) {
                    searchInput.value = prevPatient.fullname;
                }
                const selectDropdown = document.getElementById('od-patient-select');
                if (selectDropdown) {
                    selectDropdown.value = currentActiveId;
                }
                return;
            }

            if (result.isConfirmed) {
                // Save as draft
                await saveCurrentBudgetAsDraft(currentActiveId);
                Swal.fire({
                    icon: 'success',
                    title: 'Guardado como Borrador',
                    text: `El presupuesto de ${prevPatientName} se guardó exitosamente.`,
                    timer: 1500,
                    showConfirmButton: false
                });
            } else if (result.isDenied) {
                // Discard unsaved changes
                currentBudgetItems = [];
                activeEditingBudgetId = null;
            }
        }
    }

    // Ensure subview is editor
    localStorage.setItem('dental_odontogram_subview', 'editor');
    document.documentElement.setAttribute('data-odontogram-subview', 'editor');
    const listContainer = document.getElementById('odontogram-list-container');
    const editorContainer = document.getElementById('odontogram-editor-container');
    const medEditorContainer = document.getElementById('medical-budget-editor-container');
    if (listContainer) listContainer.classList.add('hidden');
    if (medEditorContainer) medEditorContainer.classList.add('hidden');
    if (editorContainer) editorContainer.classList.remove('hidden');

    const navOdontogram = document.querySelector('.nav-item[data-tab="odontogram"]') || document.getElementById('mob-nav-odontogram');
    if (navOdontogram && !navOdontogram.classList.contains('active')) {
        navOdontogram.click();
    }

    if (!patientId) {
        setActivePatientId(null);
        activeEditingBudgetId = null;
        currentBudgetItems = [];
        if (window.odontogram) window.odontogram.setData({});
        if (window.patientSigPad) window.patientSigPad.clear();
        const searchInput = document.getElementById('od-patient-search-input');
        if (searchInput) searchInput.value = '';
        await renderOdontogramView();
        renderBudgetTable();
        return;
    }

    setActivePatientId(patientId);

    // 1. Consultar si este paciente tiene un presupuesto en invoices (Aprobado o Borrador)
    const invoices = await SupabaseDataService.getInvoices();
    const patientInvoices = invoices.filter(inv => String(inv.patientId) === String(patientId));
    const approvedBudget = patientInvoices.find(inv => (String(inv.status).toLowerCase() === 'aprobado' || String(inv.status).toLowerCase() === 'approved' || String(inv.status).toLowerCase() === 'completada' || String(inv.status).toLowerCase() === 'finalizado'));
    const latestBudget = approvedBudget || patientInvoices.sort((a, b) => new Date(b.invoiceDate || b.createdAt || 0) - new Date(a.invoiceDate || a.createdAt || 0))[0];

    if (latestBudget && window.loadBudgetIntoEditor) {
        await window.loadBudgetIntoEditor(latestBudget.id);
    } else {
        // Si no tiene presupuesto registrado en invoices: cargar borrador en metadata si existe
        const patients = await SupabaseDataService.getPatients();
        const p = patients.find(pat => String(pat.id) === String(patientId));
        activeEditingBudgetId = (p?.metadata?.draftBudget && p.metadata.draftBudget.id) || null;
        currentBudgetItems = (p?.metadata?.draftBudget && Array.isArray(p.metadata.draftBudget.items))
            ? [...p.metadata.draftBudget.items]
            : [];
        const draftOdData = (p?.metadata && p.metadata.draftOdontogramData) || (p?.odontogramData) || {};
        if (window.patientSigPad) {
            window.patientSigPad.clear();
            if (p?.metadata?.patientSignature) {
                try { window.patientSigPad.loadFromDataURL(p.metadata.patientSignature); } catch(e){}
            }
        }
        await renderOdontogramView();
        if (window.odontogram && Object.keys(draftOdData).length > 0) {
            window.odontogram.setData(draftOdData);
        }

        // Auto-aplicar regla de convenio / etiqueta del paciente si no hay borrador con descuento propio
        const discInput = document.getElementById('budget-discount-input');
        if (discInput && p) {
            const rule = p.tagRule || (p.metadata && p.metadata.tagRule);
            if (rule && rule.type === 'discount') {
                discInput.value = parseFloat(rule.value) || 0;
            } else if (rule && rule.type === 'exonerated') {
                discInput.value = 100;
            } else if (!p?.metadata?.draftBudget) {
                discInput.value = 0;
            }
        }

        renderBudgetTable();
    }
};

window.activeBudgetCategoryFilter = window.activeBudgetCategoryFilter || 'all';

window.filterBudgetCategory = function(cat, btn) {
    window.activeBudgetCategoryFilter = cat;
    const container = document.getElementById('odontogram-list-container');
    if (container) {
        container.querySelectorAll('.filter-btn').forEach(b => {
            if (b.id && b.id.startsWith('filter-cat-')) b.classList.remove('active');
        });
    }
    if (btn) btn.classList.add('active');
    renderBudgetListView();
};

async function renderBudgetListView(forceRefresh = false) {
    localStorage.setItem('dental_odontogram_subview', 'list');
    document.documentElement.setAttribute('data-odontogram-subview', 'list');
    const listContainer = document.getElementById('odontogram-list-container');
    const editorContainer = document.getElementById('odontogram-editor-container');
    const medEditorContainer = document.getElementById('medical-budget-editor-container');
    if (listContainer) listContainer.classList.remove('hidden');
    if (editorContainer) editorContainer.classList.add('hidden');
    if (medEditorContainer) medEditorContainer.classList.add('hidden');

    const searchInput = document.getElementById('budget-search-input');
    const statusFilter = document.getElementById('budget-status-filter');
    const tableBody = document.getElementById('budget-list-table-body');
    if (!tableBody) return;

    const invoices = await SupabaseDataService.getInvoices(forceRefresh);
    let budgets = invoices.filter(inv => inv.id && inv.id.startsWith('PRE-'));

    // Calcular contadores por área clínica
    let countAll = budgets.length;
    let countDental = 0;
    let countMed = 0;
    let countXray = 0;
    let countLab = 0;
    let countProc = 0;

    budgets.forEach(b => {
        const cat = b.category || 'Odontología';
        if (cat === 'Odontología') countDental++;
        else if (cat === 'Consultas Médicas' || cat.includes('Consulta')) countMed++;
        else if (cat === 'Rayos X & Imagenología' || cat.includes('Rayos') || cat.includes('Imagen')) countXray++;
        else if (cat === 'Laboratorio Clínico' || cat.includes('Laboratorio')) countLab++;
        else if (cat === 'Procedimientos Ambulatorios' || cat.includes('Procedimiento')) countProc++;
        else countDental++;
    });

    const elAll = document.getElementById('count-cat-all'); if (elAll) elAll.innerText = countAll;
    const elDental = document.getElementById('count-cat-dental'); if (elDental) elDental.innerText = countDental;
    const elMed = document.getElementById('count-cat-med'); if (elMed) elMed.innerText = countMed;
    const elXray = document.getElementById('count-cat-xray'); if (elXray) elXray.innerText = countXray;
    const elLab = document.getElementById('count-cat-lab'); if (elLab) elLab.innerText = countLab;
    const elProc = document.getElementById('count-cat-proc'); if (elProc) elProc.innerText = countProc;

    // Ordenar por orden de llegada: El último creado SIEMPRE de primero
    budgets.sort((a, b) => {
        const timeA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
        const timeB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
        if (timeA !== timeB) return timeB - timeA;

        const dateA = a.invoiceDate ? new Date(a.invoiceDate).getTime() : 0;
        const dateB = b.invoiceDate ? new Date(b.invoiceDate).getTime() : 0;
        if (dateA !== dateB) return dateB - dateA;

        const idNumA = parseInt(String(a.id).replace(/[^0-9]/g, '')) || 0;
        const idNumB = parseInt(String(b.id).replace(/[^0-9]/g, '')) || 0;
        return idNumB - idNumA;
    });

    if (searchInput && !searchInput.oninput) {
        searchInput.oninput = () => drawTable();
    }
    if (statusFilter && !statusFilter.onchange) {
        statusFilter.onchange = () => drawTable();
    }

    drawTable();

    async function drawTable() {
        const query = searchInput ? searchInput.value.toLowerCase().trim() : '';
        const status = statusFilter ? statusFilter.value : 'all';

        const patients = await SupabaseDataService.getPatients();

        let filtered = budgets.filter(b => {
            const patient = patients.find(p => p.id === b.patientId);
            const patientName = patient ? patient.fullname.toLowerCase() : '';
            const spec = b.items && b.items[0] && b.items[0].specialist ? b.items[0].specialist.toLowerCase() : '';
            const docName = (b.doctor || '').toLowerCase();
            const catName = (b.category || '').toLowerCase();
            const matchText = b.id.toLowerCase().includes(query) || patientName.includes(query) || spec.includes(query) || docName.includes(query) || catName.includes(query);

            if (status === 'all') return matchText;
            if (status === 'Presupuesto') return matchText && b.status !== 'Aprobado' && b.status !== 'Facturado';
            if (status === 'Aprobado') return matchText && b.status === 'Aprobado';
            if (status === 'Facturado') return matchText && b.status === 'Facturado';
            return matchText;
        });

        // Filtrar por categoría / especialidad seleccionada
        if (window.activeBudgetCategoryFilter && window.activeBudgetCategoryFilter !== 'all') {
            const selCat = window.activeBudgetCategoryFilter;
            if (selCat === 'Odontología') {
                filtered = filtered.filter(b => !b.category || b.category === 'Odontología');
            } else {
                filtered = filtered.filter(b => b.category === selCat || (b.category && b.category.includes(selCat.substring(0, 6))));
            }
        }

        tableBody.innerHTML = '';
        if (filtered.length === 0) {
            tableBody.innerHTML = '<tr><td colspan="8" class="text-center text-muted" style="padding: 30px;">No se encontraron presupuestos en este filtro.</td></tr>';
            return;
        }

        filtered.forEach(b => {
            const patient = patients.find(p => p.id === b.patientId);
            const patientName = patient ? patient.fullname : 'Desconocido';
            const spec = b.items && b.items[0] && b.items[0].specialist ? b.items[0].specialist : (b.doctor || 'Especialista');
            
            const isApproved = b.status === 'Aprobado';
            const isFacturado = b.status === 'Facturado';
            const badgeClass = isFacturado ? 'badge-tag blue' : (isApproved ? 'badge-tag green' : 'badge-tag orange');
            const statusLabel = isFacturado ? 'Finalizado' : (isApproved ? 'Aprobado' : 'Borrador');

            // Category badge
            let categoryBadge = '';
            const cat = b.category || 'Odontología';
            if (cat === 'Odontología') {
                categoryBadge = `<span class="badge-tag green" style="font-size:0.74rem; font-weight:700;"><i class="fa-solid fa-tooth"></i> Odontología</span>`;
            } else if (cat === 'Consultas Médicas' || cat.includes('Consulta')) {
                categoryBadge = `<span class="badge-tag blue" style="font-size:0.74rem; font-weight:700;"><i class="fa-solid fa-stethoscope"></i> ${b.specialty || 'Consultas'}</span>`;
            } else if (cat === 'Rayos X & Imagenología' || cat.includes('Rayos') || cat.includes('Imagen')) {
                categoryBadge = `<span class="badge-tag purple" style="font-size:0.74rem; font-weight:700;"><i class="fa-solid fa-x-ray"></i> ${b.specialty || 'Rayos X'}</span>`;
            } else if (cat === 'Laboratorio Clínico' || cat.includes('Laboratorio')) {
                categoryBadge = `<span class="badge-tag amber" style="font-size:0.74rem; font-weight:700;"><i class="fa-solid fa-flask"></i> Laboratorio</span>`;
            } else if (cat === 'Procedimientos Ambulatorios' || cat.includes('Procedimiento')) {
                categoryBadge = `<span class="badge-tag red" style="font-size:0.74rem; font-weight:700;"><i class="fa-solid fa-syringe"></i> ${b.specialty || 'Procedimiento'}</span>`;
            } else {
                categoryBadge = `<span class="badge-tag gray" style="font-size:0.74rem; font-weight:700;">${cat}</span>`;
            }

            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td><strong>${b.id}</strong></td>
                <td>${categoryBadge}</td>
                <td>
                    <strong>${patientName}</strong>
                    ${patient && patient.cedula ? `<br><small class="text-muted">${patient.cedula}</small>` : ''}
                </td>
                <td>${b.invoiceDate || 'N/A'}</td>
                <td>
                    <strong style="color: #0f172a; font-size: 0.95rem;">$${b.totalRef.toFixed(2)}</strong>
                    ${b.totalBcv ? `<br><small style="color: #0284c7; font-weight: 600;">${parseFloat(b.totalBcv).toFixed(2)} Bs.</small>` : ''}
                </td>
                <td>${b.doctor || spec}</td>
                <td><span class="${badgeClass}" style="font-size:0.75rem; text-transform:none; padding: 2px 6px;">${statusLabel}</span></td>
                <td style="text-align: center;">
                    <div style="display: flex; gap: 4px; justify-content: center; flex-wrap: wrap;">
                        <button class="btn btn-xs btn-outline" onclick="loadBudgetIntoEditor('${b.id}')" style="padding: 4px 8px; font-weight:600; border-radius:4px; cursor: pointer;" title="Abrir y Editar Presupuesto"><i class="fa-solid fa-folder-open"></i> Abrir</button>
                        ${b.category && b.category !== 'Odontología' 
                            ? `<button class="btn btn-xs btn-outline" onclick="window.printMedicalBudgetPDF('${b.id}')" style="padding: 4px 8px; font-weight:600; border-radius:4px; cursor: pointer; color: #0284c7; border-color: #bae6fd;" title="Imprimir Presupuesto PDF"><i class="fa-solid fa-file-pdf"></i> PDF</button>`
                            : ''
                        }
                        <button class="btn btn-xs btn-success" onclick="${b.category && b.category !== 'Odontología' ? `window.sendMedicalBudgetWhatsApp('${b.id}')` : `window.sendBudgetWhatsApp('${b.id}')`}" style="padding: 4px 8px; font-weight:600; border-radius:4px; cursor: pointer; background:#25D366; border:none; color:#fff;" title="Enviar Presupuesto por WhatsApp"><i class="fa-brands fa-whatsapp"></i> WhatsApp</button>
                        ${isApproved ? `<button class="btn btn-xs btn-success" onclick="window.finalizeBudgetDirect('${b.id}')" style="padding: 4px 8px; font-weight:600; border-radius:4px; cursor: pointer; background:#10b981; border:none; color:#fff;" title="Finalizar Tratamiento / Presupuesto"><i class="fa-solid fa-circle-check"></i> Finalizar</button>` : ''}
                        <button class="btn btn-xs btn-outline text-red" onclick="window.deleteBudget('${b.id}')" style="padding: 4px 8px; font-weight:600; border-radius:4px; cursor: pointer; border-color: #ef4444; color: #ef4444;" title="Eliminar Presupuesto (Enviar a Papelera)"><i class="fa-solid fa-trash-can"></i></button>
                    </div>
                </td>
            `;
            tableBody.appendChild(tr);
        });
    }
}

window.deleteBudget = async function(budgetId) {
    try {
        const invoices = await SupabaseDataService.getInvoices();
        const budget = invoices.find(inv => String(inv.id) === String(budgetId));
        if (!budget) {
            Swal.fire({ icon: 'error', title: 'Error', text: 'No se encontró el presupuesto especificado.' });
            return;
        }

        const patients = await SupabaseDataService.getPatients();
        const patient = patients.find(p => String(p.id) === String(budget.patientId));
        const patientName = patient ? patient.fullname : (budget.patientId || 'Paciente');

        const result = await Swal.fire({
            title: '¿Eliminar presupuesto?',
            html: `
                <div style="text-align: left; font-size: 0.92rem; line-height: 1.5; color: var(--text-main);">
                    <p style="margin-bottom: 8px;">¿Está seguro de que desea eliminar el presupuesto <strong>${budget.id}</strong> del paciente <strong>${patientName}</strong>?</p>
                    <div style="background: rgba(239, 68, 68, 0.08); border-left: 3px solid #ef4444; padding: 8px 12px; border-radius: 4px; font-size: 0.85rem; color: #dc2626;">
                        <i class="fa-solid fa-trash-arrow-up"></i> Este presupuesto se enviará a la <strong>Papelera de Reciclaje</strong>, donde podrá restaurarlo en cualquier momento.
                    </div>
                </div>
            `,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ef4444',
            cancelButtonColor: '#64748b',
            confirmButtonText: '<i class="fa-solid fa-trash-can"></i> Sí, enviar a papelera',
            cancelButtonText: 'Cancelar'
        });

        if (!result.isConfirmed) return;

        // 1. Move to Trash
        if (window.moveToTrash) {
            await window.moveToTrash('invoices', budget, `Presupuesto ${budget.id} - ${patientName} ($${(budget.totalRef || budget.totalUSD || 0).toFixed(2)})`);
        }

        // 2. Delete from invoices
        await SupabaseDataService.deleteInvoice(budgetId);

        // 3. Clear draft metadata if linked to patient
        if (patient && patient.metadata && patient.metadata.draftBudget && String(patient.metadata.draftBudget.id) === String(budgetId)) {
            delete patient.metadata.draftBudget;
            delete patient.metadata.draftOdontogramData;
            await SupabaseDataService.savePatient(patient);
        }

        // 4. If current budget is open in editor, clear it
        if (activeEditingBudgetId === budgetId) {
            activeEditingBudgetId = null;
            currentBudgetItems = [];
            setActivePatientId(null);
            if (window.odontogram) window.odontogram.setData({});
            if (window.dismissFloatingBudgetBubble) window.dismissFloatingBudgetBubble();
        }

        // 5. Re-render budget list and dashboard
        await renderBudgetListView(true);
        if (typeof renderDashboard === 'function') await renderDashboard();

        Swal.fire({
            icon: 'success',
            title: 'Presupuesto Eliminado',
            text: `El presupuesto ${budgetId} fue movido a la Papelera de Reciclaje.`,
            timer: 2000,
            showConfirmButton: false
        });
    } catch(err) {
        console.error("Error deleting budget:", err);
        Swal.fire({ icon: 'error', title: 'Error', text: 'No se pudo eliminar el presupuesto.' });
    }
};

window.sendBudgetWhatsApp = async function(budgetId) {
    try {
        const invoices = await SupabaseDataService.getInvoices();
        const budget = invoices.find(inv => String(inv.id) === String(budgetId));
        if (!budget) {
            Swal.fire({ icon: 'error', title: 'Error', text: 'No se encontró el presupuesto.' });
            return;
        }

        // VALIDAR QUE EL PRESUPUESTO ESTÉ APROBADO ANTES DE ENVIARLO POR WHATSAPP
        const status = String(budget.status || '').toLowerCase();
        const isApproved = status === 'aprobado' || status === 'approved' || status === 'facturado' || status === 'completada' || status === 'finalizado';
        if (!isApproved) {
            Swal.fire({
                icon: 'warning',
                title: 'Presupuesto no Aprobado',
                text: 'No se puede enviar el presupuesto al paciente por WhatsApp porque aún está en estado Borrador. Debe Aprobar el presupuesto antes de enviarlo.'
            });
            return;
        }

        const patients = await SupabaseDataService.getPatients();
        const patient = patients.find(p => String(p.id) === String(budget.patientId));
        if (!patient || !patient.phone) {
            Swal.fire({ icon: 'warning', title: 'Sin Teléfono', text: 'El paciente asociado a este presupuesto no tiene un número de teléfono / WhatsApp registrado.' });
            return;
        }

        const items = budget.items || [];
        const totalUSD = budget.totalRef || budget.totalUSD || 0;
        const subtotalUSD = budget.subtotal || totalUSD;
        const discountPct = budget.discountPct || 0;
        const paymentMode = budget.paymentTerms || 'Contado';

        const msg = WhatsAppService.generateBudgetMessage(patient, items, totalUSD, paymentMode, '', subtotalUSD, discountPct, paymentMode, budget.id);
        WhatsAppService.sendToPatient(patient.phone, msg);
    } catch(err) {
        console.error("Error sending budget via WhatsApp:", err);
        Swal.fire({ icon: 'error', title: 'Error', text: err.message || err });
    }
};

window.finalizeBudgetDirect = async function(budgetId) {
    try {
        const invoices = await SupabaseDataService.getInvoices();
        const budget = invoices.find(inv => String(inv.id) === String(budgetId));
        if (!budget) {
            Swal.fire({ icon: 'error', title: 'Error', text: 'No se encontró el presupuesto especificado.' });
            return;
        }

        const patients = await SupabaseDataService.getPatients();
        const patient = patients.find(p => String(p.id) === String(budget.patientId)) || { fullname: 'Paciente', id: budget.patientId };

        const totalUSD = budget.totalRef || budget.totalUSD || 0;

        const { value: formValues } = await Swal.fire({
            title: `<i class="fa-solid fa-circle-check text-green"></i> Finalizar Tratamiento / Presupuesto`,
            html: `
                <div style="text-align: left; font-size: 0.92rem; display: flex; flex-direction: column; gap: 12px;">
                    <div style="background: rgba(5,150,105,0.08); padding: 12px; border-radius: 8px; border: 1px solid rgba(5,150,105,0.2);">
                        <div><strong>Paciente:</strong> ${patient.fullname} (${patient.id})</div>
                        <div><strong>Presupuesto N°:</strong> ${budget.id}</div>
                        <div><strong>Monto Total:</strong> <span style="color:#059669; font-weight:bold; font-size:1.1rem;">$${totalUSD.toFixed(2)}</span></div>
                    </div>
                    
                    <div>
                        <label style="font-weight: 600; display: block; margin-bottom: 4px;">N° de Control / Factura o Recibo Físico (Opcional):</label>
                        <input id="swal-finalize-num" class="swal2-input" style="margin: 0; width: 100%;" placeholder="Ej: REC-00${budget.id.replace(/[^0-9]/g,'') || '101'}" value="REC-${budget.id}">
                    </div>

                    <div>
                        <label style="font-weight: 600; display: block; margin-bottom: 4px;">Método de Liquidación / Cierre:</label>
                        <select id="swal-finalize-method" class="swal2-select" style="margin: 0; width: 100%; display: block;">
                            <option value="cash">Dólares Efectivo ($ USD)</option>
                            <option value="zelle">Zelle ($ USD)</option>
                            <option value="transfer_bs">Transferencia / Pago Móvil (Bs.)</option>
                            <option value="pos">Punto de Venta (Bs.)</option>
                            <option value="mixed">Pago Mixto / Múltiples Métodos</option>
                            <option value="already_settled">Ya Liquidado / Pagado Previamente</option>
                        </select>
                    </div>

                    <div style="margin-top: 5px;">
                        <label style="font-weight: 600; display: block; margin-bottom: 4px;">Notas o Observaciones Finales:</label>
                        <textarea id="swal-finalize-notes" class="swal2-textarea" style="margin: 0; width: 100%; height: 60px;" placeholder="Tratamiento completado satisfactoriamente."></textarea>
                    </div>
                </div>
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: '<i class="fa-solid fa-check-circle"></i> Confirmar y Finalizar',
            cancelButtonText: 'Cancelar',
            confirmButtonColor: '#10b981',
            cancelButtonColor: '#64748b',
            preConfirm: () => {
                return {
                    receiptNum: document.getElementById('swal-finalize-num').value.trim(),
                    method: document.getElementById('swal-finalize-method').value,
                    notes: document.getElementById('swal-finalize-notes').value.trim()
                };
            }
        });

        if (!formValues) return;

        // 1. Update invoice in Supabase
        budget.status = 'Facturado';
        budget.paymentTerms = 'Contado';
        budget.finalizedDate = new Date().toISOString().split('T')[0];
        budget.receiptNumber = formValues.receiptNum;
        budget.closureMethod = formValues.method;
        budget.closureNotes = formValues.notes;
        await SupabaseDataService.saveInvoice(budget);

        // 2. Update patient treatment cycle
        const pat = patients.find(p => String(p.id) === String(budget.patientId));
        if (pat) {
            if (!pat.metadata) pat.metadata = {};
            pat.metadata.treatmentStatus = 'Finalizado';
            pat.status = 'Activo';

            if (pat.metadata.treatments) {
                pat.metadata.treatments.forEach(t => t.status = 'Completado');
            }

            if (!pat.clinicalNotes) pat.clinicalNotes = [];
            pat.clinicalNotes.unshift({
                id: 'note-' + Date.now(),
                datetime: new Date().toISOString().slice(0, 16).replace('T', ' '),
                content: `Tratamiento Completado y Presupuesto #${budget.id} Finalizado con éxito. N° Control / Recibo: ${formValues.receiptNum || 'S/N'}. Método: ${formValues.method}. Notas: ${formValues.notes || 'Sin observaciones adicionales.'}`,
                paymentUSD: totalUSD
            });

            if (!pat.payments) pat.payments = [];
            const alreadyPaid = pat.payments.some(p => p.concept && p.concept.includes(budget.id));
            if (!alreadyPaid && formValues.method !== 'already_settled') {
                pat.payments.unshift({
                    date: new Date().toISOString().split('T')[0],
                    concept: `Liquidación Final Presupuesto #${budget.id} (${formValues.receiptNum || 'Recibo'})`,
                    totalUSD: totalUSD,
                    paidUSD: totalUSD,
                    balanceUSD: 0.00,
                    status: 'Pagado',
                    method: formValues.method
                });
            }

            await SupabaseDataService.savePatient(pat);
        }

        // 2.1 Auto-record medical liquidation for completed treatments
        try {
            const currentUser = getCurrentUser();
            const docName = budget.doctor || (currentUser ? currentUser.fullname : 'Médico Tratante');
            const docId = currentUser ? currentUser.id : null;
            const itemsToLiquidate = Array.isArray(budget.items) && budget.items.length > 0
                ? budget.items 
                : (pat && pat.metadata && Array.isArray(pat.metadata.treatments) ? pat.metadata.treatments : []);

            for (const item of itemsToLiquidate) {
                const srvPrice = parseFloat(item.price || item.totalUSD || item.cost || 0);
                if (srvPrice > 0 || item.name || item.treatment) {
                    await SupabaseDataService.recordServiceCompletionForLiquidation({
                        serviceCode: item.serviceCode || item.code || 'SRV-BUDGET',
                        serviceName: item.name || item.treatment || item.description || 'Procedimiento Odontológico',
                        servicePrice: srvPrice,
                        patientId: budget.patientId || (pat ? pat.id : ''),
                        patientName: (pat ? pat.fullname : (patient ? patient.fullname : 'Paciente Clínico')),
                        doctorId: docId,
                        doctorName: docName,
                        sourceType: 'budget_completion',
                        notes: `Finalizado con Presupuesto #${budget.id} (${formValues.receiptNum || 'Recibo'})`
                    });
                }
            }
            if (window.ClinicalERP && window.ClinicalERP.loadAll) {
                await window.ClinicalERP.loadAll();
            }
        } catch(liqErr) {
            console.warn('[Liquidation] Error auto-recording budget items liquidation:', liqErr);
        }

        // 3. Refresh views
        if (typeof renderOdontogramView === 'function') await renderOdontogramView();
        if (typeof renderPatientsTable === 'function') await renderPatientsTable();
        if (typeof renderEHRView === 'function') await renderEHRView();
        if (typeof renderDashboard === 'function') await renderDashboard();
        if (typeof renderFinanceView === 'function') await renderFinanceView();

        Swal.fire({
            icon: 'success',
            title: '¡Tratamiento / Presupuesto Finalizado!',
            text: `El presupuesto ${budget.id} ha sido finalizado con éxito.`,
            timer: 2200,
            showConfirmButton: false
        });
    } catch(err) {
        console.error("Error finalizing budget:", err);
        Swal.fire({ icon: 'error', title: 'Error al Finalizar', text: err.message || err });
    }
};

window.closeBudgetFinanciallyDirect = window.finalizeBudgetDirect;

window.finalizePatientTreatment = async function(patientId) {
    try {
        const invoices = await SupabaseDataService.getInvoices();
        const patientBudgets = invoices.filter(inv => String(inv.patientId) === String(patientId));
        const activeBudget = patientBudgets.find(b => b.status === 'Aprobado') || patientBudgets[0];

        if (activeBudget) {
            await window.finalizeBudgetDirect(activeBudget.id);
        } else {
            // Patient has no formal invoice, finalize directly
            const patients = await SupabaseDataService.getPatients();
            const pat = patients.find(p => String(p.id) === String(patientId));
            if (!pat) {
                Swal.fire({ icon: 'error', title: 'Error', text: 'No se encontró el paciente.' });
                return;
            }

            const { isConfirmed } = await Swal.fire({
                title: `<i class="fa-solid fa-circle-check text-green"></i> Finalizar Tratamiento`,
                text: `¿Desea marcar como "Finalizado" el ciclo de tratamiento de ${pat.fullname}?`,
                icon: 'question',
                showCancelButton: true,
                confirmButtonText: 'Sí, Finalizar Tratamiento',
                cancelButtonText: 'Cancelar',
                confirmButtonColor: '#10b981',
                cancelButtonColor: '#64748b'
            });

            if (isConfirmed) {
                if (!pat.metadata) pat.metadata = {};
                pat.metadata.treatmentStatus = 'Finalizado';
                pat.status = 'Activo';
                if (pat.metadata.treatments) {
                    pat.metadata.treatments.forEach(t => t.status = 'Completado');
                }
                await SupabaseDataService.savePatient(pat);
                await renderPatientsTable();
                await renderEHRView();
                await renderDashboard();
                Swal.fire({ icon: 'success', title: 'Tratamiento Finalizado', text: `El tratamiento de ${pat.fullname} ha sido finalizado exitosamente.`, timer: 2000, showConfirmButton: false });
            }
        }
    } catch(err) {
        console.error("Error finalizing patient treatment:", err);
        Swal.fire({ icon: 'error', title: 'Error', text: err.message || err });
    }
};

// ==========================================================================
// MOTOR DE PRESUPUESTOS MÉDICOS & MULTI-ESPECIALIDADES (SIN ODONTOGRAMA)
// ==========================================================================
window.currentMedicalBudgetItems = [];
window.activeEditingMedicalBudgetId = null;
window.activeMedicalSpecialtyCategory = 'Consultas Médicas';

window.startBudgetCreation = async function(category) {
    closeModal('modal-select-budget-type');
    if (typeof window.navigateToTab === 'function') {
        await window.navigateToTab('odontogram');
    }
    if (category === 'Odontología') {
        await window.selectPatientAndLoadApprovedBudget(null);
    } else {
        await window.openMedicalBudgetEditor({ specialtyCategory: category });
    }
};

window.openMedicalBudgetEditor = async function({ budgetId = null, specialtyCategory = 'Consultas Médicas' } = {}) {
    localStorage.setItem('dental_odontogram_subview', 'medical-editor');
    document.documentElement.setAttribute('data-odontogram-subview', 'medical-editor');

    const listContainer = document.getElementById('odontogram-list-container');
    const editorContainer = document.getElementById('odontogram-editor-container');
    const medEditorContainer = document.getElementById('medical-budget-editor-container');

    if (listContainer) listContainer.classList.add('hidden');
    if (editorContainer) editorContainer.classList.add('hidden');
    if (medEditorContainer) medEditorContainer.classList.remove('hidden');

    const navOdontogram = document.querySelector('.nav-item[data-tab="odontogram"]') || document.getElementById('mob-nav-odontogram');
    if (navOdontogram && !navOdontogram.classList.contains('active')) {
        navOdontogram.click();
    }

    window.activeMedicalSpecialtyCategory = specialtyCategory;
    window.activeEditingMedicalBudgetId = budgetId;

    // Actualizar tasa BCV en el encabezado
    const rate = getExchangeRate();
    const rateEl = document.getElementById('med-budget-bcv-rate');
    if (rateEl) rateEl.innerText = rate.toFixed(2);

    // Cargar pacientes
    const patientSelect = document.getElementById('med-budget-patient-select');
    if (patientSelect) {
        patientSelect.innerHTML = '<option value="">Cargando pacientes...</option>';
        try {
            const patients = await SupabaseDataService.getPatients();
            patientSelect.innerHTML = '<option value="">-- Seleccionar Paciente --</option>' +
                patients.map(p => `<option value="${p.id}">${p.fullname} ${p.cedula ? `(${p.cedula})` : ''}</option>`).join('');
        } catch(e) {
            patientSelect.innerHTML = '<option value="">-- Error cargando pacientes --</option>';
        }
    }

    // Cargar especialistas (doctores)
    const doctorSelect = document.getElementById('med-budget-doctor-select');
    if (doctorSelect) {
        try {
            const users = await SupabaseDataService.getUsers();
            const doctors = users.filter(u => u.role === 'Odontólogo' || u.role === 'Especialista' || u.role === 'Doctor' || (u.name && u.name.toLowerCase().includes('dr')) || (u.fullname && u.fullname.toLowerCase().includes('dr')));
            if (doctors.length > 0) {
                doctorSelect.innerHTML = doctors.map(d => `<option value="${d.fullname || d.name}" data-id="${d.id}">${d.fullname || d.name} (${d.role || 'Médico'})</option>`).join('');
            } else {
                doctorSelect.innerHTML = '<option value="Médico Tratante">Médico Tratante</option>';
            }
        } catch(e) {
            doctorSelect.innerHTML = '<option value="Médico Tratante">Médico Tratante</option>';
        }
    }

    // Configurar Departamento / Área
    const deptSelect = document.getElementById('med-budget-department-select');
    if (deptSelect) {
        deptSelect.value = specialtyCategory;
    }

    // Título dinámico
    const titleEl = document.getElementById('med-budget-title');
    const icons = {
        'Odontología': '<i class="fa-solid fa-tooth text-green"></i> Presupuesto Odontológico',
        'Consultas Médicas': '<i class="fa-solid fa-stethoscope text-blue"></i> Presupuesto de Consultas Médicas',
        'Rayos X & Imagenología': '<i class="fa-solid fa-x-ray text-purple"></i> Presupuesto de Rayos X & Imagenología',
        'Laboratorio Clínico': '<i class="fa-solid fa-flask text-amber"></i> Presupuesto de Laboratorio Clínico',
        'Procedimientos Ambulatorios': '<i class="fa-solid fa-syringe text-red"></i> Presupuesto de Procedimientos Ambulatorios'
    };
    if (titleEl) {
        titleEl.innerHTML = icons[specialtyCategory] || `<i class="fa-solid fa-file-invoice-dollar text-cyan"></i> Presupuesto: ${specialtyCategory}`;
    }

    // Fechas
    const dateInput = document.getElementById('med-budget-date');
    if (dateInput) {
        dateInput.value = new Date().toISOString().split('T')[0];
    }

    // Cargar servicios en el baremo
    await window.refreshMedicalBaremoSelect();

    // Si estamos editando un presupuesto existente:
    if (budgetId) {
        try {
            const invoices = await SupabaseDataService.getInvoices();
            const budget = invoices.find(inv => String(inv.id) === String(budgetId));
            if (budget) {
                window.activeEditingMedicalBudgetId = budget.id;
                const idBadge = document.getElementById('med-budget-id-badge');
                if (idBadge) {
                    idBadge.innerText = budget.id;
                    idBadge.className = 'badge-tag green';
                }

                if (patientSelect) {
                    patientSelect.value = budget.patientId || '';
                    window.onMedicalBudgetPatientChange(budget.patientId);
                }
                if (deptSelect && budget.category) {
                    deptSelect.value = budget.category;
                }
                if (doctorSelect && budget.doctor) {
                    doctorSelect.value = budget.doctor;
                }
                if (dateInput && budget.invoiceDate) {
                    dateInput.value = budget.invoiceDate;
                }
                const validitySelect = document.getElementById('med-budget-validity');
                if (validitySelect && budget.validUntil) {
                    validitySelect.value = String(budget.validUntil);
                }
                const notesEl = document.getElementById('med-budget-notes');
                if (notesEl) {
                    notesEl.value = budget.notes || budget.footerText || '';
                }

                window.currentMedicalBudgetItems = (budget.items || []).map(it => ({
                    code: it.code || it.serviceCode || '',
                    name: it.name || it.treatment || 'Servicio',
                    price: parseFloat(it.price) || 0,
                    qty: parseInt(it.qty) || 1,
                    discount: parseFloat(it.discount) || 0,
                    totalUSD: parseFloat(it.totalUSD || (it.price * (it.qty || 1))),
                    totalBs: parseFloat(it.totalBs || (it.totalUSD * rate))
                }));

                window.renderMedicalBudgetItems();
                return;
            }
        } catch(e) {
            console.error('Error loading medical budget:', e);
        }
    }

    // Presupuesto nuevo en blanco
    window.activeEditingMedicalBudgetId = null;
    window.currentMedicalBudgetItems = [];
    const idBadge = document.getElementById('med-budget-id-badge');
    if (idBadge) {
        idBadge.innerText = 'Nuevo Presupuesto';
        idBadge.className = 'badge-tag gray';
    }
    const notesEl = document.getElementById('med-budget-notes');
    if (notesEl) notesEl.value = '';

    const infoBox = document.getElementById('med-budget-patient-info-box');
    if (infoBox) {
        infoBox.innerHTML = '<span style="color: #64748b;"><i class="fa-solid fa-circle-info"></i> Seleccione un paciente para ver sus datos clínicos de contacto.</span>';
    }

    window.renderMedicalBudgetItems();
};

window.backToBudgetList = function() {
    localStorage.setItem('dental_odontogram_subview', 'list');
    document.documentElement.setAttribute('data-odontogram-subview', 'list');
    const listContainer = document.getElementById('odontogram-list-container');
    const editorContainer = document.getElementById('odontogram-editor-container');
    const medEditorContainer = document.getElementById('medical-budget-editor-container');
    if (listContainer) listContainer.classList.remove('hidden');
    if (editorContainer) editorContainer.classList.add('hidden');
    if (medEditorContainer) medEditorContainer.classList.add('hidden');
    renderBudgetListView();
};

window.getActivePatientTagRule = function(patientId) {
    if (!patientId) return null;
    try {
        const raw = localStorage.getItem('dental_patients');
        if (raw) {
            const list = JSON.parse(raw);
            const p = list.find(pat => String(pat.id) === String(patientId));
            if (p) return p.tagRule || (p.metadata && p.metadata.tagRule) || null;
        }
    } catch(e) {}
    return null;
};

window.onMedicalBudgetPatientChange = async function(patientId) {
    const infoBox = document.getElementById('med-budget-patient-info-box');
    if (!infoBox) return;

    if (!patientId) {
        infoBox.innerHTML = '<span style="color: #64748b;"><i class="fa-solid fa-circle-info"></i> Seleccione un paciente para ver sus datos clínicos de contacto.</span>';
        return;
    }

    try {
        const patients = await SupabaseDataService.getPatients();
        const p = patients.find(pat => String(pat.id) === String(patientId));
        if (p) {
            const tagName = p.tagName || (p.metadata && p.metadata.tagName);
            const tagColor = p.tagColor || (p.metadata && p.metadata.tagColor) || '#2563eb';
            const tagRule = p.tagRule || (p.metadata && p.metadata.tagRule);

            let tagBadgeHtml = '';
            if (tagName) {
                let ruleText = '';
                if (tagRule) {
                    if (tagRule.type === 'discount') ruleText = ` (-${tagRule.value}%)`;
                    else if (tagRule.type === 'surcharge') ruleText = ` (+${tagRule.value}%)`;
                    else if (tagRule.type === 'exonerated') ruleText = ' (100% Exonerado)';
                }
                tagBadgeHtml = `<span class="badge-tag" style="background:${tagColor}18; color:${tagColor}; border:1px solid ${tagColor}50; font-weight:700; font-size:0.75rem; margin-left:8px; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-tags"></i> ${tagName}${ruleText}</span>`;
            }

            infoBox.innerHTML = `
                <div style="line-height: 1.35; flex: 1;">
                    <div style="display: flex; align-items: center; flex-wrap: wrap; margin-bottom: 2px;">
                        <strong style="color: #0f172a; font-size: 0.92rem;">${p.fullname}</strong>
                        ${tagBadgeHtml}
                    </div>
                    <span style="color: #64748b; font-size: 0.82rem;">Cédula: <strong>${p.cedula || p.id || 'N/A'}</strong> • Edad: <strong>${p.age ? p.age + ' años' : 'N/A'}</strong> • Teléfono: <strong>${p.phone || 'N/A'}</strong></span>
                </div>
            `;

            // Auto-fill discount input for new items if discount rule exists
            const discountInput = document.getElementById('med-item-discount');
            if (discountInput && tagRule) {
                if (tagRule.type === 'discount') {
                    discountInput.value = tagRule.value;
                } else if (tagRule.type === 'exonerated') {
                    discountInput.value = '100';
                }
            }
        }
    } catch(e) {
        console.error(e);
    }
};

window.onMedicalBudgetDepartmentChange = async function(dept) {
    window.activeMedicalSpecialtyCategory = dept;
    const titleEl = document.getElementById('med-budget-title');
    const icons = {
        'Consultas Médicas': '<i class="fa-solid fa-stethoscope text-blue"></i> Presupuesto de Consultas Médicas',
        'Rayos X & Imagenología': '<i class="fa-solid fa-x-ray text-purple"></i> Presupuesto de Rayos X & Imagenología',
        'Laboratorio Clínico': '<i class="fa-solid fa-flask text-amber"></i> Presupuesto de Laboratorio Clínico',
        'Procedimientos Ambulatorios': '<i class="fa-solid fa-syringe text-red"></i> Presupuesto de Procedimientos Ambulatorios'
    };
    if (titleEl) {
        titleEl.innerHTML = icons[dept] || `<i class="fa-solid fa-file-invoice-dollar text-cyan"></i> Presupuesto: ${dept}`;
    }
    await window.refreshMedicalBaremoSelect();
};

window.refreshMedicalBaremoSelect = async function() {
    const srvSelect = document.getElementById('med-item-baremo-select');
    if (!srvSelect) return;

    srvSelect.innerHTML = '<option value="">Cargando baremo...</option>';
    try {
        const baremo = await SupabaseDataService.getBaremo();
        const showAll = document.getElementById('med-budget-show-all-baremo')?.checked;
        const currentDept = document.getElementById('med-budget-department-select')?.value || 'Consultas Médicas';

        let filtered = baremo;
        if (!showAll) {
            const deptLow = currentDept.toLowerCase();
            filtered = baremo.filter(b => {
                const cat = (b.category || '').toLowerCase();
                if (deptLow.includes('consulta')) {
                    return cat.includes('consulta') || cat.includes('medicina') || cat.includes('cardiolog') || cat.includes('pediatr') || cat.includes('especialidad');
                } else if (deptLow.includes('rayos') || deptLow.includes('imagen')) {
                    return cat.includes('rayos') || cat.includes('radio') || cat.includes('eco') || cat.includes('imagen') || cat.includes('tórax') || cat.includes('rx');
                } else if (deptLow.includes('laboratorio')) {
                    return cat.includes('lab') || cat.includes('sangre') || cat.includes('perfil') || cat.includes('examen') || cat.includes('química');
                } else if (deptLow.includes('procedimiento')) {
                    return cat.includes('cirug') || cat.includes('proced') || cat.includes('curac') || cat.includes('sutura');
                }
                return true;
            });
            // Si el filtro no encontró ítems específicos, mostramos todo el baremo para no dejar en blanco
            if (filtered.length === 0) filtered = baremo;
        }

        srvSelect.innerHTML = '<option value="">-- Seleccionar Servicio / Procedimiento --</option>' +
            filtered.map(b => `<option value="${b.code || b.id}" data-name="${b.name}" data-price="${b.price || 0}">${b.name} ($${parseFloat(b.price || 0).toFixed(2)})</option>`).join('');
    } catch(e) {
        srvSelect.innerHTML = '<option value="">Error cargando baremo</option>';
    }
};

window.onMedicalBaremoSelected = function(code) {
    const srvSelect = document.getElementById('med-item-baremo-select');
    const opt = srvSelect ? srvSelect.options[srvSelect.selectedIndex] : null;
    const priceInput = document.getElementById('med-item-price');
    if (opt && priceInput) {
        let price = parseFloat(opt.getAttribute('data-price') || 0);
        // Verificar regla de recargo comercial del paciente activo
        const patId = document.getElementById('med-budget-patient-select')?.value;
        if (patId && typeof window.getActivePatientTagRule === 'function') {
            const rule = window.getActivePatientTagRule(patId);
            if (rule && rule.type === 'surcharge') {
                const surchargePct = parseFloat(rule.value) || 0;
                price = price * (1 + surchargePct / 100);
            }
        }
        priceInput.value = price.toFixed(2);
    }
};

window.addMedicalBudgetItem = function() {
    const srvSelect = document.getElementById('med-item-baremo-select');
    const opt = srvSelect ? srvSelect.options[srvSelect.selectedIndex] : null;
    if (!opt || !opt.value) {
        Swal.fire({ icon: 'warning', title: 'Servicio Requerido', text: 'Por favor seleccione un servicio del baremo.' });
        return;
    }

    const name = opt.getAttribute('data-name') || opt.text.split(' ($')[0];
    const code = opt.value;
    const price = parseFloat(document.getElementById('med-item-price')?.value) || 0;
    const qty = parseInt(document.getElementById('med-item-qty')?.value) || 1;
    const discount = parseFloat(document.getElementById('med-item-discount')?.value) || 0;

    const rate = getExchangeRate();
    const itemSubtotal = price * qty;
    const itemTotalUSD = Math.max(0, itemSubtotal * (1 - discount / 100));
    const itemTotalBs = itemTotalUSD * rate;

    window.currentMedicalBudgetItems.push({
        code: code,
        name: name,
        price: price,
        qty: qty,
        discount: discount,
        totalUSD: itemTotalUSD,
        totalBs: itemTotalBs
    });

    // Reset fields
    if (srvSelect) srvSelect.value = '';
    const priceInput = document.getElementById('med-item-price');
    if (priceInput) priceInput.value = '';
    const qtyInput = document.getElementById('med-item-qty');
    if (qtyInput) qtyInput.value = '1';
    const discInput = document.getElementById('med-item-discount');
    if (discInput) {
        const patId = document.getElementById('med-budget-patient-select')?.value;
        const rule = patId && typeof window.getActivePatientTagRule === 'function' ? window.getActivePatientTagRule(patId) : null;
        if (rule && rule.type === 'discount') {
            discInput.value = rule.value;
        } else if (rule && rule.type === 'exonerated') {
            discInput.value = '100';
        } else {
            discInput.value = '0';
        }
    }

    window.renderMedicalBudgetItems();
};

window.removeMedicalBudgetItem = function(index) {
    window.currentMedicalBudgetItems.splice(index, 1);
    window.renderMedicalBudgetItems();
};

window.renderMedicalBudgetItems = function() {
    const tbody = document.getElementById('med-budget-items-tbody');
    if (!tbody) return;

    const rate = getExchangeRate();
    let subtotalUSD = 0;
    let totalDiscountUSD = 0;
    let totalFinalUSD = 0;

    if (window.currentMedicalBudgetItems.length === 0) {
        tbody.innerHTML = '<tr class="empty-row"><td colspan="6" class="text-center text-muted" style="padding: 30px;">Cargue los servicios o estudios médicos para calcular el presupuesto.</td></tr>';
    } else {
        tbody.innerHTML = window.currentMedicalBudgetItems.map((it, idx) => {
            const rawSub = it.price * it.qty;
            const discAmt = rawSub * (it.discount / 100);
            const netUSD = rawSub - discAmt;
            const netBs = netUSD * rate;

            subtotalUSD += rawSub;
            totalDiscountUSD += discAmt;
            totalFinalUSD += netUSD;

            return `
                <tr>
                    <td>
                        <strong style="color: #0f172a; font-size: 0.92rem;">${it.name}</strong>
                        ${it.code ? `<br><small style="color: #64748b;">Cód: ${it.code}</small>` : ''}
                    </td>
                    <td class="text-center font-weight-bold">${it.qty}</td>
                    <td class="text-right">$${it.price.toFixed(2)}</td>
                    <td class="text-center">${it.discount > 0 ? `<span class="badge-tag red">${it.discount}%</span>` : '-'}</td>
                    <td class="text-right">
                        <strong style="color: #0f172a; font-size: 0.95rem;">$${netUSD.toFixed(2)}</strong>
                        <br><small style="color: #0284c7; font-weight: 600;">${netBs.toFixed(2)} Bs.</small>
                    </td>
                    <td class="text-center">
                        <button type="button" class="btn btn-xs btn-outline text-red" onclick="window.removeMedicalBudgetItem(${idx})" style="border: none; color: #ef4444; cursor: pointer;" title="Eliminar ítem">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </td>
                </tr>
            `;
        }).join('');
    }

    // Totales calculados
    if (window.currentMedicalBudgetItems.length > 0) {
        totalFinalUSD = Math.max(0, subtotalUSD - totalDiscountUSD);
    }
    const totalFinalBs = totalFinalUSD * rate;

    const elSub = document.getElementById('med-summary-subtotal');
    if (elSub) elSub.innerText = `$${subtotalUSD.toFixed(2)}`;

    const elDisc = document.getElementById('med-summary-discount');
    if (elDisc) elDisc.innerText = `-$${totalDiscountUSD.toFixed(2)}`;

    const elTot = document.getElementById('med-summary-total');
    if (elTot) elTot.innerText = `$${totalFinalUSD.toFixed(2)}`;

    const elBs = document.getElementById('med-summary-bs');
    if (elBs) elBs.innerText = `${totalFinalBs.toFixed(2)} Bs.`;
};

window.saveMedicalBudget = async function(status = 'Presupuesto') {
    const patientSelect = document.getElementById('med-budget-patient-select');
    const patientId = patientSelect ? patientSelect.value : null;

    if (!patientId) {
        Swal.fire({ icon: 'warning', title: 'Paciente Requerido', text: 'Debe seleccionar un paciente para el presupuesto.' });
        return;
    }

    if (window.currentMedicalBudgetItems.length === 0) {
        Swal.fire({ icon: 'warning', title: 'Presupuesto Vacío', text: 'Debe añadir al menos un servicio o estudio al presupuesto.' });
        return;
    }

    const deptSelect = document.getElementById('med-budget-department-select');
    const department = deptSelect ? deptSelect.value : 'Consultas Médicas';

    const doctorSelect = document.getElementById('med-budget-doctor-select');
    const doctorName = doctorSelect ? doctorSelect.value : 'Médico Tratante';

    const dateInput = document.getElementById('med-budget-date');
    const date = dateInput && dateInput.value ? dateInput.value : new Date().toISOString().split('T')[0];

    const validitySelect = document.getElementById('med-budget-validity');
    const validityDays = validitySelect ? validitySelect.value : '30';

    const notes = document.getElementById('med-budget-notes')?.value || '';

    const rate = getExchangeRate();
    let totalRef = 0;
    window.currentMedicalBudgetItems.forEach(it => {
        totalRef += (it.totalUSD || (it.price * it.qty));
    });
    const totalBcv = totalRef * rate;

    // Generar o conservar ID del presupuesto
    const budgetId = window.activeEditingMedicalBudgetId || ('PRE-' + Date.now().toString().slice(-6));

    const invoiceObj = {
        id: budgetId,
        patientId: patientId,
        invoiceDate: date,
        paymentMethod: 'Por definir',
        paymentTerms: 'Contado',
        currency: 'USD',
        category: department,
        specialty: department,
        doctor: doctorName,
        items: window.currentMedicalBudgetItems,
        totalRef: totalRef,
        totalBcv: totalBcv,
        status: status, // 'Presupuesto' | 'Aprobado'
        notes: notes,
        validUntil: validityDays,
        createdAt: new Date().toISOString()
    };

    try {
        // 1. Guardar formalmente en Supabase Cloud (tabla invoices)
        await SupabaseDataService.saveInvoice(invoiceObj);

        // 2. Asociar al paciente en Supabase
        const patients = await SupabaseDataService.getPatients();
        const pat = patients.find(p => String(p.id) === String(patientId));
        if (pat) {
            if (!pat.metadata) pat.metadata = {};
            if (!pat.metadata.budgets) pat.metadata.budgets = [];
            const existingIdx = pat.metadata.budgets.findIndex(b => String(b.id) === String(budgetId));
            if (existingIdx >= 0) {
                pat.metadata.budgets[existingIdx] = invoiceObj;
            } else {
                pat.metadata.budgets.unshift(invoiceObj);
            }
            await SupabaseDataService.savePatient(pat);
        }

        window.activeEditingMedicalBudgetId = budgetId;
        const idBadge = document.getElementById('med-budget-id-badge');
        if (idBadge) {
            idBadge.innerText = budgetId;
            idBadge.className = status === 'Aprobado' ? 'badge-tag green' : 'badge-tag orange';
        }

        Swal.fire({
            icon: 'success',
            title: status === 'Aprobado' ? '¡Presupuesto Aprobado!' : '¡Borrador Guardado!',
            text: `Presupuesto ${budgetId} guardado exitosamente en la base de datos.`,
            timer: 2000,
            showConfirmButton: false
        });
    } catch(err) {
        console.error('Error saving medical budget:', err);
        Swal.fire({ icon: 'error', title: 'Error al Guardar', text: err.message || err });
    }
};

