window.sendWhatsAppReminderForAppt = async function(apptId) {
    const appointments = await SupabaseDataService.getAppointments();
    const appt = appointments.find(a => a.id === apptId);
    if (!appt) return;

    const patients = await SupabaseDataService.getPatients();
    let patient = patients.find(p => p.id === appt.patientId || p.fullname.toLowerCase() === appt.patientName.toLowerCase());

    const phone = patient ? patient.phone : prompt(`Ingrese el número de WhatsApp del paciente ${appt.patientName}:`, "+584141234567");
    if (!phone) return;

    const tomorrowStr = new Date(Date.now() + 86400000).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });
    
    // Generate calendar link for patient
    const calendarLink = window.getGoogleCalendarLinkForAppt(appt);
    const msg = WhatsAppService.generateAppointmentReminderMessage(appt.patientName, tomorrowStr, appt.time, appt.treatment, calendarLink);
    
    WhatsAppService.sendToPatient(phone, msg);
};

window.sendRemindersForAllTomorrow = async function() {
    const appointments = await SupabaseDataService.getAppointments();
    const tomorrowAppts = appointments.filter(a => a.isTomorrow === true || a.date === 'tomorrow');

    if (tomorrowAppts.length === 0) {
        Swal.fire({ icon: 'info', title: 'Sin citas agendadas', text: 'No hay citas programadas para el día de mañana.' });
        return;
    }

    Swal.fire({
        title: '¿Enviar recordatorios por WhatsApp?',
        text: `Se enviará el mensaje de confirmación a los ${tomorrowAppts.length} pacientes agendados para mañana.`,
        icon: 'question',
        showCancelButton: true,
        confirmButtonColor: '#10b981',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Sí, enviar ahora',
        cancelButtonText: 'Cancelar'
    }).then((result) => {
        if (result.isConfirmed) {
            tomorrowAppts.forEach((appt, idx) => {
                setTimeout(() => {
                    window.sendWhatsAppReminderForAppt(appt.id);
                }, idx * 1000);
            });
        }
    });
};

function parsePortions(unitStr) {
    if (!unitStr) return null;
    const match = unitStr.match(/\((\d+)\s*porciones\)/i);
    if (match) return parseInt(match[1]);
    const matchSimple = unitStr.match(/\((\d+)\)/);
    if (matchSimple) return parseInt(matchSimple[1]);
    return null;
}

function renderSessionMaterialsList(inventory, container) {
    if (!container) return;
    container.innerHTML = '';
    
    inventory.forEach(item => {
        const portionsPerUnit = parsePortions(item.unit);
        let stockDesc = `${item.currentStock} ${item.unit}`;
        let maxQty = item.currentStock;
        let qtyLabel = 'U.';

        if (portionsPerUnit) {
            const units = Math.floor(item.currentStock);
            const portions = Math.round((item.currentStock - units) * portionsPerUnit);
            const baseUnit = item.unit.replace(/\s*\(\d+\s*porciones\)/i, '').trim();
            stockDesc = `${units} ${baseUnit} y ${portions} porc.`;
            maxQty = Math.round(item.currentStock * portionsPerUnit);
            qtyLabel = 'porc.';
        }

        const row = document.createElement('div');
        row.style.display = 'flex';
        row.style.justifyContent = 'space-between';
        row.style.alignItems = 'center';
        row.style.padding = '4px 0';
        row.style.borderBottom = '1px dashed var(--border-color)';
        row.innerHTML = `
            <label style="font-size:0.8rem; cursor:pointer; display:flex; align-items:center; gap:6px; color: var(--text-main); margin:0;">
                <input type="checkbox" class="session-mat-checkbox" data-code="${item.code}">
                <span>${item.name} <small class="text-muted">(${stockDesc})</small></span>
            </label>
            <div style="display:flex; align-items:center; gap:4px;">
                <input type="number" class="session-mat-qty form-control" data-code="${item.code}" min="1" max="${maxQty}" value="1" style="width:60px; padding:2px; font-size:0.8rem; border:1px solid var(--border-color); background:var(--bg-main); color:var(--text-main);" disabled>
                <span style="font-size:0.75rem; color:var(--text-muted);">${qtyLabel}</span>
            </div>
        `;
        const chk = row.querySelector('.session-mat-checkbox');
        const qtyIn = row.querySelector('.session-mat-qty');
        chk.onchange = () => {
            qtyIn.disabled = !chk.checked;
        };
        container.appendChild(row);
    });
}

// ==========================================
// INVENTORY KARDEX & PRICING TABLES WITH DELETE
// ==========================================
window.currentInventoryAreaFilter = 'all';
window.currentInventoryStatusFilter = 'all';

async function renderInventoryTable(filter = null, searchQuery = null, areaFilter = null) {
    const tbody = document.getElementById('inventory-table-body');
    if (!tbody || !window.kardex) return;

    if (filter !== null) window.currentInventoryStatusFilter = filter;
    if (areaFilter !== null) window.currentInventoryAreaFilter = areaFilter;

    const currentStatus = window.currentInventoryStatusFilter || 'all';
    const currentArea = window.currentInventoryAreaFilter || 'all';
    const searchVal = searchQuery !== null ? searchQuery : (document.getElementById('inventory-table-search') ? document.getElementById('inventory-table-search').value : '');

    tbody.innerHTML = '';
    let items = await SupabaseDataService.getInventory();
    const currentUser = getCurrentUser();
    const isAssistant = currentUser && currentUser.role.toLowerCase().includes('asistente');

    // Ensure each item has a clinical area (inference engine fallback)
    items.forEach(item => {
        if (!item.area) {
            item.area = detectClinicalArea(item.category, item.name);
        }
    });

    // 1. Filter by Clinical Area
    if (currentArea !== 'all') {
        items = items.filter(item => (item.area || '').toLowerCase() === currentArea.toLowerCase());
    }

    // 2. Filter by Stock / Expiry Status
    if (currentStatus !== 'all') {
        if (currentStatus === 'low_stock') {
            items = items.filter(item => item.currentStock <= (item.minStock || 5));
        } else if (currentStatus === 'expired') {
            const today = new Date();
            const threshold = new Date();
            threshold.setDate(today.getDate() + 30); // 30 days buffer
            items = items.filter(item => {
                if (!item.expiryDate) return false;
                const expiry = new Date(item.expiryDate);
                return expiry.getTime() <= threshold.getTime();
            });
        }
    }

    // 3. Search Query Filter
    if (searchVal && searchVal.trim() !== '') {
        const q = searchVal.toLowerCase();
        items = items.filter(item => 
            (item.code && item.code.toLowerCase().includes(q)) ||
            (item.name && item.name.toLowerCase().includes(q)) ||
            (item.area && item.area.toLowerCase().includes(q)) ||
            (item.category && item.category.toLowerCase().includes(q))
        );
    }

    if (items.length === 0) {
        tbody.innerHTML = `<tr><td colspan="9" class="text-center text-muted" style="padding: 24px;">No se encontraron insumos para los filtros seleccionados (Área: ${currentArea === 'all' ? 'Todas las Áreas' : currentArea}, Alerta: ${currentStatus === 'all' ? 'Todos' : currentStatus}).</td></tr>`;
        return;
    }

    items.forEach(item => {
        let statusBadge = `<span class="badge-tag green">Normal</span>`;
        if (item.currentStock <= item.minStock) {
            statusBadge = `<span class="badge-tag red">Stock Crítico</span>`;
        }

        const deleteMatBtn = isAssistant ? '' : `<button class="btn btn-xs btn-outline text-red" onclick="deleteInventoryItem('${item.code}')" title="Eliminar Insumo"><i class="fa-solid fa-trash"></i></button>`;

        // Parse portions if fraccionado
        let stockDisplay = `${item.currentStock} ${item.unit}`;
        let minStockDisplay = `${item.minStock} ${item.unit}`;
        
        const portionsPerUnit = parsePortions(item.unit);
        if (portionsPerUnit) {
            const units = Math.floor(item.currentStock);
            const portions = Math.round((item.currentStock - units) * portionsPerUnit);
            const baseUnit = item.unit.replace(/\s*\(\d+\s*porciones\)/i, '').trim();
            stockDisplay = `<strong>${units}</strong> ${baseUnit} y <strong>${portions}</strong> / ${portionsPerUnit} porc.`;
            minStockDisplay = `${item.minStock} ${baseUnit}`;
        }

        const areaInfo = typeof getAreaIconInfo === 'function' ? getAreaIconInfo(item.area) : { icon: 'fa-hospital', color: '#64748b', bg: 'rgba(100,116,139,0.1)' };

        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong>${item.code}</strong></td>
            <td>
                <span class="badge-tag" style="background: ${areaInfo.bg}; color: ${areaInfo.color}; font-weight: 700; display: inline-flex; align-items: center; gap: 4px;">
                    <i class="fa-solid ${areaInfo.icon}"></i> ${item.area}
                </span>
            </td>
            <td><strong>${item.name}</strong></td>
            <td><span class="badge-tag gray" style="font-size: 0.72rem;">${item.category || 'General'}</span></td>
            <td>${stockDisplay}</td>
            <td>${minStockDisplay}</td>
            <td>${item.expiryDate || 'N/A'}</td>
            <td>${statusBadge}</td>
            <td>
                <div class="actions-cell-group">
                    <button class="btn btn-xs btn-outline" onclick="adjustStockPrompt('${item.code}')">+ / - Ajustar</button>
                    ${deleteMatBtn}
                </div>
            </td>
        `;
        tbody.appendChild(tr);
    });
    window.checkGlobalStockAlerts();
}

window.adjustStockPrompt = async function(code) {
    Swal.fire({
        title: 'Ajuste de Insumo',
        text: 'Ingrese la cantidad a ajustar (+ para agregar, - para restar):',
        input: 'number',
        inputValue: 5,
        showCancelButton: true,
        confirmButtonText: 'Aplicar ajuste',
        cancelButtonText: 'Cancelar'
    }).then(async (result) => {
        if (result.isConfirmed && result.value !== '') {
            const qty = parseInt(result.value);
            if (!isNaN(qty)) {
                window.kardex.updateStock(code, qty);
                await renderInventoryTable();
                await renderDashboard();
                Swal.fire({ icon: 'success', title: 'Stock actualizado', timer: 1500, showConfirmButton: false });
            }
        }
    });
};

window.deleteInventoryItem = async function(code) {
    const user = getCurrentUser();
    if (user && user.role.toLowerCase().includes('asistente')) {
        Swal.fire({ icon: 'warning', title: 'Acción denegada', text: 'Solo el Odontólogo Principal puede eliminar insumos del Kardex.' });
        return;
    }

    const items = await SupabaseDataService.getInventory();
    const item = items.find(i => i.code === code || i.id === code);

    Swal.fire({
        title: '¿Mover insumo a la Papelera?',
        text: `El insumo ${item ? item.name : code} se moverá a la Papelera de Reciclaje. Podrá restaurarlo desde Ajustes.`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ef4444',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Sí, mover a papelera',
        cancelButtonText: 'Cancelar'
    }).then(async (result) => {
        if (result.isConfirmed) {
            if (window.moveToTrash && item) {
                await window.moveToTrash('inventory', item, item.name);
            }
            await SupabaseDataService.deleteInventoryItem(code);
            await renderInventoryTable();
            await renderDashboard();
            Swal.fire({ icon: 'success', title: 'Insumo movido a la papelera', text: 'Puede restaurarlo en Ajustes > Papelera de Reciclaje.', timer: 1800, showConfirmButton: false });
        }
    });
};

window.checkGlobalStockAlerts = async function() {
    let items = [];
    if (window.kardex && window.kardex.getAllItems().length > 0) {
        items = window.kardex.getAllItems();
    } else {
        items = await SupabaseDataService.getInventory();
    }
    const criticalItems = items.filter(i => (i.currentStock !== undefined && i.currentStock < 5) || i.currentStock <= (i.minStock || 5));
    
    const badge = document.getElementById('nav-stock-alert-badge');
    if (badge) {
        if (criticalItems.length > 0) {
            badge.innerText = criticalItems.length;
            badge.classList.remove('hidden');
        } else {
            badge.classList.add('hidden');
        }
    }

    const alertBox = document.getElementById('dashboard-stock-alerts');
    if (alertBox) {
        alertBox.innerHTML = '';
        if (criticalItems.length > 0) {
            const renderStockItem = (a) => `
                <div style="padding: 8px 12px; border-radius: 6px; background: rgba(239, 68, 68, 0.08); border: 1px solid rgba(239, 68, 68, 0.25); margin-bottom: 8px; font-size: 0.82rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 6px;">
                    <div>
                        <strong style="color: #b91c1c;">${a.name}:</strong> ${a.currentStock} ${a.unit || 'U'} restantes (Mín: ${a.minStock || 5})
                    </div>
                    <span class="badge-tag red" style="font-size: 0.7rem; font-weight: 700;">Stock Crítico</span>
                </div>
            `;

            const hasMoreThan5 = criticalItems.length > 5;
            const visibleItems = hasMoreThan5 ? criticalItems.slice(0, 5) : criticalItems;
            const remainingItems = hasMoreThan5 ? criticalItems.slice(5) : [];

            let itemsHtml = visibleItems.map(renderStockItem).join('');
            let extraHtml = '';

            if (hasMoreThan5) {
                extraHtml = `
                    <div id="stock-alerts-extra" style="display: none;">
                        ${remainingItems.map(renderStockItem).join('')}
                    </div>
                    <div class="dashboard-toggle-wrap">
                        <button type="button" class="btn-dashboard-toggle" id="btn-toggle-stock-alerts" onclick="window.toggleDashboardList('stock-alerts-extra', 'btn-toggle-stock-alerts', ${remainingItems.length})">
                            <i class="fa-solid fa-chevron-down"></i> Ver más (${remainingItems.length} restantes)
                        </button>
                    </div>
                `;
            }

            alertBox.innerHTML = `
                <div style="margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;">
                    <span style="font-size: 0.85rem; font-weight: 700; color: #dc2626;"><i class="fa-solid fa-triangle-exclamation"></i> ${criticalItems.length} insumos con stock crítico (< 5)</span>
                    <button class="btn btn-xs btn-outline" style="border-color: #0891b2; color: #0891b2; font-weight: 600;" onclick="window.copyStockReorderList()"><i class="fa-solid fa-clipboard-list"></i> Copiar Lista de Reposición</button>
                </div>
                ${itemsHtml}
                ${extraHtml}
            `;
        } else {
            alertBox.innerHTML = `<span class="text-muted" style="font-size: 0.85rem;"><i class="fa-solid fa-circle-check text-green"></i> Todos los insumos cuentan con stock adecuado.</span>`;
        }
    }
};

window.copyStockReorderList = function() {
    if (!window.kardex) return;
    const items = window.kardex.getAllItems();
    const criticalItems = items.filter(i => (i.currentStock !== undefined && i.currentStock < 5) || i.currentStock <= (i.minStock || 5));
    if (criticalItems.length === 0) {
        Swal.fire({ icon: 'info', title: 'Inventario Completo', text: 'No hay insumos que requieran reposición en este momento.' });
        return;
    }

    let text = `📋 ORDEN DE REPOSICIÓN DE INSUMOS - DENTALCARE PRO\nFecha: ${new Date().toLocaleDateString('es-ES')}\n\n`;
    criticalItems.forEach((it, idx) => {
        const needed = Math.max(10, (it.minStock || 5) * 2 - it.currentStock);
        text += `${idx + 1}. ${it.name} (${it.code || 'N/A'})\n   - Stock Actual: ${it.currentStock} ${it.unit || 'U'}\n   - Cantidad a Solicitar: ${needed} ${it.unit || 'U'}\n\n`;
    });

    navigator.clipboard.writeText(text).then(() => {
        Swal.fire({
            icon: 'success',
            title: '¡Lista Copiada al Portapapeles!',
            text: 'Puedes pegarla en WhatsApp, correo o enviarla directamente a tu proveedor de insumos.',
            timer: 2500,
            showConfirmButton: false
        });
    }).catch(() => {
        Swal.fire({ title: 'Lista de Reposición', html: `<pre style="text-align:left; font-size:0.8rem;">${text}</pre>` });
    });
};

async function renderPricingTable(filter = 'all', searchQuery = '') {
    const tbody = document.getElementById('pricing-table-body');
    if (!tbody) return;

    // Dynamic header: "Tiempo de Espera" for Laboratorio, "Tiempo Silla (min)" otherwise
    const thTime = document.getElementById('th-pricing-time');
    const isLabFilter = (filter && filter.toLowerCase() === 'laboratorio');
    if (thTime) {
        if (isLabFilter) {
            thTime.innerHTML = '<i class="fa-solid fa-clock text-purple"></i> Tiempo de Espera';
            thTime.title = 'Tiempo estimado para tener listos y entregar los resultados';
        } else {
            thTime.innerHTML = 'Tiempo Silla (min)';
            thTime.title = 'Tiempo estimado de atención en sillón (minutos)';
        }
    }

    tbody.innerHTML = '';
    let baremo = await SupabaseDataService.getBaremo();
    const rate = getExchangeRate();
    const currentUser = getCurrentUser();
    const isAssistant = currentUser && currentUser.role.toLowerCase().includes('asistente');

    // Ensure each service has an area assigned
    baremo.forEach(p => {
        if (!p.area) {
            p.area = detectClinicalArea(p.category, p.name);
        }
    });

    // Apply Filter by Area or Category
    if (filter !== 'all') {
        const fLower = filter.toLowerCase();
        baremo = baremo.filter(p => 
            (p.area && p.area.toLowerCase() === fLower) ||
            (p.category && p.category.toLowerCase() === fLower) ||
            (fLower === 'odontología' && (p.area === 'Odontología' || ['operatoria', 'endodoncia', 'cirugía', 'ortodoncia', 'estética', 'prótesis', 'prevención', 'diagnóstico'].includes((p.category || '').toLowerCase())))
        );
    }

    // Apply Search
    if (searchQuery && searchQuery.trim() !== '') {
        const q = searchQuery.toLowerCase();
        baremo = baremo.filter(p => 
            (p.code && p.code.toLowerCase().includes(q)) ||
            (p.name && p.name.toLowerCase().includes(q)) ||
            (p.area && p.area.toLowerCase().includes(q)) ||
            (p.category && p.category.toLowerCase().includes(q))
        );
    }

    if (baremo.length === 0) {
        tbody.innerHTML = `<tr><td colspan="10" class="text-center text-muted" style="padding: 24px;">No se encontraron servicios para el área o filtro "${filter}".</td></tr>`;
        return;
    }

    baremo.forEach(p => {
        const priceVES = (p.priceUSD * rate).toFixed(2);
        const deleteSrvBtn = isAssistant ? '' : `<button class="btn btn-xs btn-outline text-red" onclick="deletePricingService('${p.code}')" title="Eliminar Servicio"><i class="fa-solid fa-trash"></i></button>`;
        const areaInfo = typeof getAreaIconInfo === 'function' ? getAreaIconInfo(p.area) : { icon: 'fa-hospital', color: '#64748b', bg: 'rgba(100,116,139,0.1)' };

        const isLabService = (p.area && p.area.toLowerCase() === 'laboratorio') || isLabFilter;
        const timeDisplay = isLabService 
            ? (isLabFilter ? `${p.chairTimeMin} min` : `${p.chairTimeMin} min <small class="text-purple" style="font-size:0.75rem; font-weight:600;" title="Tiempo de espera para resultados">(Espera)</small>`)
            : `${p.chairTimeMin} min`;

        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong>${p.code}</strong></td>
            <td>
                <span class="badge-tag" style="background: ${areaInfo.bg}; color: ${areaInfo.color}; font-weight: 700; display: inline-flex; align-items: center; gap: 4px;">
                    <i class="fa-solid ${areaInfo.icon}"></i> ${p.area}
                </span>
            </td>
            <td><span class="badge-tag blue" style="font-size: 0.72rem;">${p.category || 'General'}</span></td>
            <td><strong>${p.name}</strong></td>
            <td class="text-cyan"><strong>$${p.priceUSD.toFixed(2)}</strong></td>
            <td>Bs. ${priceVES}</td>
            <td><strong>$${(p.hygienistBonus || 0).toFixed(2)}</strong></td>
            <td>${timeDisplay}</td>
            <td>${p.materials ? p.materials.length : 0} insumos</td>
            <td>
                <div class="actions-cell-group">
                    ${deleteSrvBtn}
                </div>
            </td>
        `;
        tbody.appendChild(tr);
    });
}

window.deletePricingService = async function(code) {
    const user = getCurrentUser();
    if (user && user.role.toLowerCase().includes('asistente')) {
        Swal.fire({ icon: 'warning', title: 'Acción denegada', text: 'Solo el Odontólogo Principal puede modificar el Baremo de Precios maestro.' });
        return;
    }

    const services = await SupabaseDataService.getPricing();
    const service = services.find(s => s.code === code || s.id === code);

    Swal.fire({
        title: '¿Mover servicio a la Papelera?',
        text: `El servicio ${service ? service.name : code} se moverá a la Papelera de Reciclaje. Podrá restaurarlo desde Ajustes.`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ef4444',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Sí, mover a papelera',
        cancelButtonText: 'Cancelar'
    }).then(async (result) => {
        if (result.isConfirmed) {
            if (window.moveToTrash && service) {
                await window.moveToTrash('pricing', service, service.name);
            }
            await SupabaseDataService.deleteBaremoService(code);
            await renderPricingTable();
            Swal.fire({ icon: 'success', title: 'Servicio movido a la papelera', text: 'Puede restaurarlo en Ajustes > Papelera de Reciclaje.', timer: 1800, showConfirmButton: false });
        }
    });
};

// Helper to identify if a role is purely administrative (System User)
function isSystemAdminRole(roleStr) {
    if (!roleStr) return false;
    const r = roleStr.toLowerCase().trim();
    // Clinical roles take precedence
    if (r.includes('odont') || r.includes('médico') || r.includes('medico') || r.includes('cirujano') || r.includes('enferm') || r.includes('asistente dental')) {
        return false;
    }
    return r.includes('admin') || r.includes('gerente') || r.includes('recep') || r.includes('caja') || r.includes('factura');
}
window.isSystemAdminRole = isSystemAdminRole;

// ==========================================
// MOTOR DE RENDIMIENTO CLÍNICO & INGRESOS
// ==========================================
let _clinicPerfCache = null;
let _clinicPerfCacheTime = 0;

window.getClinicPerformanceSummary = async function(forceRefresh = false) {
    const now = Date.now();
    if (!forceRefresh && _clinicPerfCache && (now - _clinicPerfCacheTime < 4000)) {
        return _clinicPerfCache;
    }

    let invoices = [];
    try { invoices = await SupabaseDataService.getInvoices(forceRefresh); } catch(e) {}
    
    let patients = [];
    try { patients = await SupabaseDataService.getPatients(); } catch(e) {}
    
    let appointments = [];
    try { appointments = await SupabaseDataService.getAppointments(); } catch(e) {}

    let users = [];
    try { users = await SupabaseDataService.getUsers(); } catch(e) {}

    const doctorStats = {};
    const specialtyStats = {};
    let totalRevenueUSD = 0;
    let totalAttended = 0;

    // Initialize doctorStats for all users
    users.forEach(u => {
        const docKey = String(u.id);
        doctorStats[docKey] = {
            id: u.id,
            name: u.fullname || u.name || 'Médico',
            role: u.role || 'Especialista',
            specialty: (u.doctorProfile && u.doctorProfile.specialty) || '',
            totalUSD: 0,
            attendedCount: 0
        };
    });

    const findDoctor = (docName, docId) => {
        if (docId && doctorStats[String(docId)]) return doctorStats[String(docId)];
        if (!docName) return null;
        const norm = docName.toLowerCase().replace(/^(dr\.|dra\.|doctor|doctora)\s+/i, '').trim();
        for (const k in doctorStats) {
            const uName = doctorStats[k].name.toLowerCase().replace(/^(dr\.|dra\.|doctor|doctora)\s+/i, '').trim();
            if (uName && (uName.includes(norm) || norm.includes(uName))) return doctorStats[k];
        }
        return null;
    };

    const normalizeArea = (rawArea, concept) => {
        if (typeof detectClinicalArea === 'function') {
            return detectClinicalArea(rawArea || '', concept || '');
        }
        return rawArea || 'Medicina General';
    };

    const processedPaymentIds = new Set();

    // 1. Ingresos por abonos de pacientes (historial clínico y caja)
    patients.forEach(p => {
        const payments = (p.metadata && p.metadata.payments) || p.payments || [];
        payments.forEach(pay => {
            const payId = pay.id || pay.docId || `${p.id}-${pay.date}-${pay.paidUSD}`;
            if (processedPaymentIds.has(payId)) return;
            processedPaymentIds.add(payId);

            const amt = parseFloat(pay.paidUSD || pay.amountRef || pay.amount || 0);
            if (amt <= 0) return;

            totalRevenueUSD += amt;

            const area = normalizeArea(pay.specialty || pay.area, pay.concept);
            if (!specialtyStats[area]) specialtyStats[area] = { name: area, totalUSD: 0, count: 0 };
            specialtyStats[area].totalUSD += amt;
            specialtyStats[area].count++;

            const doc = findDoctor(pay.doctor, pay.doctorId);
            if (doc) {
                doc.totalUSD += amt;
                doc.attendedCount++;
            }
        });
    });

    // 2. Ingresos por facturas clínicas
    invoices.forEach(inv => {
        if (processedPaymentIds.has(inv.id)) return;
        processedPaymentIds.add(inv.id);

        const amt = parseFloat(inv.paidRef || inv.totalRef || inv.totalUSD || inv.total || 0);
        if (amt <= 0) return;

        totalRevenueUSD += amt;

        const conceptStr = (inv.items || []).map(i => i.name).join(' ');
        const area = normalizeArea(inv.specialty || inv.category, conceptStr);
        if (!specialtyStats[area]) specialtyStats[area] = { name: area, totalUSD: 0, count: 0 };
        specialtyStats[area].totalUSD += amt;
        specialtyStats[area].count++;

        const doc = findDoctor(inv.doctor || inv.doctorName, inv.doctorId || inv.doctor_id);
        if (doc) {
            doc.totalUSD += amt;
            doc.attendedCount++;
        }
    });

    // 3. Citas asistenciales atendidas
    appointments.forEach(app => {
        if (app.status === 'Completada' || app.status === 'Atendida') {
            totalAttended++;
            const doc = findDoctor(app.doctorName, app.doctorId || app.doctor_id);
            if (doc) {
                if (doc.attendedCount === 0) doc.attendedCount++;
            }
            const area = normalizeArea(app.specialty, app.treatment);
            if (!specialtyStats[area]) specialtyStats[area] = { name: area, totalUSD: 0, count: 0 };
            if (specialtyStats[area].count === 0) specialtyStats[area].count++;
        }
    });

    // Determine Top Doctor
    const clinicalDocs = Object.values(doctorStats).filter(d => !isSystemAdminRole(d.role));
    clinicalDocs.sort((a, b) => b.totalUSD - a.totalUSD);
    const topDoctor = clinicalDocs.length > 0 ? clinicalDocs[0] : null;

    // Determine Top Specialty
    const allSpecs = Object.values(specialtyStats);
    allSpecs.sort((a, b) => b.totalUSD - a.totalUSD);
    const topSpecialty = allSpecs.length > 0 ? allSpecs[0] : null;

    const activeDocsCount = clinicalDocs.length || 1;
    const avgDoctorRevenue = totalRevenueUSD / activeDocsCount;

    _clinicPerfCache = {
        doctorStats,
        specialtyStats,
        findDoctor,
        topDoctor,
        topSpecialty,
        totalRevenueUSD,
        totalAttended,
        avgDoctorRevenue
    };
    _clinicPerfCacheTime = now;
    return _clinicPerfCache;
};

window.doctorRevenueSortDesc = false;

window.toggleDoctorRevenueSort = async function() {
    window.doctorRevenueSortDesc = !window.doctorRevenueSortDesc;
    const sortBtn = document.getElementById('btn-sort-doctor-revenue');
    const sortText = document.getElementById('sort-doctor-btn-text');
    if (sortBtn) {
        if (window.doctorRevenueSortDesc) {
            sortBtn.style.backgroundColor = 'rgba(245, 158, 11, 0.15)';
            sortBtn.style.borderColor = '#f59e0b';
            sortBtn.style.color = '#b45309';
            if (sortText) sortText.textContent = 'Mayor a Menor $';
        } else {
            sortBtn.style.backgroundColor = '';
            sortBtn.style.borderColor = '#cbd5e1';
            sortBtn.style.color = '';
            if (sortText) sortText.textContent = 'Mayor Ingreso';
        }
    }
    const activeFilterBtn = document.querySelector('#view-users .filter-card .filter-btn.active');
    const filter = activeFilterBtn ? activeFilterBtn.dataset.filter : 'all';
    const searchQuery = document.getElementById('users-table-search')?.value || '';
    await renderUsersTable(filter, searchQuery);
};

// ==========================================
// GESTIÓN DE PERSONAL MÉDICO Y ASISTENCIAL
// ==========================================
async function renderUsersTable(filter = 'all', searchQuery = '') {
    const tbody = document.getElementById('users-table-body');
    if (!tbody) return;

    tbody.innerHTML = '';
    let users = await SupabaseDataService.getUsers();

    // In Personal Médico view, ONLY show clinical staff (exclude pure system/administrative roles)
    users = users.filter(u => !isSystemAdminRole(u.role));

    // Performance metrics
    const perf = await window.getClinicPerformanceSummary();

    // Update Top 4 KPI cards in view-users
    const topDocNameEl = document.getElementById('user-stat-top-doctor-name');
    const topDocSubEl = document.getElementById('user-stat-top-doctor-sub');
    const totalRevEl = document.getElementById('user-stat-total-revenue');
    const totalAttEl = document.getElementById('user-stat-total-attended');
    const avgRevEl = document.getElementById('user-stat-avg-revenue');

    if (topDocNameEl) {
        if (perf.topDoctor && perf.topDoctor.totalUSD > 0) {
            topDocNameEl.textContent = perf.topDoctor.name;
            if (topDocSubEl) topDocSubEl.innerHTML = `<i class="fa-solid fa-arrow-trend-up"></i> $${perf.topDoctor.totalUSD.toFixed(2)} USD (${perf.topDoctor.attendedCount} ${perf.topDoctor.attendedCount === 1 ? 'atención' : 'atenciones'})`;
        } else {
            topDocNameEl.textContent = users[0] ? (users[0].fullname || users[0].name) : 'Sin registro';
            if (topDocSubEl) topDocSubEl.innerHTML = `<i class="fa-solid fa-circle-info"></i> Esperando atención`;
        }
    }
    if (totalRevEl) totalRevEl.innerHTML = `$${perf.totalRevenueUSD.toFixed(2)} <small style="font-size: 0.75rem; color: #64748b;">USD</small>`;
    if (totalAttEl) totalAttEl.textContent = perf.totalAttended;
    if (avgRevEl) avgRevEl.innerHTML = `$${perf.avgDoctorRevenue.toFixed(2)} <small style="font-size: 0.75rem; color: #64748b;">USD</small>`;

    // Apply Filter
    if (filter !== 'all') {
        users = users.filter(u => {
            if (!u.role) return false;
            const role = u.role.toLowerCase();
            const f = filter.toLowerCase();
            if (f === 'médico' || f === 'medico') {
                return role.includes('odontólogo') || role.includes('médico') || role.includes('medico') || role.includes('cirujano') || role.includes('especialista');
            }
            if (f === 'asistente') {
                return role.includes('asistente') || role.includes('enfermer') || role.includes('auxiliar');
            }
            return role.includes(f);
        });
    }

    // Apply Search
    if (searchQuery && searchQuery.trim() !== '') {
        const q = searchQuery.toLowerCase();
        users = users.filter(u => 
            (u.fullname && u.fullname.toLowerCase().includes(q)) ||
            (u.email && u.email.toLowerCase().includes(q)) ||
            (u.role && u.role.toLowerCase().includes(q)) ||
            (u.license && u.license.toLowerCase().includes(q))
        );
    }

    // Apply Revenue Sort if active
    if (window.doctorRevenueSortDesc) {
        users.sort((a, b) => {
            const revA = (perf.doctorStats[String(a.id)] || perf.findDoctor(a.fullname))?.totalUSD || 0;
            const revB = (perf.doctorStats[String(b.id)] || perf.findDoctor(b.fullname))?.totalUSD || 0;
            return revB - revA;
        });
    }

    if (users.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="text-center text-muted" style="padding: 24px;">No se encontró personal médico o asistencial registrado con estos filtros.</td></tr>`;
        return;
    }

    users.forEach(u => {
        const tr = document.createElement('tr');
        const docPerf = (perf.doctorStats && (perf.doctorStats[String(u.id)] || perf.findDoctor(u.fullname))) || { totalUSD: 0, attendedCount: 0 };
        const isTop = perf.topDoctor && (String(perf.topDoctor.id) === String(u.id) || perf.topDoctor.name === u.fullname) && docPerf.totalUSD > 0;

        const docProf = u.doctorProfile || u.doctor_profile || {};
        const extraSpecs = docProf.additionalSpecialties || [];
        let extraSpecsHtml = '';
        if (extraSpecs && extraSpecs.length > 0) {
            extraSpecsHtml = `<div style="display:flex; flex-wrap:wrap; gap:3px; margin-top:4px;">` + 
                extraSpecs.map(es => `<span class="badge-tag purple" style="font-size:0.68rem; padding:1px 5px;"><i class="fa-solid fa-tag"></i> ${es}</span>`).join('') +
                `</div>`;
        }

        tr.innerHTML = `
            <td><strong>${u.fullname}</strong></td>
            <td>${u.email}</td>
            <td>
                <span class="badge-tag blue" style="font-weight:600;"><i class="fa-solid fa-stethoscope"></i> ${u.role}</span>
                ${docProf.specialty && docProf.specialty !== u.role ? `<div style="font-size:0.75rem; color:#0284c7; font-weight:600; margin-top:2px;">${docProf.specialty}</div>` : ''}
                ${extraSpecsHtml}
            </td>
            <td>${u.license && u.license !== 'N/A' ? `<span style="font-family:monospace; font-weight:700; color:#0369a1;">${u.license}</span>` : '<span class="text-muted">N/A</span>'}</td>
            <td>
                <div style="display: flex; flex-direction: column; gap: 2px;">
                    <div style="display: flex; align-items: center; gap: 6px;">
                        <strong style="font-size: 0.95rem; color: #0f172a;">$${docPerf.totalUSD.toFixed(2)}</strong>
                        <small style="color: #64748b; font-size: 0.72rem; font-weight: 600;">USD</small>
                        ${isTop ? '<span class="badge-tag amber" style="font-size: 0.68rem; padding: 1px 6px; font-weight: 700; background: rgba(245, 158, 11, 0.15); color: #b45309;"><i class="fa-solid fa-crown"></i> #1 Top</span>' : ''}
                    </div>
                    <small style="color: #64748b; font-size: 0.78rem;">
                        <i class="fa-solid fa-clipboard-check text-green"></i> ${docPerf.attendedCount} ${docPerf.attendedCount === 1 ? 'atención' : 'atenciones'}
                    </small>
                </div>
            </td>
            <td><span class="badge-tag green">${u.status || 'Activo'}</span></td>
            <td>${u.createdAt || '-'}</td>
            <td>
                <button class="btn btn-xs btn-outline text-cyan" onclick="editUser('${u.id}')" title="Editar Ficha Médica" style="margin-right: 4px;"><i class="fa-solid fa-user-pen"></i></button>
                <button class="btn btn-xs btn-outline text-red" onclick="deleteUser('${u.id}')" title="Eliminar"><i class="fa-solid fa-user-xmark"></i></button>
            </td>
        `;
        tbody.appendChild(tr);
    });
}

// ==========================================
// GESTIÓN DE USUARIOS DEL SISTEMA (AJUSTES)
// ==========================================
window.renderSystemUsersTable = async function() {
    const tbody = document.getElementById('system-users-table-tbody');
    if (!tbody) return;

    tbody.innerHTML = `<tr><td colspan="6" class="text-center text-muted" style="padding: 20px;"><i class="fa-solid fa-spinner fa-spin text-cyan"></i> Cargando usuarios del sistema...</td></tr>`;

    let users = await SupabaseDataService.getUsers();

    // Filter to only administrative & system users
    let sysUsers = users.filter(u => isSystemAdminRole(u.role) || !u.role || u.role.toLowerCase().includes('admin'));

    if (sysUsers.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" class="text-center text-muted" style="padding: 24px;">No hay cuentas administrativas registradas. Cree una nueva con el botón "+ Crear Usuario del Sistema".</td></tr>`;
        return;
    }

    tbody.innerHTML = '';
    sysUsers.forEach(u => {
        const tr = document.createElement('tr');
        const isSuper = (u.role || '').toLowerCase().includes('super') || (u.role || '').toLowerCase().includes('gerente');
        const roleBadgeClass = isSuper ? 'green' : 'blue';

        tr.innerHTML = `
            <td>
                <strong>${u.fullname}</strong>
                ${isSuper ? ' <small class="badge-tag green" style="font-size:0.68rem; margin-left:4px;">Dirección</small>' : ''}
            </td>
            <td><span style="font-family:monospace; color:#334155;">${u.email}</span></td>
            <td><span class="badge-tag ${roleBadgeClass}" style="font-weight:700;"><i class="fa-solid fa-shield-halved"></i> ${u.role || 'Administrador'}</span></td>
            <td><span class="badge-tag ${u.status === 'Inactivo' ? 'red' : 'green'}">${u.status || 'Activo'}</span></td>
            <td>${u.createdAt || '-'}</td>
            <td style="text-align: center;">
                <button class="btn btn-xs btn-outline text-cyan" onclick="window.editSystemUser('${u.id}')" title="Editar Cuenta" style="margin-right: 4px;"><i class="fa-solid fa-user-pen"></i></button>
                <button class="btn btn-xs btn-outline text-red" onclick="window.deleteSystemUser('${u.id}')" title="Eliminar"><i class="fa-solid fa-trash"></i></button>
            </td>
        `;
        tbody.appendChild(tr);
    });
};

window.openCreateSystemUserModal = function() {
    const form = document.getElementById('form-system-user');
    if (form) form.reset();

    const idInput = document.getElementById('sys-user-id');
    if (idInput) idInput.value = '';

    const title = document.getElementById('modal-system-user-title');
    if (title) title.innerHTML = '<i class="fa-solid fa-users-gear text-cyan"></i> Crear Cuenta de Usuario del Sistema';

    const saveBtn = document.getElementById('btn-save-system-user');
    if (saveBtn) saveBtn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Usuario';

    const passInput = document.getElementById('sys-user-password');
    if (passInput) {
        passInput.required = true;
        passInput.placeholder = '••••••••';
        passInput.value = '';
    }
    const hint = document.getElementById('sys-user-password-hint');
    if (hint) hint.classList.add('hidden');

    openModal('modal-system-user');
};

window.editSystemUser = async function(userId) {
    const users = await SupabaseDataService.getUsers();
    const user = users.find(u => String(u.id) === String(userId));
    if (!user) {
        Swal.fire({ icon: 'error', title: 'No encontrado', text: 'No se encontró el usuario seleccionado.' });
        return;
    }

    const form = document.getElementById('form-system-user');
    if (form) form.reset();

    document.getElementById('sys-user-id').value = user.id;
    document.getElementById('sys-user-fullname').value = user.fullname || '';
    document.getElementById('sys-user-email').value = user.email || '';

    const passInput = document.getElementById('sys-user-password');
    if (passInput) {
        passInput.required = false;
        passInput.placeholder = '(Conservar contraseña actual)';
        passInput.value = '';
    }
    const hint = document.getElementById('sys-user-password-hint');
    if (hint) hint.classList.remove('hidden');

    const roleSel = document.getElementById('sys-user-role');
    if (roleSel) {
        roleSel.value = user.role;
        if (!roleSel.value && user.role) {
            for (let i = 0; i < roleSel.options.length; i++) {
                if (roleSel.options[i].value.toLowerCase().includes(user.role.toLowerCase())) {
                    roleSel.selectedIndex = i;
                    break;
                }
            }
        }
    }

    const statusSel = document.getElementById('sys-user-status');
    if (statusSel) statusSel.value = user.status || 'Activo';

    const title = document.getElementById('modal-system-user-title');
    if (title) title.innerHTML = '<i class="fa-solid fa-user-pen text-cyan"></i> Editar Usuario del Sistema';

    const saveBtn = document.getElementById('btn-save-system-user');
    if (saveBtn) saveBtn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios';

    openModal('modal-system-user');
};

window.deleteSystemUser = async function(userId) {
    const currentUser = getCurrentUser();
    if (currentUser && String(currentUser.id) === String(userId)) {
        Swal.fire({ icon: 'warning', title: 'Acción inválida', text: 'No puede eliminar su propia cuenta de sesión actual.' });
        return;
    }

    const users = await SupabaseDataService.getUsers();
    const target = users.find(u => String(u.id) === String(userId));
    if (!target) return;

    Swal.fire({
        title: `¿Eliminar a ${target.fullname}?`,
        text: 'Se revocará el acceso al sistema para este usuario administrativo.',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ef4444',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Sí, eliminar',
        cancelButtonText: 'Cancelar'
    }).then(async (result) => {
        if (result.isConfirmed) {
            await SupabaseDataService.deleteUser(userId);
            if (window.logUserAction) {
                await window.logUserAction('Eliminó Usuario del Sistema', 'Ajustes', `Usuario: ${target.fullname} (${target.role})`);
            }
            await window.renderSystemUsersTable();
            Swal.fire({ icon: 'success', title: 'Usuario eliminado', timer: 1800, showConfirmButton: false });
        }
    });
};

function updateRoleScopeHint(role) {
    const hintEl = document.getElementById('u-role-scope-hint');
    if (!hintEl) return;

    const r = (role || '').toLowerCase();
    const isDoctor = r.includes('medico') || r.includes('odont') || r.includes('doctor') || r.includes('dentista') || r.includes('médico') || r.includes('cirujano') || r.includes('especialista');
    const isAssistant = r.includes('asistente') || r.includes('enfermer') || r.includes('auxiliar');

    if (isDoctor) {
        hintEl.innerHTML = `
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px; font-weight:700; color:#0d9488;">
                <i class="fa-solid fa-user-doctor"></i> Médico / Odontólogo Especialista (Área Asistencial)
            </div>
            <p style="margin:0 0 6px 0; font-size:0.82rem;"><strong>Alcance:</strong> Diagnóstico clínico, historias médicas, atención en sillón y evolución.</p>
            <ul style="margin:0; padding-left:18px; font-size:0.79rem; color:var(--text-color); line-height:1.4;">
                <li>Ficha de paciente, Odontograma interactivo y expediente clínico (EHR).</li>
                <li>Emisión de récipes oficiales con código QR y firma digital.</li>
                <li>Agenda médica propia y cálculo de comisiones según baremo asignado.</li>
            </ul>
        `;
    } else if (isAssistant) {
        hintEl.innerHTML = `
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px; font-weight:700; color:#16a34a;">
                <i class="fa-solid fa-hand-holding-medical"></i> Asistente Clínico / Enfermero(a)
            </div>
            <p style="margin:0 0 6px 0; font-size:0.82rem;"><strong>Alcance:</strong> Apoyo asistencial en procedimientos clínicos e inventario.</p>
            <ul style="margin:0; padding-left:18px; font-size:0.79rem; color:var(--text-color); line-height:1.4;">
                <li>Apoyo en toma de signos, fichaje y preparación de materiales en sillón.</li>
                <li>Descargo de insumos consumidos por procedimiento en el Kardex.</li>
            </ul>
        `;
    } else {
        hintEl.innerHTML = `
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px; font-weight:700; color:#0284c7;">
                <i class="fa-solid fa-user-doctor"></i> Personal de Salud y Asistencial
            </div>
            <p style="margin:0; font-size:0.82rem;">Atención asistencial a pacientes con historial clínico y agenda médica.</p>
        `;
    }
}
window.updateRoleScopeHint = updateRoleScopeHint;

window.populateUserModalSelects = async function(docProf = {}) {
    // 1. Especialidad Principal (u-specialty) & Especialidades Adicionales
    const specSel = document.getElementById('u-specialty');
    const addContainer = document.getElementById('u-additional-specialties-container');

    let dynamicSpecs = [];
    if (window.ClinicalERP && window.ClinicalERP.specialties && window.ClinicalERP.specialties.length > 0) {
        dynamicSpecs = window.ClinicalERP.specialties;
    } else {
        try { dynamicSpecs = JSON.parse(localStorage.getItem('vidasana_specialties')) || []; } catch(e) {}
    }

    const existingDocSpecs = [
        docProf.specialty,
        ...(Array.isArray(docProf.additionalSpecialties) ? docProf.additionalSpecialties : []),
        ...(Array.isArray(docProf.specialties) ? docProf.specialties : [])
    ].filter(Boolean);

    const allSpecs = Array.from(new Set([
        'Odontología General', 'Ortodoncia', 'Endodoncia', 'Periodoncia', 'Cirugía Maxilofacial', 'Odontopediatría', 'Prótesis Dental', 'Implantología', 'Odontología Estética',
        'Medicina General', 'Pediatría', 'Ginecología y Obstetricia', 'Cardiología', 'Traumatología y Ortopedia', 'Dermatología', 'Oftalmología', 'Nutrición y Dietética', 'Psicología Clínica',
        'Laboratorio Clínico', 'Rayos X e Imagenología',
        ...dynamicSpecs.map(s => s.name || s.nombre).filter(Boolean),
        ...existingDocSpecs
    ])).sort((a, b) => a.localeCompare(b));

    if (specSel) {
        specSel.innerHTML = allSpecs.map(s => `<option value="${s}">${s}</option>`).join('');
        if (docProf.specialty && allSpecs.includes(docProf.specialty)) {
            specSel.value = docProf.specialty;
        } else if (allSpecs.length > 0) {
            specSel.value = allSpecs[0];
        }
    }

    // Render Additional Specialty Chips
    if (addContainer) {
        const renderChips = () => {
            const currentPrimary = specSel ? specSel.value : '';
            const activeAdditional = new Set(
                (Array.isArray(docProf.additionalSpecialties) ? docProf.additionalSpecialties : (Array.isArray(docProf.specialties) ? docProf.specialties.filter(s => s !== currentPrimary) : []))
            );

            // Preserve any currently clicked active chips before re-rendering
            const existingChips = addContainer.querySelectorAll('.spec-chip.active');
            existingChips.forEach(c => {
                if (c.dataset.specialty && c.dataset.specialty !== currentPrimary) {
                    activeAdditional.add(c.dataset.specialty);
                }
            });

            addContainer.innerHTML = '';
            allSpecs.forEach(spec => {
                if (spec === currentPrimary) return; // Primary specialty is already handled
                const isActive = activeAdditional.has(spec);
                const chip = document.createElement('button');
                chip.type = 'button';
                chip.className = `spec-chip ${isActive ? 'active' : ''}`;
                chip.dataset.specialty = spec;
                chip.innerHTML = `<i class="fa-solid ${isActive ? 'fa-check' : 'fa-plus'}" style="font-size: 0.7rem;"></i> <span>${spec}</span>`;
                chip.onclick = (e) => {
                    e.preventDefault();
                    chip.classList.toggle('active');
                    const nowActive = chip.classList.contains('active');
                    const icon = chip.querySelector('i');
                    if (icon) {
                        icon.className = `fa-solid ${nowActive ? 'fa-check' : 'fa-plus'}`;
                    }
                };
                addContainer.appendChild(chip);
            });
        };

        renderChips();

        if (specSel) {
            specSel.onchange = () => {
                renderChips();
            };
        }
    }

    // 2. Turno (u-shift)
    const shiftSel = document.getElementById('u-shift');
    if (shiftSel) {
        shiftSel.value = docProf.shift || 'morning';
    }

    // 3. Asistente Asignado(a) (u-assistant)
    const asstSel = document.getElementById('u-assistant');
    if (asstSel) {
        let users = await SupabaseDataService.getUsers();
        let staff = [];
        if (SupabaseDataService.getPayrollStaff) {
            staff = await SupabaseDataService.getPayrollStaff().catch(() => []);
        }
        const assistants = users.filter(u => {
            const r = (u.role || '').toLowerCase();
            return r.includes('asist') || r.includes('enferm') || r.includes('auxiliar') || r.includes('higien');
        });
        (staff || []).forEach(st => {
            const r = (st.role || st.puesto || '').toLowerCase();
            if (r.includes('asist') || r.includes('enferm') || r.includes('auxiliar') || r.includes('higien')) {
                if (!assistants.some(a => (a.fullname || '').toLowerCase() === (st.name || '').toLowerCase())) {
                    assistants.push({ id: st.id, fullname: st.name || st.fullname, role: st.role || 'Asistente' });
                }
            }
        });
        asstSel.innerHTML = '<option value="">-- Sin Asistente Asignado --</option>' +
            assistants.map(a => `<option value="${a.id}">${a.fullname} (${a.role || 'Asistente'})</option>`).join('');
        if (docProf.assistantId) asstSel.value = docProf.assistantId;
    }

    // 4. Consultorio Asignado (u-room)
    const roomSel = document.getElementById('u-room');
    if (roomSel) {
        let rooms = await SupabaseDataService.getClinicRooms();
        roomSel.innerHTML = '<option value="">-- Sin Consultorio Fijo --</option>' +
            rooms.map(rm => `<option value="${rm.id}">${rm.name || rm.room_number}</option>`).join('');
        if (docProf.roomId) roomSel.value = docProf.roomId;
    }
};

window.quickAddNewSpecialty = async function() {
    const { value: newSpec } = await Swal.fire({
        title: '<i class="fa-solid fa-stethoscope text-cyan"></i> Nueva Especialidad',
        text: 'Ingrese el nombre de la nueva especialidad médica u odontológica:',
        input: 'text',
        inputPlaceholder: 'ej: Periodoncia, Dermatología, Nutrición...',
        showCancelButton: true,
        confirmButtonText: '<i class="fa-solid fa-check"></i> Guardar y Seleccionar',
        cancelButtonText: 'Cancelar',
        confirmButtonColor: '#0891b2',
        inputValidator: (val) => {
            if (!val || !val.trim()) {
                return 'El nombre de la especialidad no puede estar vacío';
            }
        }
    });

    if (!newSpec || !newSpec.trim()) return;
    const specName = newSpec.trim();

    // Categorize
    const lower = specName.toLowerCase();
    let dept = 'Medicina General';
    let icon = 'fa-stethoscope';
    let color = '#0d9488';
    if (lower.includes('odont') || lower.includes('dent') || lower.includes('ortod') || lower.includes('endod') || lower.includes('periodon') || lower.includes('maxilo') || lower.includes('bucal') || lower.includes('protes') || lower.includes('implant')) {
        dept = 'Odontología';
        icon = 'fa-tooth';
    } else if (lower.includes('lab') || lower.includes('analis') || lower.includes('sangre')) {
        dept = 'Laboratorio';
        icon = 'fa-vials';
        color = '#0284c7';
    } else if (lower.includes('rayos') || lower.includes('rx') || lower.includes('eco') || lower.includes('imagen')) {
        dept = 'Rayos X e Imagen';
        icon = 'fa-x-ray';
        color = '#8b5cf6';
    }

    const specObj = {
        id: 'esp-' + Date.now(),
        name: specName,
        department: dept,
        doctor_commission_pct: 60,
        clinic_commission_pct: 40,
        description: `Especialidad clínica de ${specName}`,
        status: 'Activo',
        icon: icon,
        color: color
    };

    try {
        if (window.SupabaseDataService && window.SupabaseDataService.saveSpecialty) {
            await window.SupabaseDataService.saveSpecialty(specObj);
        }
        if (window.ClinicalERP) {
            if (!window.ClinicalERP.specialties) window.ClinicalERP.specialties = [];
            if (!window.ClinicalERP.specialties.some(s => (s.name || s.nombre).toLowerCase() === specName.toLowerCase())) {
                window.ClinicalERP.specialties.push(specObj);
            }
            if (typeof window.ClinicalERP.renderSpecialties === 'function') {
                window.ClinicalERP.renderSpecialties();
            }
        }
    } catch(e) {
        console.error('Error guardando nueva especialidad:', e);
    }

    // Preserve currently selected additional specialties
    const currentActiveAdditional = Array.from(document.querySelectorAll('#u-additional-specialties-container .spec-chip.active')).map(c => c.dataset.specialty);

    // Re-populate selects and set newly created as primary specialty
    await window.populateUserModalSelects({
        specialty: specName,
        additionalSpecialties: currentActiveAdditional
    });

    Swal.fire({
        icon: 'success',
        title: '¡Especialidad Registrada!',
        text: `La especialidad "${specName}" se ha creado y seleccionado exitosamente.`,
        timer: 1800,
        showConfirmButton: false
    });
};

