    window.updateImportPreviewStats = function() {
        const total = window.pendingImportMaterials.length;
        let valid = 0;
        let errors = 0;

        window.pendingImportMaterials.forEach(item => {
            if (item.code && item.name) valid++;
            else errors++;
        });

        const elTot = document.getElementById('import-preview-total');
        if (elTot) elTot.innerText = total;
        const elVal = document.getElementById('import-preview-valid');
        if (elVal) elVal.innerText = valid;
        const elErr = document.getElementById('import-preview-errors');
        if (elErr) elErr.innerText = errors;

        const btnConfirm = document.getElementById('btn-confirm-import-materials');
        if (btnConfirm) {
            btnConfirm.disabled = (valid === 0);
            btnConfirm.innerHTML = `<i class="fa-solid fa-cloud-arrow-up"></i> Subir ${valid} Insumo${valid === 1 ? '' : 's'} a Base de Datos`;
        }
    };

    window.updatePendingImportField = function(idx, field, val) {
        if (!window.pendingImportMaterials[idx]) return;
        if (field === 'currentStock' || field === 'minStock') {
            window.pendingImportMaterials[idx][field] = parseInt(val) || 0;
        } else {
            window.pendingImportMaterials[idx][field] = (val || '').toString().trim();
        }
        window.updateImportPreviewStats();

        // Highlight input if error
        const inputEl = document.getElementById(`imp-row-${field}-${idx}`);
        if (inputEl && (field === 'code' || field === 'name')) {
            if (!val || !val.toString().trim()) {
                inputEl.style.borderColor = '#dc2626';
                inputEl.style.background = '#fef2f2';
            } else {
                inputEl.style.borderColor = '#cbd5e1';
                inputEl.style.background = '#ffffff';
            }
        }
    };

    window.removePendingImportRow = function(idx) {
        window.pendingImportMaterials.splice(idx, 1);
        window.renderImportMaterialsPreviewTable();
    };

    window.renderImportMaterialsPreviewTable = function() {
        const tbody = document.getElementById('import-preview-tbody');
        if (!tbody) return;

        window.updateImportPreviewStats();

        if (window.pendingImportMaterials.length === 0) {
            tbody.innerHTML = `<tr><td colspan="10" class="text-center text-muted" style="padding: 24px;">No hay registros para mostrar.</td></tr>`;
            return;
        }

        const clinicalAreas = ['Odontología', 'Cardiología', 'Laboratorio', 'Rayos X e Imagen', 'Medicina General', 'Ginecología', 'Pediatría', 'General'];

        tbody.innerHTML = window.pendingImportMaterials.map((item, idx) => {
            const hasError = !item.code || !item.name;
            const rowBg = hasError ? '#fff5f5' : (idx % 2 === 0 ? '#ffffff' : '#f8fafc');

            const areaOptions = clinicalAreas.map(a => 
                `<option value="${a}" ${item.area.toLowerCase() === a.toLowerCase() ? 'selected' : ''}>${a}</option>`
            ).join('');

            return `
                <tr style="background: ${rowBg}; border-bottom: 1px solid #e2e8f0;">
                    <td style="text-align: center; color: #64748b; font-weight: 600;">${idx + 1}</td>
                    <td>
                        <input type="text" id="imp-row-code-${idx}" class="form-control" style="font-size: 0.78rem; padding: 4px 6px; height: 30px; font-weight: 700; ${!item.code ? 'border-color: #dc2626; background: #fef2f2;' : ''}" 
                               value="${item.code || ''}" placeholder="Ej: INS-01" 
                               oninput="window.updatePendingImportField(${idx}, 'code', this.value)">
                    </td>
                    <td>
                        <input type="text" id="imp-row-name-${idx}" class="form-control" style="font-size: 0.78rem; padding: 4px 6px; height: 30px; ${!item.name ? 'border-color: #dc2626; background: #fef2f2;' : ''}" 
                               value="${item.name || ''}" placeholder="Nombre del insumo..." 
                               oninput="window.updatePendingImportField(${idx}, 'name', this.value)">
                    </td>
                    <td>
                        <select class="form-control" style="font-size: 0.76rem; padding: 2px 6px; height: 30px;" 
                                onchange="window.updatePendingImportField(${idx}, 'area', this.value)">
                            ${areaOptions}
                        </select>
                    </td>
                    <td>
                        <input type="text" class="form-control" style="font-size: 0.76rem; padding: 4px 6px; height: 30px;" 
                               value="${item.category || 'Materiales'}" 
                               oninput="window.updatePendingImportField(${idx}, 'category', this.value)">
                    </td>
                    <td style="text-align: center;">
                        <input type="number" min="0" class="form-control" style="font-size: 0.78rem; padding: 4px; height: 30px; text-align: center;" 
                               value="${item.currentStock || 0}" 
                               oninput="window.updatePendingImportField(${idx}, 'currentStock', this.value)">
                    </td>
                    <td style="text-align: center;">
                        <input type="number" min="0" class="form-control" style="font-size: 0.78rem; padding: 4px; height: 30px; text-align: center;" 
                               value="${item.minStock || 0}" 
                               oninput="window.updatePendingImportField(${idx}, 'minStock', this.value)">
                    </td>
                    <td>
                        <input type="text" class="form-control" style="font-size: 0.76rem; padding: 4px 6px; height: 30px;" 
                               value="${item.unit || 'Unidades'}" 
                               oninput="window.updatePendingImportField(${idx}, 'unit', this.value)">
                    </td>
                    <td>
                        <input type="date" class="form-control" style="font-size: 0.74rem; padding: 2px 4px; height: 30px;" 
                               value="${item.expiryDate || ''}" 
                               onchange="window.updatePendingImportField(${idx}, 'expiryDate', this.value)">
                    </td>
                    <td style="text-align: center;">
                        <button type="button" class="btn btn-xs" style="color: #dc2626; background: transparent; border: none; padding: 4px; cursor: pointer;" 
                                title="Quitar de la lista" onclick="window.removePendingImportRow(${idx})">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </td>
                </tr>
            `;
        }).join('');
    };

    window.confirmImportMaterials = async function() {
        const validItems = window.pendingImportMaterials.filter(i => i.code && i.name);
        if (validItems.length === 0) {
            Swal.fire({ icon: 'warning', title: 'Sin insumos válidos', text: 'Por favor complete al menos el código y nombre de los insumos a subir.' });
            return;
        }

        Swal.fire({
            title: 'Guardando en Base de Datos...',
            html: `Subiendo <b>${validItems.length}</b> insumos a Supabase con persistencia dual...`,
            allowOutsideClick: false,
            didOpen: () => {
                Swal.showLoading();
            }
        });

        try {
            if (window.SupabaseDataService) {
                if (typeof window.SupabaseDataService.saveInventoryBatch === 'function') {
                    await window.SupabaseDataService.saveInventoryBatch(validItems);
                } else {
                    for (const it of validItems) {
                        await window.SupabaseDataService.saveInventoryItem(it);
                    }
                }
            }

            // Close preview modal and clean up state
            window.closeImportMaterialsPreview();

            // Force refresh inventory cache immediately so no F5/cache clearing is required
            await SupabaseDataService.getInventory(true);

            // Re-render inventory table and dashboard
            window.currentInventoryAreaFilter = 'all';
            document.querySelectorAll('#inventory-area-filters .filter-btn').forEach(b => {
                if (b.dataset.areaFilter === 'all') b.classList.add('active');
                else b.classList.remove('active');
            });

            await renderInventoryTable('all', null, 'all');
            await renderDashboard();

            // Female voice notification
            if ('speechSynthesis' in window) {
                try {
                    const utter = new SpeechSynthesisUtterance('Los insumos se han subido e importado con éxito a la base de datos.');
                    utter.lang = 'es-ES';
                    utter.rate = 1.0;
                    utter.pitch = 1.15; // slightly higher pitch for friendly female tone
                    const voices = window.speechSynthesis.getVoices();
                    const femaleVoice = voices.find(v => v.lang.startsWith('es') && (v.name.toLowerCase().includes('female') || v.name.toLowerCase().includes('sabina') || v.name.toLowerCase().includes('helena') || v.name.toLowerCase().includes('monica') || v.name.toLowerCase().includes('paulina') || v.name.toLowerCase().includes('lucia')));
                    if (femaleVoice) utter.voice = femaleVoice;
                    window.speechSynthesis.speak(utter);
                } catch(e) {}
            }

            Swal.fire({
                icon: 'success',
                title: '¡Importación Completada con Éxito!',
                html: `Se han subido y sincronizado <b>${validItems.length}</b> insumos en la base de datos en la nube. Ya están disponibles en pantalla.`,
                timer: 3000,
                showConfirmButton: false
            });
        } catch(err) {
            console.error('Error in confirmImportMaterials:', err);
            Swal.fire({ icon: 'error', title: 'Error al importar', text: err.message || 'Ocurrió un error al guardar en la nube.' });
        }
    };

    const btnImportMat = document.getElementById('btn-import-materials');
    const importMatFile = document.getElementById('import-materials-file');
    if (btnImportMat && importMatFile) {
        btnImportMat.onclick = () => importMatFile.click();
        importMatFile.onchange = async (e) => {
            const file = e.target.files[0];
            if (!file) return;

            Swal.fire({
                title: 'Leyendo Excel...',
                text: 'Generando vista previa de validación...',
                allowOutsideClick: false,
                didOpen: () => {
                    Swal.showLoading();
                }
            });

            const reader = new FileReader();
            reader.onload = async (evt) => {
                try {
                    const data = new Uint8Array(evt.target.result);
                    const workbook = XLSX.read(data, { type: 'array' });
                    const sheetName = workbook.SheetNames[0];
                    const worksheet = workbook.Sheets[sheetName];
                    const jsonData = XLSX.utils.sheet_to_json(worksheet);

                    if (jsonData.length === 0) {
                        Swal.fire({ icon: 'warning', title: 'Archivo vacío', text: 'El archivo Excel no contiene filas de insumos.' });
                        importMatFile.value = '';
                        return;
                    }

                    const parsedList = [];
                    for (const row of jsonData) {
                        const code = (row["Código"] || row["Codigo"] || row["code"] || row["Code"] || "").toString().trim();
                        const name = (row["Nombre del Insumo"] || row["Nombre"] || row["name"] || row["Name"] || "").toString().trim();
                        const category = (row["Categoría"] || row["Categoria"] || row["category"] || row["Category"] || "Materiales").toString().trim();
                        let area = (row["Área Clínica"] || row["Area Clinica"] || row["Área"] || row["Area"] || row["area"] || "").toString().trim();
                        if (!area && typeof detectClinicalArea === 'function') {
                            area = detectClinicalArea(category, name);
                        }
                        if (!area) area = 'Odontología';

                        const currentStock = parseInt(row["Stock Actual"] || row["Stock"] || row["currentStock"] || 0);
                        const minStock = parseInt(row["Stock Mínimo"] || row["Stock Minimo"] || row["minStock"] || 0);
                        const unit = (row["Unidad de Medida"] || row["Unidad"] || row["unit"] || "Unidades").toString().trim();
                        const rawExpiry = row["Fecha de Vencimiento (AAAA-MM-DD)"] || row["Fecha de Vencimiento"] || row["Vencimiento"] || row["expiryDate"] || null;
                        const expiryDate = SupabaseDataService._sanitizeDate ? SupabaseDataService._sanitizeDate(rawExpiry) : (rawExpiry === '—' || rawExpiry === '-' ? null : rawExpiry);

                        parsedList.push({
                            code,
                            name,
                            area,
                            category,
                            unit,
                            currentStock: isNaN(currentStock) ? 0 : currentStock,
                            minStock: isNaN(minStock) ? 0 : minStock,
                            expiryDate: expiryDate || ''
                        });
                    }

                    window.pendingImportMaterials = parsedList;
                    Swal.close();

                    const modal = document.getElementById('modal-import-materials-preview');
                    if (modal) {
                        modal.classList.remove('hidden');
                        window.renderImportMaterialsPreviewTable();
                    }
                } catch (err) {
                    console.error("Error al procesar Excel:", err);
                    Swal.fire({ icon: 'error', title: 'Error de Lectura', text: `No se pudo procesar el archivo Excel. Detalle: ${err.message || err}` });
                    importMatFile.value = '';
                }
            };
            reader.onerror = () => {
                Swal.fire({ icon: 'error', title: 'Error de Lectura', text: 'No se pudo leer el archivo físico.' });
                importMatFile.value = '';
            };
            reader.readAsArrayBuffer(file);
        };
    }

    // Day Target selector toggle custom date
    const dayTargetSelect = document.getElementById('app-day-target');
    const customDateGroup = document.getElementById('app-custom-date-group');
    if (dayTargetSelect && customDateGroup) {
        dayTargetSelect.onchange = () => {
            if (dayTargetSelect.value === 'custom') {
                customDateGroup.classList.remove('hidden');
                const customDateInput = document.getElementById('app-custom-date');
                if (customDateInput && !customDateInput.value) {
                    customDateInput.value = new Date().toISOString().split('T')[0];
                }
            } else {
                customDateGroup.classList.add('hidden');
            }
        };
    }

    // Dynamic Appointment Helpers: Doctors, Specialties, Shifts, Assistants, and Rooms
    window._availableDoctorsCache = [];

    window.populateAppointmentDropdowns = async function(appt = {}) {
        // 1. Especialidad
        const specSel = document.getElementById('app-specialty-select');
        let dynamicSpecs = [];
        if (window.ClinicalERP && window.ClinicalERP.specialties && window.ClinicalERP.specialties.length > 0) {
            dynamicSpecs = window.ClinicalERP.specialties;
        } else {
            try { dynamicSpecs = JSON.parse(localStorage.getItem('vidasana_specialties')) || []; } catch(e) {}
        }
        const allSpecs = Array.from(new Set([
            'Odontología', 'Medicina General', 'Laboratorio', 'Rayos X e Imagen',
            'Cardiología', 'Ginecología', 'Pediatría', 'Traumatología', 'Oftalmología',
            ...dynamicSpecs.map(s => s.name || s.nombre).filter(Boolean)
        ]));

        if (specSel) {
            specSel.innerHTML = allSpecs.map(s => `<option value="${s}">${s}</option>`).join('');
            if (appt.specialty) specSel.value = appt.specialty;
        }

        // 2. Load Doctors, Staff & Rooms
        const [users, staff, rooms] = await Promise.all([
            SupabaseDataService.getUsers(),
            SupabaseDataService.getPayrollStaff ? SupabaseDataService.getPayrollStaff().catch(() => []) : [],
            SupabaseDataService.getClinicRooms ? SupabaseDataService.getClinicRooms().catch(() => []) : []
        ]);

        const doctors = users.filter(u => {
            const r = (u.role || '').toLowerCase();
            const n = (u.fullname || '').toLowerCase();
            return r.includes('odont') || r.includes('médic') || r.includes('medic') || 
                   r.includes('doctor') || r.includes('especialista') || r.includes('admin') ||
                   n.startsWith('dr') || n.startsWith('dra');
        });

        (staff || []).forEach(st => {
            const r = (st.role || st.puesto || '').toLowerCase();
            const n = (st.name || st.fullname || '').toLowerCase();
            if (r.includes('médic') || r.includes('doctor') || r.includes('odont') || n.startsWith('dr') || n.startsWith('dra')) {
                if (!doctors.some(d => (d.fullname || '').toLowerCase() === n)) {
                    doctors.push({
                        id: st.id,
                        fullname: st.name || st.fullname,
                        role: st.role || st.puesto || 'Médico Especialista',
                        doctorProfile: { specialty: st.department || 'Medicina General' }
                    });
                }
            }
        });

        window._availableDoctorsCache = doctors;

        // 3. Assistants
        const asstSel = document.getElementById('app-assistant-select');
        if (asstSel) {
            const assistants = users.filter(u => {
                const r = (u.role || '').toLowerCase();
                return r.includes('asist') || r.includes('enferm') || r.includes('auxiliar') || r.includes('higien');
            });
            (staff || []).forEach(st => {
                const r = (st.role || st.puesto || '').toLowerCase();
                if (r.includes('asist') || r.includes('enferm') || r.includes('auxiliar') || r.includes('higien')) {
                    if (!assistants.some(a => (a.fullname || '').toLowerCase() === (st.name || '').toLowerCase())) {
                        assistants.push({ id: st.id, fullname: st.name || st.fullname, role: st.role || 'Asistente' });
                    }
                }
            });
            asstSel.innerHTML = '<option value="">-- Sin Asistente --</option>' +
                assistants.map(a => `<option value="${a.id}" data-name="${a.fullname}">${a.fullname} (${a.role || 'Asistente'})</option>`).join('');
            if (appt.assistantId) asstSel.value = appt.assistantId;
            else if (appt.assistantName) {
                for (let i = 0; i < asstSel.options.length; i++) {
                    if (asstSel.options[i].text.includes(appt.assistantName)) {
                        asstSel.selectedIndex = i;
                        break;
                    }
                }
            }
        }

        // 4. Rooms
        const roomSel = document.getElementById('app-room-select');
        if (roomSel) {
            roomSel.innerHTML = '<option value="">-- Sin Consultorio Asignado --</option>' +
                rooms.map(rm => `<option value="${rm.id}" data-name="${rm.name || rm.room_number}">${rm.name || rm.room_number}</option>`).join('');
            if (appt.roomId) roomSel.value = appt.roomId;
            else if (appt.roomName) {
                for (let i = 0; i < roomSel.options.length; i++) {
                    if (roomSel.options[i].text.includes(appt.roomName)) {
                        roomSel.selectedIndex = i;
                        break;
                    }
                }
            }
        }

        // 5. Populate doctors matching specialty
        window.updateAppointmentDoctorOptions(appt.specialty || (specSel ? specSel.value : 'Odontología'), appt.doctorId || appt.doctorName);

        // 6. Shift
        const shiftSel = document.getElementById('app-shift-select');
        if (shiftSel && appt.shift) {
            shiftSel.value = appt.shift;
        }
    };

    window.updateAppointmentDoctorOptions = function(selectedSpec, preselectVal) {
        const docSel = document.getElementById('app-doctor-select');
        if (!docSel) return;
        const docs = window._availableDoctorsCache || [];
        
        const specLower = (selectedSpec || '').toLowerCase();
        const sortedDocs = [...docs].sort((a, b) => {
            const aProf = a.doctorProfile || a.doctor_profile || {};
            const bProf = b.doctorProfile || b.doctor_profile || {};
            const aSpec = (aProf.specialty || a.role || '').toLowerCase();
            const bSpec = (bProf.specialty || b.role || '').toLowerCase();
            const aMatch = aSpec.includes(specLower) ? 1 : 0;
            const bMatch = bSpec.includes(specLower) ? 1 : 0;
            return bMatch - aMatch;
        });

        docSel.innerHTML = '<option value="">-- Seleccionar Médico Tratante --</option>' +
            sortedDocs.map(d => {
                const docProf = d.doctorProfile || d.doctor_profile || {};
                const spec = docProf.specialty || d.role || 'Especialista';
                const shift = docProf.shift === 'afternoon' ? 'Tarde' : (docProf.shift === 'both' ? 'Completo' : 'Mañana');
                return `<option value="${d.id}" data-name="${d.fullname}" data-specialty="${spec}" data-shift="${docProf.shift || ''}" data-assistant-id="${docProf.assistantId || ''}" data-assistant-name="${docProf.assistantName || ''}" data-room-id="${docProf.roomId || ''}" data-room-name="${docProf.roomName || ''}">${d.fullname} (${spec} • Turno ${shift})</option>`;
            }).join('');

        if (preselectVal) {
            let found = false;
            for (let i = 0; i < docSel.options.length; i++) {
                if (docSel.options[i].value === preselectVal || (docSel.options[i].dataset.name && docSel.options[i].dataset.name.includes(preselectVal))) {
                    docSel.selectedIndex = i;
                    found = true;
                    break;
                }
            }
            if (!found && docSel.options.length > 1) docSel.selectedIndex = 1;
        } else if (docSel.options.length > 1) {
            docSel.selectedIndex = 1;
        }
        window.onAppointmentDoctorChange(docSel.value);
    };

    window.onAppointmentSpecialtyChange = function(spec) {
        window.updateAppointmentDoctorOptions(spec, null);
    };

    window.onAppointmentDoctorChange = function(docId) {
        const docSel = document.getElementById('app-doctor-select');
        if (!docSel || docSel.selectedIndex <= 0) return;
        const opt = docSel.options[docSel.selectedIndex];
        
        // Auto-set shift
        const shiftSel = document.getElementById('app-shift-select');
        if (shiftSel && opt.dataset.shift) {
            shiftSel.value = opt.dataset.shift === 'afternoon' ? 'afternoon' : 'morning';
        }

        // Auto-set assistant
        const asstSel = document.getElementById('app-assistant-select');
        if (asstSel && (opt.dataset.assistantId || opt.dataset.assistantName)) {
            if (opt.dataset.assistantId) asstSel.value = opt.dataset.assistantId;
            else {
                for (let i = 0; i < asstSel.options.length; i++) {
                    if (asstSel.options[i].text.includes(opt.dataset.assistantName)) {
                        asstSel.selectedIndex = i;
                        break;
                    }
                }
            }
        }

        // Auto-set room
        const roomSel = document.getElementById('app-room-select');
        if (roomSel && (opt.dataset.roomId || opt.dataset.roomName)) {
            if (opt.dataset.roomId) roomSel.value = opt.dataset.roomId;
            else {
                for (let i = 0; i < roomSel.options.length; i++) {
                    if (roomSel.options[i].text.includes(opt.dataset.roomName)) {
                        roomSel.selectedIndex = i;
                        break;
                    }
                }
            }
        }
    };

    // Modal Cita Helpers: New & Edit
    window.openNewAppointmentModal = async function() {
        try {
            await populateAppointmentPatientSelect();
            await window.populateAppointmentDropdowns({});
        } catch(err) {
            console.error("Error populating appointment patients/dropdowns:", err);
        }

        const titleEl = document.getElementById('modal-appointment-title');
        if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-calendar-plus text-cyan"></i> Agendar Nueva Cita Médica';

        const saveBtn = document.getElementById('btn-save-appointment');
        if (saveBtn) saveBtn.textContent = 'Guardar Cita';

        const appIdInput = document.getElementById('app-id');
        if (appIdInput) appIdInput.value = '';

        const timeInput = document.getElementById('app-time');
        if (timeInput) timeInput.value = '';

        const treatmentInput = document.getElementById('app-treatment');
        if (treatmentInput) treatmentInput.value = '';

        const statusSelect = document.getElementById('app-status');
        if (statusSelect) statusSelect.value = 'Programada';

        const daySel = document.getElementById('app-day-target');
        const customGrp = document.getElementById('app-custom-date-group');
        const customDateInput = document.getElementById('app-custom-date');
        if (daySel) daySel.value = 'today';
        if (customGrp) customGrp.classList.add('hidden');
        if (customDateInput) {
            customDateInput.value = new Date().toISOString().split('T')[0];
        }

        openModal('modal-appointment');
    };

    window.editAppointment = async function(apptId) {
        try {
            const appts = await SupabaseDataService.getAppointments();
            const app = appts.find(a => a.id === apptId);
            if (!app) {
                Swal.fire({ icon: 'error', title: 'Error', text: 'No se encontró la información de la cita seleccionada.' });
                return;
            }

            await populateAppointmentPatientSelect();
            await window.populateAppointmentDropdowns(app);

            const titleEl = document.getElementById('modal-appointment-title');
            if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-pen-to-square text-cyan"></i> Editar Cita Médica';

            const saveBtn = document.getElementById('btn-save-appointment');
            if (saveBtn) saveBtn.textContent = 'Actualizar Cita';

            const appIdInput = document.getElementById('app-id');
            if (appIdInput) appIdInput.value = app.id;

            const pSelect = document.getElementById('app-patient-select');
            if (pSelect) pSelect.value = app.patientId;

            const timeInput = document.getElementById('app-time');
            if (timeInput) timeInput.value = app.time || '';

            const treatmentInput = document.getElementById('app-treatment');
            if (treatmentInput) treatmentInput.value = app.treatment || '';

            const statusSelect = document.getElementById('app-status');
            if (statusSelect) statusSelect.value = app.status || 'Programada';

            const daySel = document.getElementById('app-day-target');
            const customGrp = document.getElementById('app-custom-date-group');
            const customDateInput = document.getElementById('app-custom-date');

            if (daySel) {
                if (app.date === 'today' || app.date === 'today-appt' || app.isTomorrow === false) {
                    daySel.value = 'today';
                    if (customGrp) customGrp.classList.add('hidden');
                } else if (app.date === 'tomorrow' || app.isTomorrow === true) {
                    daySel.value = 'tomorrow';
                    if (customGrp) customGrp.classList.add('hidden');
                } else if (app.date && app.date.includes('-')) {
                    daySel.value = 'custom';
                    if (customGrp) customGrp.classList.remove('hidden');
                    if (customDateInput) customDateInput.value = app.date;
                } else {
                    daySel.value = 'today';
                    if (customGrp) customGrp.classList.add('hidden');
                }
            }

            openModal('modal-appointment');
        } catch(e) {
            console.error("Error editing appointment:", e);
            Swal.fire({ icon: 'error', title: 'Error', text: 'No se pudo abrir el editor de la cita.' });
        }
    };

    // Modal Cita Trigger Listener
