    const saveUserBtn = document.getElementById('btn-save-user');
    if (saveUserBtn) {
        saveUserBtn.onclick = async (e) => {
            e.preventDefault();
            const existingUserId = document.getElementById('u-user-id')?.value;
            const fullname = document.getElementById('u-fullname').value.trim();
            const email = document.getElementById('u-email').value.trim();
            const password = document.getElementById('u-password').value.trim();
            const role = document.getElementById('u-role').value;
            const rawLicense = document.getElementById('u-license').value.trim();

            if (!fullname || !email) {
                Swal.fire({ icon: 'warning', title: 'Campos requeridos', text: 'Por favor ingrese el Nombre Completo y el Correo Electrónico.' });
                return;
            }

            if (!existingUserId && !password) {
                Swal.fire({ icon: 'warning', title: 'Contraseña requerida', text: 'Por favor ingrese una contraseña para el nuevo usuario.' });
                return;
            }

            const r = (role || '').toLowerCase();
            const isDoctor = r.includes('odont') || r.includes('especialista') || r.includes('cirujano') || r.includes('médico') || r.includes('medico') || r.includes('doctor');
            const license = isDoctor ? (rawLicense || 'N/A') : 'N/A';
            let doctorProfile = null;

            if (isDoctor) {
                const assignedServices = Array.from(document.getElementById('u-services').selectedOptions).map(opt => opt.value);
                const schedule = document.getElementById('u-schedule').value.trim();
                const commission = parseFloat(document.getElementById('u-commission').value) || 0;
                const availability = document.getElementById('u-availability').value.trim();

                const specialty = document.getElementById('u-specialty')?.value || '';
                const shift = document.getElementById('u-shift')?.value || 'both';
                const asstSel = document.getElementById('u-assistant');
                const assistantId = asstSel?.value || '';
                const assistantName = asstSel && asstSel.selectedIndex >= 0 && asstSel.value ? asstSel.options[asstSel.selectedIndex].text : '';
                const roomSel = document.getElementById('u-room');
                const roomId = roomSel?.value || '';
                const roomName = roomSel && roomSel.selectedIndex >= 0 && roomSel.value ? roomSel.options[roomSel.selectedIndex].text : '';

                // Collect additional specialties from active chips
                const additionalChips = document.querySelectorAll('#u-additional-specialties-container .spec-chip.active');
                const additionalSpecialties = Array.from(additionalChips).map(c => c.dataset.specialty).filter(Boolean);
                const allSpecialties = Array.from(new Set([specialty, ...additionalSpecialties].filter(Boolean)));

                doctorProfile = {
                    specialty,
                    additionalSpecialties,
                    specialties: allSpecialties,
                    shift,
                    assistantId,
                    assistantName,
                    roomId,
                    roomName,
                    assignedServices,
                    schedule,
                    commission,
                    availability
                };
            }

            let userObj = null;
            if (existingUserId) {
                const users = await SupabaseDataService.getUsers();
                const existing = users.find(u => String(u.id) === String(existingUserId));
                userObj = {
                    ...(existing || {}),
                    id: existingUserId,
                    fullname,
                    email,
                    password: password || (existing ? existing.password : '123456'),
                    role,
                    license,
                    status: existing ? (existing.status || 'Activo') : 'Activo',
                    createdAt: existing ? existing.createdAt : new Date().toISOString().split('T')[0],
                    doctorProfile: doctorProfile || (existing ? existing.doctorProfile : {}),
                    doctor_profile: doctorProfile || (existing ? existing.doctor_profile : {})
                };
            } else {
                userObj = {
                    id: 'usr-' + Date.now(),
                    fullname,
                    email,
                    password,
                    role,
                    license,
                    status: 'Activo',
                    createdAt: new Date().toISOString().split('T')[0],
                    doctorProfile: doctorProfile || {},
                    doctor_profile: doctorProfile || {}
                };
            }

            try {
                await SupabaseDataService.saveUser(userObj);

                // Sincronizar consultorio si se asignó uno al especialista
                if (doctorProfile && doctorProfile.roomId && SupabaseDataService.getClinicRooms && SupabaseDataService.saveClinicRoom) {
                    try {
                        const rooms = await SupabaseDataService.getClinicRooms();
                        const room = rooms.find(r => String(r.id) === String(doctorProfile.roomId));
                        if (room) {
                            if (!room.shifts) room.shifts = { morning: {}, afternoon: {} };
                            const docData = { doctorId: userObj.id, doctorName: fullname, specialty: doctorProfile.specialty };
                            if (doctorProfile.shift === 'morning' || doctorProfile.shift === 'both') {
                                room.shifts.morning = { ...room.shifts.morning, ...docData };
                            }
                            if (doctorProfile.shift === 'afternoon' || doctorProfile.shift === 'both') {
                                room.shifts.afternoon = { ...room.shifts.afternoon, ...docData };
                            }
                            await SupabaseDataService.saveClinicRoom(room);
                        }
                    } catch (errRoom) {
                        console.warn('Error sincronizando consultorio con el médico:', errRoom);
                    }
                }

                // Notificar a los selectores reactivos
                if (window.ClinicalERP && window.ClinicalERP.populateRoomDoctorSelects) {
                    window.ClinicalERP.populateRoomDoctorSelects();
                }
                if (window.populateAppointmentDropdowns) {
                    window.populateAppointmentDropdowns();
                }

                closeModal('modal-user');
                await renderUsersTable();
                Swal.fire({
                    icon: 'success',
                    title: existingUserId ? '¡Usuario Actualizado!' : '¡Usuario Registrado!',
                    text: `La cuenta de ${fullname} se guardó exitosamente en la base de datos.`,
                    timer: 2000,
                    showConfirmButton: false
                });
            } catch (err) {
                console.error('Error guardando usuario:', err);
                Swal.fire({
                    icon: 'error',
                    title: 'Error al guardar',
                    text: 'Ocurrió un inconveniente al guardar el usuario en la base de datos: ' + (err.message || err)
                });
            }
        };
    }

    // Guardar Usuario del Sistema (Ajustes -> Usuarios y Roles del Sistema)
    const saveSysUserBtn = document.getElementById('btn-save-system-user');
