    const handleSaveSystemUser = async (e) => {
        if (e) e.preventDefault();
        const existingId = document.getElementById('sys-user-id')?.value;
        const fullname = document.getElementById('sys-user-fullname').value.trim();
        const email = document.getElementById('sys-user-email').value.trim();
        const password = document.getElementById('sys-user-password').value.trim();
        const role = document.getElementById('sys-user-role').value;
        const status = document.getElementById('sys-user-status').value || 'Activo';

        if (!fullname || !email) {
            Swal.fire({ icon: 'warning', title: 'Campos requeridos', text: 'Por favor ingrese el Nombre Completo y el Correo Electrónico.' });
            return;
        }

        if (!existingId && !password) {
            Swal.fire({ icon: 'warning', title: 'Contraseña requerida', text: 'Por favor asigne una contraseña de acceso inicial.' });
            return;
        }

        if (password && password.length < 4) {
            Swal.fire({ icon: 'warning', title: 'Contraseña muy corta', text: 'La contraseña debe tener al menos 4 caracteres.' });
            return;
        }

        let userObj = null;
        if (existingId) {
            const users = await SupabaseDataService.getUsers();
            const existing = users.find(u => String(u.id) === String(existingId));
            userObj = {
                ...(existing || {}),
                id: existingId,
                fullname,
                email,
                password: password || (existing ? existing.password : '123456'),
                role,
                status,
                createdAt: existing ? existing.createdAt : new Date().toISOString().split('T')[0]
            };
        } else {
            userObj = {
                id: 'sys-' + Date.now(),
                fullname,
                email,
                password,
                role,
                status,
                createdAt: new Date().toISOString().split('T')[0]
            };
        }

        try {
            await SupabaseDataService.saveUser(userObj);
            if (window.logUserAction) {
                await window.logUserAction(
                    existingId ? 'Actualizó Usuario del Sistema' : 'Creó Usuario del Sistema',
                    'Ajustes',
                    `Cuenta: ${fullname} (${role}) - Estado: ${status}`
                );
            }
            closeModal('modal-system-user');
            await window.renderSystemUsersTable();
            Swal.fire({
                icon: 'success',
                title: existingId ? '¡Cuenta Actualizada!' : '¡Cuenta Creada!',
                text: `El usuario administrativo de ${fullname} fue guardado correctamente.`,
                timer: 2000,
                showConfirmButton: false
            });
        } catch (err) {
            console.error('Error guardando usuario del sistema:', err);
            Swal.fire({
                icon: 'error',
                title: 'Error al guardar',
                text: 'Ocurrió un inconveniente al guardar el usuario administrativo: ' + (err.message || err)
            });
        }
    };

    if (saveSysUserBtn) saveSysUserBtn.onclick = handleSaveSystemUser;
    if (formSysUser) formSysUser.onsubmit = handleSaveSystemUser;

    window.openBudgetForNewPatient = async function(patientId) {
        setActivePatientId(patientId);

        // Forzar cambio al editor
        localStorage.setItem('dental_odontogram_subview', 'editor');
        document.documentElement.setAttribute('data-odontogram-subview', 'editor');
        const listContainer = document.getElementById('odontogram-list-container');
        const editorContainer = document.getElementById('odontogram-editor-container');
        if (listContainer) listContainer.classList.add('hidden');
        if (editorContainer) editorContainer.classList.remove('hidden');

        const navOdontogram = document.querySelector('.nav-item[data-tab="odontogram"]') || document.getElementById('mob-nav-odontogram');
        if (navOdontogram) navOdontogram.click();

        const patients = await SupabaseDataService.getPatients();
        const patient = patients.find(p => String(p.id) === String(patientId));

        // Si ya hay ítems de presupuesto en memoria (por ejemplo, recién seleccionados en el odontograma), NO los borramos.
        // Si no hay en memoria, intentamos recuperarlos del borrador guardado en metadata.draftBudget.items del paciente.
        if (!currentBudgetItems || currentBudgetItems.length === 0) {
            if (patient && patient.metadata && patient.metadata.draftBudget && Array.isArray(patient.metadata.draftBudget.items) && patient.metadata.draftBudget.items.length > 0) {
                currentBudgetItems = [...patient.metadata.draftBudget.items];
            }
        }

        // De igual forma con el odontograma: si ya tiene marcas en memoria, preservarlas. Si no, cargar del paciente.
        if (window.odontogram) {
            const currentOdData = window.odontogram.getData();
            const hasCurrentOdData = currentOdData && Object.keys(currentOdData).length > 0;
            if (!hasCurrentOdData && patient && patient.odontogramData && Object.keys(patient.odontogramData).length > 0) {
                window.odontogram.setData(patient.odontogramData);
            }
        }

        if (window.doctorSigPad) {
            await autoLoadDoctorSignatureInBudget(patient ? patient.assignedDoctor : null);
        }

        await renderOdontogramView();

        const searchInput = document.getElementById('od-patient-search-input');
        if (searchInput) searchInput.value = patient ? (patient.fullname || '') : '';

        renderBudgetTable();
    };

    window.savePatientRecord = async function(redirectToBudget = false) {
        const getVal = (id) => {
            const el = document.getElementById(id);
            return el ? el.value.trim() : '';
        };
        const getChecked = (id) => {
            const el = document.getElementById(id);
            return el ? (el.checked ? 'Sí' : 'No') : 'No';
        };

        const id = getVal('p-id');
        const firstname = getVal('p-firstname');
        const lastname = getVal('p-lastname');
        const fullname = `${firstname} ${lastname}`.trim();
        const birthdate = getVal('p-birthdate');
        const phone = getVal('p-mobile-phone');
        const address = getVal('p-address');
        const type = getVal('p-type') || 'Adulto';
        const age = parseInt(getVal('p-age')) || 0;

        if (!id || !firstname || !lastname || !birthdate || !phone || !address) {
            Swal.fire({ 
                icon: 'warning', 
                title: 'Campos Requeridos Incompletos', 
                text: 'Por favor complete todos los campos obligatorios del Paso 1 (Cédula, Nombres, Apellidos, Fecha de Nacimiento, WhatsApp y Dirección) para continuar.' 
            });
            if (typeof window.setPatientStepperStep === 'function') window.setPatientStepperStep(1);
            return false;
        }

        if (type === 'Infantil' || (age > 0 && age < 18)) {
            const repName = getVal('p-rep-name');
            const repId = getVal('p-rep-id');
            const repPhone = getVal('p-rep-phone');
            const repRelation = getVal('p-rep-relation');

            if (!repName || !repId || !repPhone || !repRelation) {
                Swal.fire({ 
                    icon: 'warning', 
                    title: 'Representante Obligatorio', 
                    text: 'El paciente es menor de edad. Por favor complete los datos del representante legal en el Paso 1 (Nombre, Cédula, Teléfono y Parentesco).' 
                });
                if (typeof window.setPatientStepperStep === 'function') window.setPatientStepperStep(1);
                return false;
            }
        }

        const allergies = Array.from(document.querySelectorAll('input[name="p-allergies"]:checked')).map(cb => cb.value);
        const systemic = Array.from(document.querySelectorAll('input[name="p-systemic"]:checked')).map(cb => cb.value);
        const medication = getVal('p-medication');
        const emergencyContact = getVal('p-emergency');

        // Extract all detailed metadata fields
        const gender = getVal('p-gender') || 'Femenino';
        const mobilePhone = getVal('p-mobile-phone');
        const localPhone = getVal('p-local-phone');
        const workPhone = getVal('p-work-phone');
        const profession = getVal('p-profession');
        const consultReason = getVal('p-consult-reason');

        const repName = getVal('p-rep-name');
        const repId = getVal('p-rep-id');
        const repPhone = getVal('p-rep-phone');
        const repRelation = getVal('p-rep-relation');

        const medicalTreatment = getChecked('p-medical-treatment');
        const medicalTreatmentDetails = getVal('p-medical-treatment-details');
        const childDiseases = getVal('p-child-diseases');
        const hasAllergies = getChecked('p-has-allergies');
        const allergiesDetails = getVal('p-allergies-details');
        const surgeries = getVal('p-surgeries');
        const bleedingIssue = getChecked('p-bleeding-issue');
        const respiratoryIssues = getChecked('p-respiratory-issues');
        const respiratoryIssuesDetails = getVal('p-respiratory-issues-details');
        const anesthesiaReaction = getChecked('p-anesthesia-reaction');
        const anesthesiaReactionDetails = getVal('p-anesthesia-reaction-details');
        const penicillinAllergy = getChecked('p-penicillin-allergy');
        const penicillinAllergyDetails = getVal('p-penicillin-allergy-details');
        const heartIssues = getChecked('p-heart-issues');
        const heartIssuesDetails = getVal('p-heart-issues-details');

        const tissueHardPalate = getVal('p-tissue-hard-palate');
        const tissueSoftPalate = getVal('p-tissue-soft-palate');
        const tissueMouthFloor = getVal('p-tissue-mouth-floor');
        const tissueCheeks = getVal('p-tissue-cheeks');
        const tissueTongue = getVal('p-tissue-tongue');
        const tissueFrenum = getVal('p-tissue-frenum');

        const habitSwallowing = getChecked('p-habit-swallowing');
        const habitNailbiting = getChecked('p-habit-nailbiting');
        const habitThumbsucking = getChecked('p-habit-thumbsucking');
        const habitThumbsuckingFinger = getVal('p-habit-thumbsucking-finger');
        const habitOthers = getVal('p-habit-others');
        const habitMouthbreather = getChecked('p-habit-mouthbreather');
        const habitFrequency = getVal('p-habit-frequency');
        const habitIntensity = getVal('p-habit-intensity');
        // Collect sessions data from step 4
        const sessionsData = [];
        const planSessionsContainer = document.getElementById('plan-sessions-container');
        const bItems = window.currentPlannerBudgetItems || (currentBudgetItems && currentBudgetItems.length > 0 ? currentBudgetItems : (window.currentBudgetItems || []));
        const step4WasRendered = planSessionsContainer && planSessionsContainer.querySelectorAll('.session-date-input').length > 0;

        if (step4WasRendered && bItems.length > 0) {
            const sessionBlocks = planSessionsContainer.querySelectorAll('.session-date-input');
            sessionBlocks.forEach(input => {
                const sessionNum = parseInt(input.dataset.session);
                const dateVal = input.value;
                const timeSelect = planSessionsContainer.querySelector(`.session-time-select[data-session="${sessionNum}"]`);
                const timeVal = timeSelect ? timeSelect.value : '09:00 AM';
                const checkedBoxes = planSessionsContainer.querySelectorAll(`.session-service-checkbox[data-session="${sessionNum}"]:checked`);
                const services = Array.from(checkedBoxes).map(cb => {
                    const idx = parseInt(cb.dataset.itemIdx);
                    return bItems[idx];
                }).filter(Boolean);
                sessionsData.push({
                    sessionNumber: sessionNum,
                    date: dateVal,
                    time: timeVal,
                    services: services
                });
            });
        }

        let patientToSave = {};

        try {
            const selectedTagId = getVal('p-tag') || '';
            let tagObj = null;
            if (selectedTagId) {
                const allTags = await SupabaseDataService.getPatientTags();
                tagObj = allTags.find(t => t.id === selectedTagId) || null;
            }
            const tagId = tagObj ? tagObj.id : '';
            const tagName = tagObj ? tagObj.name : '';
            const tagColor = tagObj ? tagObj.color : '';
            const tagRule = tagObj ? { type: tagObj.ruleType, value: tagObj.ruleValue, label: tagObj.name } : null;

            const patients = await SupabaseDataService.getPatients();
            const existing = patients.find(p => p.id === id || (window.editingPatientId && p.id === window.editingPatientId));

            if (existing) {
                // MODO EDICIÓN: Actualizar todos los datos clínicos y personales preservando historial
                patientToSave = {
                    ...existing,
                    id: existing.id,
                    fullname,
                    birthdate,
                    phone,
                    email: getVal('p-email'),
                    occupation: profession,
                    address: address,
                    allergies,
                    systemic,
                    medication,
                    emergencyContact,
                    tagId,
                    tagName,
                    tagColor,
                    tagRule,
                    updatedAt: new Date().toISOString(),
                    odontogramData: (existing && existing.odontogramData) ? existing.odontogramData : {},
                    metadata: {
                        ...(existing.metadata || {}),
                        tagId,
                        tagName,
                        tagColor,
                        tagRule,
                        updatedAt: new Date().toISOString(),
                        type,
                        age,
                        gender,
                        address,
                        mobilePhone,
                        localPhone,
                        workPhone,
                        profession,
                        consultReason,
                        repName,
                        repId,
                        repPhone,
                        repRelation,
                        medicalTreatment,
                        medicalTreatmentDetails,
                        childDiseases,
                        hasAllergies,
                        allergiesDetails,
                        surgeries,
                        bleedingIssue,
                        respiratoryIssues,
                        respiratoryIssuesDetails,
                        anesthesiaReaction,
                        anesthesiaReactionDetails,
                        penicillinAllergy,
                        penicillinAllergyDetails,
                        heartIssues,
                        heartIssuesDetails,
                        tissueHardPalate,
                        tissueSoftPalate,
                        tissueMouthFloor,
                        tissueCheeks,
                        tissueTongue,
                        tissueFrenum,
                        habitSwallowing,
                        habitNailbiting,
                        habitThumbsucking,
                        habitThumbsuckingFinger,
                        habitOthers,
                        habitMouthbreather,
                        habitFrequency,
                        habitIntensity,
                        initTreatmentName: getVal('p-init-treatment-name'),
                        initTreatmentSessions: getVal('p-init-treatment-sessions'),
                        initTreatmentInterval: getVal('p-init-treatment-interval'),
                        initialTreatmentPlan: {
                            treatmentName: getVal('p-init-treatment-name') || 'Tratamiento Integral',
                            totalSessions: parseInt(getVal('p-init-treatment-sessions')) || 2,
                            interval: getVal('p-init-treatment-interval') || 'Quincenal'
                        },
                        sessionsPlan: step4WasRendered ? sessionsData : ((existing.metadata && existing.metadata.sessionsPlan) || []),
                        draftOdontogramData: (window.odontogram && Object.keys(window.odontogram.getData() || {}).length > 0) ? window.odontogram.getData() : ((existing.metadata && existing.metadata.draftOdontogramData) || {}),
                        draftBudget: {
                            items: (currentBudgetItems && currentBudgetItems.length > 0) ? currentBudgetItems : ((existing.metadata && existing.metadata.draftBudget && existing.metadata.draftBudget.items) || [])
                        }
                    }
                };
            } else {
                // MODO NUEVO PACIENTE: Guardar ficha integral con todos los datos de pasos 1, 2, 3 y 4
                patientToSave = {
                    id,
                    fullname,
                    birthdate,
                    phone,
                    email: getVal('p-email'),
                    occupation: profession,
                    allergies,
                    systemic,
                    medication,
                    emergencyContact,
                    tagId,
                    tagName,
                    tagColor,
                    tagRule,
                    status: 'Activo',
                    createdAt: new Date().toISOString(),
                    updatedAt: new Date().toISOString(),
                    odontogramData: {},
                    clinicalNotes: [],
                    photos: [],
                    payments: [],
                    metadata: {
                        tagId,
                        tagName,
                        tagColor,
                        tagRule,
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString(),
                        type,
                        age,
                        gender,
                        address,
                        mobilePhone,
                        localPhone,
                        workPhone,
                        profession,
                        consultReason,
                        repName,
                        repId,
                        repPhone,
                        repRelation,
                        medicalTreatment,
                        medicalTreatmentDetails,
                        childDiseases,
                        hasAllergies,
                        allergiesDetails,
                        surgeries,
                        bleedingIssue,
                        respiratoryIssues,
                        respiratoryIssuesDetails,
                        anesthesiaReaction,
                        anesthesiaReactionDetails,
                        penicillinAllergy,
                        penicillinAllergyDetails,
                        heartIssues,
                        heartIssuesDetails,
                        tissueHardPalate,
                        tissueSoftPalate,
                        tissueMouthFloor,
                        tissueCheeks,
                        tissueTongue,
                        tissueFrenum,
                        habitSwallowing,
                        habitNailbiting,
                        habitThumbsucking,
                        habitThumbsuckingFinger,
                        habitOthers,
                        habitMouthbreather,
                        habitFrequency,
                        habitIntensity,
                        initTreatmentName: getVal('p-init-treatment-name'),
                        initTreatmentSessions: getVal('p-init-treatment-sessions'),
                        initTreatmentInterval: getVal('p-init-treatment-interval'),
                        initialTreatmentPlan: {
                            treatmentName: getVal('p-init-treatment-name') || 'Tratamiento Integral',
                            totalSessions: parseInt(getVal('p-init-treatment-sessions')) || 2,
                            interval: getVal('p-init-treatment-interval') || 'Quincenal'
                        },
                        sessionsPlan: sessionsData,
                        draftOdontogramData: (window.odontogram && Object.keys(window.odontogram.getData() || {}).length > 0) ? window.odontogram.getData() : {},
                        draftBudget: {
                            items: (currentBudgetItems && currentBudgetItems.length > 0) ? currentBudgetItems : []
                        }
                    }
                };
            }

            await SupabaseDataService.savePatient(patientToSave);
            window.editingPatientId = null;
            
            // Create or update automatically scheduled appointments ONLY if the budget is approved
            if (sessionsData && sessionsData.length > 0) {
                const invoices = await SupabaseDataService.getInvoices();
                const isBudgetApproved = invoices.some(inv => String(inv.patientId) === String(id) && (String(inv.status).toLowerCase() === 'aprobado' || String(inv.status).toLowerCase() === 'approved'));
                
                if (isBudgetApproved) {
                    let appointmentsScheduledCount = 0;
                    const existingAppts = await SupabaseDataService.getAppointments();
                    for (const session of sessionsData) {
                        if (session.date) {
                            const servicesText = session.services && session.services.length > 0
                                ? session.services.map(s => `Pza ${s.tooth || 'Gnl'}: ${s.name}`).join(', ')
                                : 'Tratamiento Planificado';
                            
                            const treatmentTitle = `Sesión ${session.sessionNumber}: ${servicesText}`;
                            const safeId = (id || '').replace(/[^a-zA-Z0-9]/g, '_');
                            const apptId = `appt-${safeId}-session-${session.sessionNumber}`;
                            
                            const existingAppt = existingAppts.find(a => a.id === apptId || (a.patientId === id && a.treatment && a.treatment.startsWith(`Sesión ${session.sessionNumber}:`)));
                            
                            const appt = {
                                id: existingAppt ? existingAppt.id : apptId,
                                patientId: id,
                                patientName: fullname,
                                date: session.date,
                                time: session.time || "09:00 AM",
                                treatment: treatmentTitle,
                                status: "Programada",
                                isTomorrow: false
                            };
                            await SupabaseDataService.saveAppointment(appt);
                            appointmentsScheduledCount++;
                        }
                    }
                    if (appointmentsScheduledCount > 0) {
                        await renderAgendaView(); // Reload agenda immediately
                    }
                }
            }

            await closeModal('modal-patient', true);
            setActivePatientId(id);

            // Reset search and filters in Pacientes table so the new patient is immediately visible
            const searchInp = document.getElementById('patient-table-search');
            if (searchInp) searchInp.value = '';
            document.querySelectorAll('#view-patients .filter-btn').forEach(b => {
                if (b.dataset.filter === 'all' || b.dataset.filter === (patientToSave.status || 'Activo')) b.classList.add('active');
                else b.classList.remove('active');
            });
            const tagFilterEl = document.getElementById('patient-tag-filter');
            if (tagFilterEl) tagFilterEl.value = 'all';

            await renderPatientsTable('all', '', id);
            await renderEHRView();
            await renderDashboard();
            await renderAgendaView();

            if (window.returnToDirectSaleAfterPatientCreated) {
                window.returnToDirectSaleAfterPatientCreated = false;
                await window.openDirectSaleModal(id);
                Swal.fire({
                    icon: 'success',
                    title: '¡Paciente Guardado!',
                    text: `${fullname} ha sido registrado y seleccionado en la Venta Directa.`,
                    timer: 2000,
                    showConfirmButton: false
                });
                return true;
            }

            if (redirectToBudget) {
                await window.openBudgetForNewPatient(id);
                Swal.fire({
                    icon: 'success',
                    title: '¡Paciente Guardado!',
                    text: `Ficha de ${fullname} creada. Redirigiendo a elaboración de presupuesto...`,
                    timer: 2000,
                    showConfirmButton: false
                });
            } else {
                Swal.fire({
                    icon: 'success',
                    title: '¡Paciente Guardado!',
                    text: `${fullname} ha sido guardado exitosamente en la base de datos.`,
                    timer: 2000,
                    showConfirmButton: false
                });
            }
            return true;
        } catch (err) {
            console.error("Error al guardar paciente:", err);
            Swal.fire({
                icon: 'error',
                title: 'Error de Servidor / Base de Datos',
                text: `No se pudo guardar el paciente. Detalle: ${err.message || err}`
            });
            return false;
        }
    };

    const savePatientBtn = document.getElementById('btn-save-patient');
    if (savePatientBtn) {
        savePatientBtn.onclick = async (e) => {
            e.preventDefault();
            await window.savePatientRecord(false);
        };
    }

    const savePatientBudgetBtn = document.getElementById('btn-patient-save-and-budget');
    if (savePatientBudgetBtn) {
        savePatientBudgetBtn.onclick = async (e) => {
            e.preventDefault();
            await window.savePatientRecord(true);
        };
    }

    const step3BudgetBtn = document.getElementById('btn-patient-step3-budget');
    if (step3BudgetBtn) {
        step3BudgetBtn.onclick = async (e) => {
            e.preventDefault();
            await window.savePatientRecord(true);
        };
    }

    const clearActiveBtn = document.getElementById('btn-clear-active-patient');
    if (clearActiveBtn) {
        clearActiveBtn.onclick = () => {
            setActivePatientId(null);
        };
    }

    const clearDocSigBtn = document.getElementById('btn-clear-doc-sig');
    if (clearDocSigBtn) {
        clearDocSigBtn.onclick = async (e) => {
            e.stopPropagation();
            if (window.doctorSigPad) window.doctorSigPad.clear();
            window.refreshSignatureBoxBadges();
            await autoSaveActivePatientOdontogram();
        };
    }

    const clearPatSigBtn = document.getElementById('btn-clear-patient-sig');
    if (clearPatSigBtn) {
        clearPatSigBtn.onclick = async (e) => {
            e.stopPropagation();
            if (window.patientSigPad) window.patientSigPad.clear();
            const activeId = getActivePatientId();
            if (activeId) {
                try {
                    const patients = await SupabaseDataService.getPatients();
                    const patient = patients.find(p => String(p.id) === String(activeId));
                    if (patient && patient.metadata) {
                        patient.metadata.patientSignature = '';
                        await SupabaseDataService.savePatient(patient);
                    }
                } catch(err) {
                    console.error("Error clearing patient signature metadata:", err);
                }
            }
            window.refreshSignatureBoxBadges();
            await autoSaveActivePatientOdontogram();
        };
    }

    // Setup payment selector buttons click handler
    document.querySelectorAll('.pay-method-btn').forEach(btn => {
        btn.onclick = function() {
            document.querySelectorAll('.pay-method-btn').forEach(b => {
                b.classList.remove('active');
                b.style.background = 'transparent';
                b.style.color = 'var(--text-main)';
                b.style.borderColor = 'var(--border-color)';
            });
            this.classList.add('active');
            this.style.background = '#0d9488';
            this.style.color = '#fff';
            this.style.borderColor = '#0d9488';
            
            const method = this.getAttribute('data-method');
            const select = document.getElementById('budget-payment-method');
            if (select) {
                select.value = method;
                select.dispatchEvent(new Event('change'));
            }
        };
    });

    const approveBudgetBtn = document.getElementById('btn-approve-budget');
    if (approveBudgetBtn) {
        approveBudgetBtn.onclick = async () => {
            if (window.isSavingBudget) return;
            window.isSavingBudget = true;
            approveBudgetBtn.disabled = true;
            const origHtml = approveBudgetBtn.innerHTML;
            approveBudgetBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Guardando...';

            try {
                // Deduplicate current budget items FIRST
                currentBudgetItems = deduplicateBudgetItems(currentBudgetItems);

                const activeId = getActivePatientId();
                if (!activeId) {
                    Swal.fire({ icon: 'info', title: 'Seleccione un paciente', text: 'Por favor active un paciente antes de aprobar el presupuesto.' });
                    return;
                }
                const patients = await SupabaseDataService.getPatients();
                const patient = patients.find(p => p.id === activeId);
                if (!patient) return;

                if (currentBudgetItems.length === 0) {
                    Swal.fire({ icon: 'warning', title: 'Presupuesto vacío', text: 'Agregue al menos un tratamiento al presupuesto.' });
                    return;
                }

                // Deduct materials from Kardex
                currentBudgetItems.forEach(item => {
                    if (item.serviceCode) {
                        window.kardex.deductForTreatment(item.serviceCode);
                    }
                });

                // Calculate totals
                const rate = getExchangeRate();
                let subtotalUSD = 0;
                currentBudgetItems.forEach(item => {
                    subtotalUSD += item.price;
                });
                const discountPct = parseFloat(document.getElementById('budget-discount-input').value) || 0;
                const discountAmountUSD = subtotalUSD * (discountPct / 100);
                const totalUSD = subtotalUSD - discountAmountUSD;
                const totalVES = (totalUSD * rate).toFixed(2);
                const discountVES = (discountAmountUSD * rate).toFixed(2);

                const paymentModeSelect = document.getElementById('payment-mode-select');
                const paymentModeText = paymentModeSelect ? paymentModeSelect.options[paymentModeSelect.selectedIndex].text : 'Contado';
                const paymentMethodSelect = document.getElementById('budget-payment-method');
                const rawPaymentMethod = paymentMethodSelect ? paymentMethodSelect.value : '';
                
                if (!rawPaymentMethod) {
                    Swal.fire({
                        icon: 'warning',
                        title: 'Método de Pago Requerido',
                        text: 'No se puede aprobar el presupuesto porque aún falta seleccionar o añadir el método de pago.'
                    });
                    return;
                }

                let paymentMethod = rawPaymentMethod;
                let paymentMethodLabel = paymentMethodSelect ? paymentMethodSelect.options[paymentMethodSelect.selectedIndex]?.text : 'Pago Móvil';
                let splitDetails = {};

                if (rawPaymentMethod === 'split') {
                    const pmAmt = parseFloat(document.getElementById('budget-split-pagomovil')?.value) || 0;
                    const cashAmt = parseFloat(document.getElementById('budget-split-cash')?.value) || 0;
                    const zelleAmt = parseFloat(document.getElementById('budget-split-zelle')?.value) || 0;
                    const binanceAmt = parseFloat(document.getElementById('budget-split-binance')?.value) || 0;
                    const sumSplit = pmAmt + cashAmt + zelleAmt + binanceAmt;

                    if (sumSplit <= 0) {
                        Swal.fire({
                            icon: 'warning',
                            title: 'Distribución de Pago Incompleta',
                            text: 'Ha seleccionado "Pago Mixto", pero no ha distribuido los montos en los métodos de pago (Pago Móvil, Efectivo, Zelle o Binance).'
                        });
                        return;
                    }

                    const diff = Math.abs(totalUSD - sumSplit);
                    if (diff > 0.05) {
                        Swal.fire({
                            icon: 'warning',
                            title: 'Distribución Descuadrada',
                            text: `La suma de los montos en Pago Mixto ($${sumSplit.toFixed(2)} USD) no coincide con el total del presupuesto ($${totalUSD.toFixed(2)} USD). Por favor ajuste la distribución.`
                        });
                        return;
                    }

                    splitDetails = {
                        pagomovil: pmAmt,
                        cash: cashAmt,
                        zelle: zelleAmt,
                        binance: binanceAmt
                    };

                    const parts = [];
                    if (pmAmt > 0) parts.push(`Pago Móvil: $${pmAmt.toFixed(2)}`);
                    if (cashAmt > 0) parts.push(`Efectivo: $${cashAmt.toFixed(2)}`);
                    if (zelleAmt > 0) parts.push(`Zelle: $${zelleAmt.toFixed(2)}`);
                    if (binanceAmt > 0) parts.push(`Binance: $${binanceAmt.toFixed(2)}`);

                    paymentMethod = `Mixto (${parts.join(', ') || 'Sin distribución'})`;
                    paymentMethodLabel = paymentMethod;
                }
                
                const notes = document.getElementById('budget-notes').value;
                const consentText = document.getElementById('consent-text').value;

                let docSig = null;
                if (window.doctorSigPad && !window.doctorSigPad.isEmpty()) {
                    docSig = window.doctorSigPad.toDataURL();
                } else {
                    const currentUser = getCurrentUser();
                    docSig = currentUser ? ((currentUser.doctorProfile && currentUser.doctorProfile.signature) || (currentUser.doctor_profile && currentUser.doctor_profile.signature)) : null;
                }

                let patSig = null;
                if (window.patientSigPad && !window.patientSigPad.isEmpty()) {
                    patSig = window.patientSigPad.toDataURL();
                } else if (patient && patient.metadata && patient.metadata.patientSignature) {
                    patSig = patient.metadata.patientSignature;
                }

                // Generate or load budget invoice record ID
                const invoiceId = activeEditingBudgetId || `PRE-${Date.now().toString().slice(-6)}`;
                const approvedOdData = (window.odontogram ? window.odontogram.getData() : {});

                const invoiceObj = {
                    id: invoiceId,
                    patientId: patient.id,
                    invoiceDate: new Date().toISOString().split('T')[0],
                    paymentMethod: paymentMethod,
                    paymentTerms: paymentModeText,
                    currency: 'REF',
                    items: currentBudgetItems.map(item => ({
                        code: item.serviceCode,
                        name: item.name,
                        tooth: extractToothNumber(item),
                        face: item.face || 'Gnl',
                        price: item.price,
                        specialist: item.specialist || '',
                        assistant: item.assistant || ''
                    })),
                    odontogramData: { ...approvedOdData },
                    totalRef: totalUSD,
                    totalBcv: parseFloat(totalVES),
                    status: 'Aprobado',
                    doctorSignature: docSig,
                    patientSignature: patSig,
                    footerText: `Descuento global del ${discountPct}% aplicado. Ahorro: $${discountAmountUSD.toFixed(2)}.`,
                    metadata: {
                        consentText: consentText,
                        discountPct: discountPct,
                        paymentMethodCode: rawPaymentMethod,
                        splitDetails: splitDetails,
                        odontogramData: approvedOdData
                    }
                };

                // Save Invoice
                await SupabaseDataService.saveInvoice(invoiceObj);

                // Sync signatures, treatments and planned sessions to patient metadata
                if (!patient.metadata) patient.metadata = {};
                if (patSig) patient.metadata.patientSignature = patSig;
                if (docSig) patient.metadata.doctorSignature = docSig;
                patient.metadata.treatments = deduplicateBudgetItems(currentBudgetItems).map((item, idx) => ({
                    id: 'trt-' + (idx + 1),
                    serviceCode: item.serviceCode || '',
                    name: item.name,
                    tooth: extractToothNumber(item),
                    face: item.face || 'Gnl',
                    price: item.price,
                    specialist: item.specialist || '',
                    assistant: item.assistant || '',
                    status: 'Planificado',
                    sessionNum: item.sessionNum || (idx + 1)
                }));

                // Save official odontogram data and evolution history
                if (!patient.metadata.approvedOdontograms) {
                    patient.metadata.approvedOdontograms = [];
                }

                // If first approval, establish as Initial Diagnosis
                if (!patient.metadata.initialOdontogramData || Object.keys(patient.metadata.initialOdontogramData).length === 0) {
                    patient.metadata.initialOdontogramData = { ...approvedOdData };
                    patient.metadata.initialDiagnosisDate = invoiceObj.invoiceDate;
                }

                // Update cumulative official odontogram and push evolution snapshot
                patient.odontogramData = { ...(patient.odontogramData || {}), ...approvedOdData };
                patient.metadata.approvedOdontograms.push({
                    id: invoiceObj.id,
                    date: invoiceObj.invoiceDate,
                    totalUSD: totalUSD,
                    odontogramData: { ...approvedOdData },
                    treatments: deduplicateBudgetItems(currentBudgetItems)
                });
                patient.metadata.odontogramLastUpdated = invoiceObj.invoiceDate;

                // Set treatment plan overview
                const treatmentTitle = currentBudgetItems.map(i => i.name).slice(0, 3).join(' + ') + (currentBudgetItems.length > 3 ? '...' : '');
                patient.metadata.initialTreatmentPlan = {
                    treatmentName: treatmentTitle || 'Tratamiento Odontológico Integral',
                    totalSessions: Math.max(currentBudgetItems.length, (patient.metadata.initialTreatmentPlan && patient.metadata.initialTreatmentPlan.totalSessions) || 1),
                    interval: 'Quincenal'
                };

                // Save or update in patient clinical notes (prevent duplicates for same invoice)
                if (!patient.clinicalNotes) patient.clinicalNotes = [];
                const existingNoteIdx = patient.clinicalNotes.findIndex(n => n.content && n.content.includes(`(${invoiceObj.id})`));
                const noteObj = {
                    id: existingNoteIdx >= 0 ? patient.clinicalNotes[existingNoteIdx].id : 'note-' + Date.now(),
                    datetime: new Date().toISOString().slice(0, 16).replace('T', ' '),
                    content: `Presupuesto Aprobado y Certificado (${invoiceObj.id}). Subtotal: $${subtotalUSD.toFixed(2)}, Descuento: ${discountPct}% (-$${discountAmountUSD.toFixed(2)}), Total: $${totalUSD.toFixed(2)}. Método de pago: ${paymentMethodLabel}. Consentimiento: ${consentText}. Observaciones: ${notes}`,
                    paymentUSD: 0
                };
                if (existingNoteIdx >= 0) {
                    patient.clinicalNotes[existingNoteIdx] = noteObj;
                } else {
                    patient.clinicalNotes.unshift(noteObj);
                }

                // Save or update in patient payments history (prevent duplicates for same invoice)
                if (!patient.payments) patient.payments = [];
                const existingPayIdx = patient.payments.findIndex(p => p.concept && p.concept.includes(invoiceObj.id));
                const payObj = {
                    id: existingPayIdx >= 0 ? (patient.payments[existingPayIdx].id || 'pay-' + Date.now()) : 'pay-' + Date.now(),
                    date: invoiceObj.invoiceDate,
                    concept: `Presupuesto Aprobado ${invoiceObj.id}`,
                    totalUSD: totalUSD,
                    paidUSD: totalUSD,
                    balanceUSD: 0,
                    status: 'Pagado',
                    method: paymentMethod
                };
                if (existingPayIdx >= 0) {
                    patient.payments[existingPayIdx] = payObj;
                } else {
                    patient.payments.unshift(payObj);
                }

                if (patient.metadata) {
                    delete patient.metadata.draftBudget;
                    delete patient.metadata.draftOdontogramData;
                }
                await SupabaseDataService.savePatient(patient);

                // Auto-schedule and activate appointments for approved budget sessions
                try {
                    const allAppts = await SupabaseDataService.getAppointments();
                    const patientAppts = allAppts.filter(a => String(a.patientId) === String(patient.id));

                    // Activate any pending budget appointments to 'Programada'
                    for (const appt of patientAppts) {
                        if (appt.status === 'Pendiente Aprobación' || appt.status === 'Pendiente Aprobación Presupuesto') {
                            appt.status = 'Programada';
                            await SupabaseDataService.saveAppointment(appt);
                        }
                    }

                    // Create appointments for sessions in metadata.sessionsPlan if not yet created
                    const sessionsPlan = (patient.metadata && patient.metadata.sessionsPlan) || [];
                    if (sessionsPlan && sessionsPlan.length > 0) {
                        for (const session of sessionsPlan) {
                            if (session.date) {
                                const servicesText = session.services && session.services.length > 0
                                    ? session.services.map(s => `Pza ${s.tooth || 'Gnl'}: ${s.name}`).join(', ')
                                    : 'Tratamiento Planificado';
                                
                                const treatmentTitle = `Sesión ${session.sessionNumber}: ${servicesText}`;
                                const safeId = String(patient.id).replace(/[^a-zA-Z0-9]/g, '_');
                                const apptId = `appt-${safeId}-session-${session.sessionNumber}`;
                                
                                const existingAppt = patientAppts.find(a => a.id === apptId || (a.treatment && a.treatment.startsWith(`Sesión ${session.sessionNumber}:`)));
                                
                                const apptObj = {
                                    id: existingAppt ? existingAppt.id : apptId,
                                    patientId: patient.id,
                                    patientName: patient.fullname,
                                    date: session.date,
                                    time: session.time || "09:00 AM",
                                    treatment: treatmentTitle,
                                    status: "Programada",
                                    isTomorrow: false
                                };
                                await SupabaseDataService.saveAppointment(apptObj);
                            }
                        }
                    }
                    await renderAgendaView();
                } catch(e) {
                    console.error("Error auto-scheduling appointments for approved budget:", e);
                }

                // Reset editor state to zero
                currentBudgetItems = [];
                activeEditingBudgetId = null;
                setActivePatientId(null);
                if (window.odontogram) {
                    window.odontogram.setData({});
                }
                document.getElementById('budget-notes').value = '';
                document.getElementById('budget-discount-input').value = '0';
                if (window.doctorSigPad) window.doctorSigPad.clear();
                if (window.patientSigPad) window.patientSigPad.clear();
                if (window.dismissFloatingBudgetBubble) window.dismissFloatingBudgetBubble();

                await renderBudgetListView();

                Swal.fire({
                    icon: 'success',
                    title: '¡Presupuesto Aprobado y Certificado!',
                    text: `Se registró la transacción ${invoiceId} en el historial financiero y clínico del paciente.`,
                    timer: 3500,
                    showConfirmButton: true
                });
            } catch (err) {
                console.error("Error al aprobar presupuesto:", err);
                Swal.fire({ icon: 'error', title: 'Error de Guardado', text: 'No se pudo guardar la aprobación en la base de datos.' });
            } finally {
                window.isSavingBudget = false;
                approveBudgetBtn.disabled = false;
                approveBudgetBtn.innerHTML = origHtml;
            }
        };
    }

    const sendWpBtn = document.getElementById('btn-send-whatsapp');
    if (sendWpBtn) {
        sendWpBtn.onclick = async () => {
            const activeId = getActivePatientId();
            if (!activeId) {
                Swal.fire({ icon: 'info', title: 'Seleccione un paciente', text: 'Por favor active un paciente antes de enviar el presupuesto.' });
                return;
            }
            const patients = await SupabaseDataService.getPatients();
            const patient = patients.find(p => p.id === activeId);
            if (!patient) return;

            if (currentBudgetItems.length === 0) {
                Swal.fire({ icon: 'warning', title: 'Presupuesto vacío', text: 'Agregue al menos un tratamiento al presupuesto.' });
                return;
            }

            // Calculate totals
            let subtotalUSD = 0;
            currentBudgetItems.forEach(item => {
                subtotalUSD += item.price;
            });
            const discountPct = parseFloat(document.getElementById('budget-discount-input').value) || 0;
            const discountAmountUSD = subtotalUSD * (discountPct / 100);
            const totalUSD = subtotalUSD - discountAmountUSD;

            const paymentModeSelect = document.getElementById('payment-mode-select');
            const paymentModeText = paymentModeSelect.options[paymentModeSelect.selectedIndex].text;
            const paymentMethodSelect = document.getElementById('budget-payment-method');
            const paymentMethodLabel = paymentMethodSelect.options[paymentMethodSelect.selectedIndex].text;
            
            const notes = document.getElementById('budget-notes').value;
            const consentText = document.getElementById('consent-text').value;

            // VALIDAR QUE EL PRESUPUESTO ESTÉ APROBADO ANTES DE ENVIARLO
            let isApproved = false;
            if (activeEditingBudgetId) {
                const invoices = await SupabaseDataService.getInvoices();
                const inv = invoices.find(i => String(i.id) === String(activeEditingBudgetId));
                const st = String(inv?.status || '').toLowerCase();
                isApproved = st === 'aprobado' || st === 'approved' || st === 'facturado' || st === 'completada' || st === 'finalizado';
            }

            if (!isApproved) {
                Swal.fire({
                    icon: 'warning',
                    title: 'Presupuesto no Aprobado',
                    text: 'No se puede enviar el presupuesto al paciente por WhatsApp porque aún no ha sido Aprobado. Debe hacer clic en "Aprobar Presupuesto" antes de enviarlo.'
                });
                return;
            }

            const msg = WhatsAppService.generateBudgetMessage(patient, currentBudgetItems, totalUSD, paymentModeText, notes, subtotalUSD, discountPct, paymentMethodLabel, activeEditingBudgetId);
            WhatsAppService.sendToPatient(patient.phone, msg);
        };
    }

