window.selectedInterconsultaStudyKey = null;

window.selectInterconsultaStudy = function(studyKey, cardEl) {
    window.selectedInterconsultaStudyKey = studyKey;

    document.querySelectorAll('.study-accordion-card').forEach(card => {
        card.style.borderColor = 'var(--border-color)';
        card.style.background = 'var(--bg-card)';
        
        const radioIcon = card.querySelector('.study-radio-icon');
        if (radioIcon) {
            radioIcon.className = 'fa-solid fa-circle-dot study-radio-icon text-muted';
        }
        
        const badge = card.querySelector('.study-badge');
        if (badge) {
            badge.className = 'badge-tag gray study-badge';
            badge.innerText = 'Haga clic para seleccionar';
        }

        const pane = card.querySelector('.study-details-pane');
        if (pane) pane.classList.add('hidden');
    });

    if (cardEl) {
        cardEl.style.borderColor = '#10b981';
        cardEl.style.background = 'rgba(16, 185, 129, 0.04)';

        const radioIcon = cardEl.querySelector('.study-radio-icon');
        if (radioIcon) {
            radioIcon.className = 'fa-solid fa-circle-check study-radio-icon text-green';
        }

        const badge = cardEl.querySelector('.study-badge');
        if (badge) {
            badge.className = 'badge-tag green study-badge';
            badge.innerText = '✓ Seleccionado';
        }

        const pane = cardEl.querySelector('.study-details-pane');
        if (pane) pane.classList.remove('hidden');
    }
};

window.openInterconsultationModal = function() {
    const activeId = getActivePatientId();
    if (!activeId) {
        Swal.fire({ icon: 'warning', title: 'Seleccione Paciente', text: 'Por favor seleccione un paciente de la lista para abrir la interconsulta.' });
        return;
    }

    window.selectedInterconsultaStudyKey = null;
    document.querySelectorAll('.study-note-input').forEach(input => input.value = '');
    const notesEl = document.getElementById('interconsultation-notes');
    if (notesEl) notesEl.value = '';

    // Auto-select first study by default
    const firstCard = document.querySelector('.study-accordion-card');
    if (firstCard) {
        const studyKey = firstCard.dataset.studyKey;
        window.selectInterconsultaStudy(studyKey, firstCard);
    }

    // Bind Create Recipe button from Interconsultation modal
    const btnCreateRecipe = document.getElementById('btn-interconsultation-create-recipe');
    if (btnCreateRecipe) {
        btnCreateRecipe.onclick = async () => {
            if (!window.selectedInterconsultaStudyKey) {
                Swal.fire({ icon: 'warning', title: 'Seleccione un Estudio', text: 'Por favor haga clic en un estudio del acordeón para seleccionarlo.' });
                return;
            }

            const activeId = getActivePatientId();
            if (!activeId) return;

            // Open recipe modal
            await window.openRecipeModal(null, '');

            // Ensure the selected study is added to the select dropdown and selected
            const select = document.getElementById('recipe-treatment-select');
            if (select) {
                const studyOptVal = `Estudio Especial: ${window.selectedInterconsultaStudyKey}`;
                let existingOpt = Array.from(select.options).find(o => o.value === studyOptVal);
                if (!existingOpt) {
                    const opt = document.createElement('option');
                    opt.value = studyOptVal;
                    opt.innerText = studyOptVal;
                    select.appendChild(opt);
                }
                select.value = studyOptVal;
            }

            // Tailor notes and clinical indications for the study
            const notesInput = document.getElementById('recipe-general-notes');
            const indInput = document.getElementById('recipe-clinical-indications');

            if (notesInput) {
                notesInput.value = `Orden de examen para laboratorio / laboratorio de imágenes: Realizar ${window.selectedInterconsultaStudyKey}.`;
            }
            if (indInput) {
                indInput.value = `1. Acudir en ayunas (mínimo 8 horas de ayuno) para la toma de muestra de ${window.selectedInterconsultaStudyKey}.\n2. Evitar consumo de medicamentos anticoagulantes o aspirinas 24 horas antes del examen salvo indicación médica opuesta.\n3. Presentar esta orden e indicaciones al momento de realizar la prueba.`;
            }
        };
    }

    openModal('modal-interconsultation');
};

window.switchRecipeModalTab = function(mode) {
    const btnRecipe = document.getElementById('btn-recipe-tab-mode');
    const btnIndications = document.getElementById('btn-indications-tab-mode');
    const paneRecipe = document.getElementById('recipe-modal-pane-recipe');
    const paneIndications = document.getElementById('recipe-modal-pane-indications');

    if (mode === 'recipe') {
        if (btnRecipe) btnRecipe.classList.add('active');
        if (btnIndications) btnIndications.classList.remove('active');
        if (paneRecipe) paneRecipe.classList.remove('hidden');
        if (paneIndications) paneIndications.classList.add('hidden');
    } else {
        if (btnIndications) btnIndications.classList.add('active');
        if (btnRecipe) btnRecipe.classList.remove('active');
        if (paneIndications) paneIndications.classList.remove('hidden');
        if (paneRecipe) paneRecipe.classList.add('hidden');
    }
};

window.addRecipeRow = function(med = '', dose = '', freq = '') {
    const tbody = document.getElementById('recipe-medicines-tbody');
    if (!tbody) return;
    const tr = document.createElement('tr');
    tr.innerHTML = `
        <td><input type="text" class="form-input recipe-med-name" value="${med}" placeholder="ej: Amoxicilina 500mg" style="width:100%; font-size:0.85rem;"></td>
        <td><input type="text" class="form-input recipe-med-dose" value="${dose}" placeholder="ej: 1 cápsula cada 8 horas" style="width:100%; font-size:0.85rem;"></td>
        <td><input type="text" class="form-input recipe-med-freq" value="${freq}" placeholder="ej: Por 7 días" style="width:100%; font-size:0.85rem;"></td>
        <td style="text-align:center;"><button type="button" class="btn btn-xs btn-outline text-red" onclick="this.closest('tr').remove()"><i class="fa-solid fa-trash"></i></button></td>
    `;
    tbody.appendChild(tr);
};

window.openRecipeModal = async function(sessionNum = null, sessionTitle = '') {
    const activeId = getActivePatientId();
    if (!activeId) {
        Swal.fire({ icon: 'warning', title: 'Seleccione Paciente', text: 'Por favor seleccione un paciente.' });
        return;
    }

    const select = document.getElementById('recipe-treatment-select');
    if (select) {
        select.innerHTML = '<option value="General">General / Consulta Externa</option>';
        const patients = await SupabaseDataService.getPatients();
        const p = patients.find(pt => pt.id === activeId);
        if (p) {
            const meta = p.metadata || {};
            const trts = meta.treatments || [];
            trts.forEach((t, i) => {
                const opt = document.createElement('option');
                opt.value = `Sesión #${i + 1}: ${t.name || 'Procedimiento'} (${t.tooth || 'Gnl'})`;
                opt.innerText = opt.value;
                select.appendChild(opt);
            });
            if (p.sessions && p.sessions.length > 0) {
                p.sessions.forEach(s => {
                    const opt = document.createElement('option');
                    opt.value = `Sesión Realizada #${s.sessionNum}: ${s.procedure}`;
                    opt.innerText = opt.value;
                    select.appendChild(opt);
                });
            }
        }
        if (sessionNum && sessionTitle) {
            const matchingOpt = Array.from(select.options).find(o => o.value.includes(`Sesión #${sessionNum}`) || o.value.includes(sessionTitle));
            if (matchingOpt) select.value = matchingOpt.value;
        }
    }

    // Populate Doctor Selector with doctors list and licenses
    const doctorSelect = document.getElementById('recipe-doctor-select');
    if (doctorSelect) {
        doctorSelect.innerHTML = '';
        try {
            const users = await SupabaseDataService.getUsers();
            const doctors = users.filter(u => {
                const r = (u.role || '').toLowerCase();
                return r.includes('odont') || r.includes('medico') || r.includes('médico') || r.includes('especialista') || r.includes('cirujano') || r.includes('doctor') || (u.license && u.license !== 'N/A');
            });
            const targetDoctors = (doctors.length > 0) ? doctors : users;
            const currentUser = getCurrentUser();

            targetDoctors.forEach(doc => {
                const opt = document.createElement('option');
                opt.value = doc.id;
                const lic = (doc.license && doc.license !== 'N/A') ? ` (${doc.license})` : '';
                opt.innerText = `${doc.fullname} - ${doc.role || 'Odontólogo'}${lic}`;
                opt.dataset.doctorName = doc.fullname;
                opt.dataset.doctorRole = doc.role || 'Odontología General';
                opt.dataset.doctorLicense = (doc.license && doc.license !== 'N/A') ? doc.license : '';
                const docSig = (doc.doctorProfile && doc.doctorProfile.signature) || (doc.doctor_profile && doc.doctor_profile.signature) || '';
                opt.dataset.doctorSignature = docSig;

                if (currentUser && (currentUser.id === doc.id || currentUser.fullname === doc.fullname)) {
                    opt.selected = true;
                }
                doctorSelect.appendChild(opt);
            });
        } catch(e) {
            console.warn("Error loading doctors in recipe modal:", e);
        }
    }

    const tbody = document.getElementById('recipe-medicines-tbody');
    if (tbody) tbody.innerHTML = '';
    window.addRecipeRow('Amoxicilina 500mg', '1 cápsula c/8h', 'Por 7 días');
    window.addRecipeRow('Ibuprofeno 400mg', '1 tableta c/8h', 'Por 3 días (si hay dolor)');

    const notesEl = document.getElementById('recipe-general-notes');
    if (notesEl) notesEl.value = 'Tomar los medicamentos indicados strictly después de las comidas.';

    const indEl = document.getElementById('recipe-clinical-indications');
    if (indEl) indEl.value = '1. Reposo relativo durante las primeras 48 horas.\n2. Aplicar hielo local en la zona externa por lapsos de 15 minutos.\n3. Dieta blanda y fría. Evitar exponerse al sol o realizar esfuerzos físicos.';

    window.switchRecipeModalTab('recipe');
    openModal('modal-recipe-and-indications');
};

window.saveInterconsultationFull = async function() {
    const activeId = getActivePatientId();
    if (!activeId) {
        Swal.fire({ icon: 'warning', text: 'Seleccione un paciente' });
        return;
    }

    if (!window.selectedInterconsultaStudyKey) {
        Swal.fire({ icon: 'warning', title: 'Seleccione un Estudio', text: 'Por favor seleccione un estudio especial del acordeón.' });
        return;
    }

    const selectedCard = document.querySelector(`.study-accordion-card[data-study-key="${window.selectedInterconsultaStudyKey}"]`);
    const noteInput = selectedCard ? selectedCard.querySelector('.study-note-input') : null;
    const studyNote = noteInput ? noteInput.value.trim() : '';

    const notes = document.getElementById('interconsultation-notes') ? document.getElementById('interconsultation-notes').value.trim() : '';

    const patients = await SupabaseDataService.getPatients();
    const p = patients.find(pt => pt.id === activeId);
    if (p) {
        if (!p.metadata) p.metadata = {};
        if (!p.metadata.interconsultations) p.metadata.interconsultations = [];

        const record = {
            id: 'IC-' + Date.now().toString().slice(-6),
            date: new Date().toISOString().split('T')[0],
            studyName: window.selectedInterconsultaStudyKey,
            studies: [{ name: window.selectedInterconsultaStudyKey, note: studyNote }],
            notes: notes
        };

        p.metadata.interconsultations.unshift(record);
        await SupabaseDataService.savePatient(p);

        closeModal('modal-interconsultation');
        localStorage.setItem('dental_ehr_subtab', 'interconsultation');
        window.currentEHRSubtab = 'interconsultation';
        await renderEHRView();

        Swal.fire({
            icon: 'success',
            title: '¡Interconsulta Guardada!',
            text: `Solicitud de ${window.selectedInterconsultaStudyKey} registrada en el expediente.`,
            timer: 1800,
            showConfirmButton: false
        });
    }
};

window.saveRecipeAndIndicationsFinal = async function() {
    const activeId = getActivePatientId();
    if (!activeId) {
        Swal.fire({ icon: 'warning', text: 'Seleccione un paciente' });
        return;
    }

    const treatmentLinked = document.getElementById('recipe-treatment-select') ? document.getElementById('recipe-treatment-select').value : 'General';
    const medicines = [];
    document.querySelectorAll('#recipe-medicines-tbody tr').forEach(tr => {
        const med = tr.querySelector('.recipe-med-name') ? tr.querySelector('.recipe-med-name').value.trim() : '';
        const dose = tr.querySelector('.recipe-med-dose') ? tr.querySelector('.recipe-med-dose').value.trim() : '';
        const freq = tr.querySelector('.recipe-med-freq') ? tr.querySelector('.recipe-med-freq').value.trim() : '';
        if (med) {
            medicines.push({ med, dose, freq });
        }
    });

    const notes = document.getElementById('recipe-general-notes') ? document.getElementById('recipe-general-notes').value.trim() : '';
    const indications = document.getElementById('recipe-clinical-indications') ? document.getElementById('recipe-clinical-indications').value.trim() : '';

    // Capture selected doctor info
    const doctorSelect = document.getElementById('recipe-doctor-select');
    let selectedDoctorId = '';
    let selectedDoctorName = 'Dr. Odontólogo Especialista';
    let selectedDoctorRole = 'Odontología General';
    let selectedDoctorLicense = '';
    let selectedDoctorSignature = '';

    if (doctorSelect && doctorSelect.selectedIndex >= 0) {
        const opt = doctorSelect.options[doctorSelect.selectedIndex];
        selectedDoctorId = opt.value;
        selectedDoctorName = opt.dataset.doctorName || opt.text.split(' - ')[0];
        selectedDoctorRole = opt.dataset.doctorRole || 'Odontología General';
        selectedDoctorLicense = opt.dataset.doctorLicense || '';
        selectedDoctorSignature = opt.dataset.doctorSignature || '';
    } else {
        const currentUser = getCurrentUser();
        if (currentUser) {
            selectedDoctorId = currentUser.id;
            selectedDoctorName = currentUser.fullname;
            selectedDoctorRole = currentUser.role || 'Odontología General';
            selectedDoctorLicense = (currentUser.license && currentUser.license !== 'N/A') ? currentUser.license : '';
            selectedDoctorSignature = (currentUser.doctorProfile && currentUser.doctorProfile.signature) || (currentUser.doctor_profile && currentUser.doctor_profile.signature) || '';
        }
    }

    const patients = await SupabaseDataService.getPatients();
    const p = patients.find(pt => pt.id === activeId);
    if (p) {
        if (!p.metadata) p.metadata = {};
        if (!p.metadata.recipes) p.metadata.recipes = [];

        const recipeRecord = {
            id: 'REC-' + Date.now().toString().slice(-6),
            date: new Date().toISOString().split('T')[0],
            treatmentLinked,
            doctorId: selectedDoctorId,
            doctorName: selectedDoctorName,
            doctorRole: selectedDoctorRole,
            doctorLicense: selectedDoctorLicense,
            doctorSignature: selectedDoctorSignature,
            medicines,
            notes,
            indications
        };

        p.metadata.recipes.unshift(recipeRecord);
        await SupabaseDataService.savePatient(p);

        closeModal('modal-recipe-and-indications');
        if (document.getElementById('modal-interconsultation')) closeModal('modal-interconsultation');
        localStorage.setItem('dental_ehr_subtab', 'interconsultation');
        window.currentEHRSubtab = 'interconsultation';
        await renderEHRView();

        Swal.fire({
            icon: 'success',
            title: '¡Récipe e Indicaciones Guardados!',
            text: 'El récipe fue vinculado y registrado exitosamente.',
            timer: 1800,
            showConfirmButton: false
        });
    }
};

window.openRecipesModalForSession = async function(patientId, sessionNum, sessionTitle) {
    const patients = await SupabaseDataService.getPatients();
    const p = patients.find(pt => pt.id === patientId);
    if (!p) return;

    const recipes = (p.metadata && p.metadata.recipes) || [];
    const sessionRecipes = recipes.filter(r => (r.treatmentLinked && r.treatmentLinked.includes(`Sesión #${sessionNum}`)) || (sessionTitle && r.treatmentLinked.includes(sessionTitle)));

    const body = document.getElementById('session-recipes-view-body');
    if (!body) return;

    if (sessionRecipes.length === 0) {
        window.openRecipeModal(sessionNum, sessionTitle);
        return;
    }

    let html = '';
    sessionRecipes.forEach(r => {
        let medsHtml = r.medicines ? r.medicines.map(m => `<li><strong>${m.med}</strong>: ${m.dose} (${m.freq})</li>`).join('') : '';
        html += `
            <div style="background:var(--bg-main); border:1px solid var(--border-color); border-radius:8px; padding:15px; margin-bottom:12px;">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border-color); padding-bottom:8px; margin-bottom:10px;">
                    <span style="font-weight:700; color:#0d9488;"><i class="fa-solid fa-prescription"></i> ${r.id} (${r.date})</span>
                    <button class="btn btn-xs btn-outline" onclick="window.printSingleRecipePDF('${patientId}', '${r.id}')"><i class="fa-solid fa-file-pdf text-red"></i> Imprimir PDF</button>
                </div>
                <div style="font-size:0.85rem; color:var(--text-main);">
                    <div><strong>Tratamiento Vinculado:</strong> ${r.treatmentLinked}</div>
                    ${r.doctorName ? `<div><strong>Médico:</strong> Dr(a). ${r.doctorName} ${r.doctorLicense ? `(${r.doctorLicense})` : ''}</div>` : ''}
                    ${medsHtml ? `<div style="margin-top:6px;"><strong>Medicamentos Prescritos:</strong><ul style="margin:4px 0; padding-left:20px;">${medsHtml}</ul></div>` : ''}
                    ${r.notes ? `<div style="margin-top:4px;"><strong>Notas:</strong> ${r.notes}</div>` : ''}
                    ${r.indications ? `<div style="margin-top:6px; background:rgba(2,132,199,0.05); padding:8px; border-radius:6px; border:1px solid rgba(2,132,199,0.2);"><strong>Indicaciones Clínicas:</strong><br>${r.indications.replace(/\n/g, '<br>')}</div>` : ''}
                </div>
            </div>
        `;
    });

    body.innerHTML = html;

    const btnNew = document.getElementById('btn-create-new-recipe-for-session');
    if (btnNew) {
        btnNew.onclick = () => {
            closeModal('modal-view-session-recipes');
            window.openRecipeModal(sessionNum, sessionTitle);
        };
    }

    openModal('modal-view-session-recipes');
};

window.printSingleRecipePDF = async function(patientId, recipeId = null) {
    const patients = await SupabaseDataService.getPatients();
    const p = patients.find(pt => pt.id === patientId);
    if (!p) return;

    const meta = p.metadata || {};
    const recipes = meta.recipes || [];
    let recipe = recipeId ? recipes.find(r => r.id === recipeId) : recipes[0];

    // If no saved recipe exists in history, build one from modal inputs if open
    if (!recipe) {
        const treatmentLinked = document.getElementById('recipe-treatment-select') ? document.getElementById('recipe-treatment-select').value : 'General';
        const medicines = [];
        document.querySelectorAll('#recipe-medicines-tbody tr').forEach(tr => {
            const med = tr.querySelector('.recipe-med-name') ? tr.querySelector('.recipe-med-name').value.trim() : '';
            const dose = tr.querySelector('.recipe-med-dose') ? tr.querySelector('.recipe-med-dose').value.trim() : '';
            const freq = tr.querySelector('.recipe-med-freq') ? tr.querySelector('.recipe-med-freq').value.trim() : '';
            if (med) medicines.push({ med, dose, freq });
        });
        const notes = document.getElementById('recipe-general-notes') ? document.getElementById('recipe-general-notes').value.trim() : '';
        const indications = document.getElementById('recipe-clinical-indications') ? document.getElementById('recipe-clinical-indications').value.trim() : '';
        
        const doctorSelect = document.getElementById('recipe-doctor-select');
        let selDocName = '';
        let selDocRole = '';
        let selDocLic = '';
        let selDocSig = '';
        if (doctorSelect && doctorSelect.selectedIndex >= 0) {
            const opt = doctorSelect.options[doctorSelect.selectedIndex];
            selDocName = opt.dataset.doctorName || opt.text.split(' - ')[0];
            selDocRole = opt.dataset.doctorRole || 'Odontología General';
            selDocLic = opt.dataset.doctorLicense || '';
            selDocSig = opt.dataset.doctorSignature || '';
        }

        recipe = {
            id: 'REC-' + Date.now().toString().slice(-6),
            date: new Date().toISOString().split('T')[0],
            treatmentLinked,
            doctorName: selDocName,
            doctorRole: selDocRole,
            doctorLicense: selDocLic,
            doctorSignature: selDocSig,
            medicines,
            notes,
            indications
        };
    }

    const config = await SupabaseDataService.getStationeryConfig();
    const headerText = config.headerText || 'Clínica Odontológica Especializada';
    const logoUrl = config.logoUrl || config.logo_url || '';
    const recipeFooter = config.recipeFooterText || config.footerText || 'Documento Clínico Oficial de Prescripción Médica para el Paciente.';

    const users = await SupabaseDataService.getUsers();
    let docUser = null;
    if (recipe && recipe.doctorId) {
        docUser = users.find(u => u.id === recipe.doctorId);
    }
    if (!docUser && recipe && recipe.doctorName) {
        docUser = users.find(u => u.fullname === recipe.doctorName);
    }
    if (!docUser) {
        const currentUser = getCurrentUser();
        if (currentUser) docUser = currentUser;
    }

    const docName = (recipe && recipe.doctorName) || (docUser ? docUser.fullname : 'Dr. Odontólogo Especialista');
    const docSpecialty = (recipe && recipe.doctorRole) || (docUser ? docUser.role : 'Odontología General');
    const docLicense = (recipe && recipe.doctorLicense) || (docUser && docUser.license && docUser.license !== 'N/A' ? docUser.license : 'MPPS-98402 / C.O.V-20104');
    
    let docSignature = (recipe && recipe.doctorSignature) || '';
    if (!docSignature && docUser) {
        docSignature = (docUser.doctorProfile && docUser.doctorProfile.signature) || (docUser.doctor_profile && docUser.doctor_profile.signature) || '';
    }
    if (!docSignature && config && (config.doctorSignature || config.doctor_signature)) {
        docSignature = config.doctorSignature || config.doctor_signature;
    }

    const clinicBusData = getClinicBusData(config);

    const docHtml = buildRecipeDocumentHTML({
        docTitle: 'Prescripción Médica y Récipe',
        emissionDate: recipe ? recipe.date : new Date().toISOString().split('T')[0],
        controlNumber: recipe ? recipe.id : 'REC-001',
        treatmentLinked: recipe ? (recipe.treatmentLinked || 'General') : 'General',
        clinicName: clinicBusData.name || headerText,
        clinicPhone: clinicBusData.phone || '',
        clinicAddress: clinicBusData.address || '',
        logoUrl: logoUrl,
        doctorName: docName,
        doctorSpecialty: docSpecialty,
        doctorLicense: docLicense,
        doctorPhone: (docUser && docUser.phone) || clinicBusData.phone || '',
        doctorSig: docSignature,
        patientName: p.fullname,
        patientId: p.id,
        patientPhone: p.phone || '',
        medicines: recipe ? (recipe.medicines || []) : [],
        notes: recipe ? (recipe.notes || '') : '',
        indications: recipe ? (recipe.indications || '') : '',
        footerNote: recipeFooter
    });

    const container = document.createElement('div');
    container.innerHTML = docHtml;
    const filename = `Recipe_${recipe ? recipe.id : 'Prescripcion'}_${p.fullname.replace(/\s+/g, '_')}.pdf`;
    await generatePDFFromElement(container, filename);
};

window.sendRecipeWhatsApp = async function(patientId, recipeId = null) {
    const patients = await SupabaseDataService.getPatients();
    const patient = patients.find(pt => pt.id === patientId);
    if (!patient || !patient.phone) {
        Swal.fire({ icon: 'warning', title: 'Sin WhatsApp', text: 'El paciente no tiene un número de teléfono / WhatsApp registrado.' });
        return;
    }

    const meta = patient.metadata || {};
    const recipes = meta.recipes || [];
    let recipe = recipeId ? recipes.find(r => r.id === recipeId) : recipes[0];

    if (!recipe) {
        const treatmentLinked = document.getElementById('recipe-treatment-select') ? document.getElementById('recipe-treatment-select').value : 'General';
        const medicines = [];
        document.querySelectorAll('#recipe-medicines-tbody tr').forEach(tr => {
            const med = tr.querySelector('.recipe-med-name') ? tr.querySelector('.recipe-med-name').value.trim() : '';
            const dose = tr.querySelector('.recipe-med-dose') ? tr.querySelector('.recipe-med-dose').value.trim() : '';
            const freq = tr.querySelector('.recipe-med-freq') ? tr.querySelector('.recipe-med-freq').value.trim() : '';
            if (med) medicines.push({ med, dose, freq });
        });
        const notes = document.getElementById('recipe-general-notes') ? document.getElementById('recipe-general-notes').value.trim() : '';
        const indications = document.getElementById('recipe-clinical-indications') ? document.getElementById('recipe-clinical-indications').value.trim() : '';

        recipe = {
            id: 'REC-' + Date.now().toString().slice(-6),
            date: new Date().toISOString().split('T')[0],
            treatmentLinked,
            medicines,
            notes,
            indications
        };
    }

    const recipeUrl = `${window.location.origin}/?patientId=${patient.id}&view=recipe&recipeId=${recipe.id}`;
    const msg = WhatsAppService.generateRecipeMessage(patient, recipe, recipeUrl);
    WhatsAppService.sendToPatient(patient.phone, msg);
};

